css:
.dex-scorecard {
  --dex-scorecard-bg: oklch(0.972 0.012 88);
  --dex-scorecard-ink: oklch(0.22 0.018 60);
  --dex-scorecard-accent: oklch(0.8 0.15 84);
  --dex-scorecard-good: oklch(0.5 0.085 165);
  --dex-scorecard-risk: oklch(0.64 0.13 68);
  --dex-scorecard-bad: oklch(0.55 0.16 32);
  --dex-scorecard-card: color-mix(in oklch, var(--dex-scorecard-bg) 45%, white);
  --dex-scorecard-line: color-mix(in oklch, var(--dex-scorecard-ink) 12%, transparent);
  --dex-scorecard-soft: color-mix(in oklch, var(--dex-scorecard-ink) 5%, transparent);
  --dex-scorecard-mute: color-mix(in oklch, var(--dex-scorecard-ink) 64%, var(--dex-scorecard-bg));
  --dex-scorecard-faint: color-mix(in oklch, var(--dex-scorecard-ink) 42%, var(--dex-scorecard-bg));
  --dex-scorecard-glow: color-mix(in oklch, var(--dex-scorecard-accent) 30%, transparent);
  --dex-scorecard-sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --dex-scorecard-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --dex-scorecard-out: cubic-bezier(.16, 1, .3, 1);
  --dex-scorecard-spring: linear(0, .006, .025 2.8%, .101 6.1%, .539 18.9%, .721 25.3%, .849 31.5%, .937 38.1%, .968 41.8%, .991 45.7%, 1.006 50.1%, 1.015 55%, 1.017 63.9%, 1.001);
  width: 100%;
  height: var(--dex-scorecard-h, 680px);
  container-type: inline-size;
  position: relative; isolation: isolate; overflow: hidden;
  border-radius: 18px;
  background: var(--dex-scorecard-bg);
  color: var(--dex-scorecard-ink);
  font: 13px/1.45 var(--dex-scorecard-sans);
  accent-color: var(--dex-scorecard-ink);
  scrollbar-width: thin;
  scrollbar-color: color-mix(in oklch, var(--dex-scorecard-ink) 20%, transparent) transparent;
  box-shadow: inset 0 0 0 1px var(--dex-scorecard-line);
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, h3, p, ul, li) { margin: 0; padding: 0; }
  & :where(ul) { list-style: none; }
  & :where(button) { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; text-align: inherit; }
  & :focus-visible { outline: 2px solid var(--dex-scorecard-ink); outline-offset: 2px; border-radius: 8px; }
  & [hidden] { display: none !important; }
}
.dex-scorecard__ic { width: 18px; height: 18px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }
.dex-scorecard__shell { height: 100%; display: grid; grid-template-columns: 208px minmax(0, 1fr); }

/* ---------------------------------------------------------------- sidebar */
.dex-scorecard__side {
  display: flex; flex-direction: column; gap: 6px; padding: 20px 14px 16px; min-height: 0; overflow: auto;
  border-right: 1px solid var(--dex-scorecard-line);
  background: color-mix(in oklch, var(--dex-scorecard-bg) 94%, var(--dex-scorecard-ink));
}
.dex-scorecard__brand {
  display: flex; align-items: center; gap: 10px; padding: 0 6px 18px;
  font-weight: 760; font-size: 16px; letter-spacing: -.03em;
  & svg { width: 30px; height: 30px; padding: 6px; border-radius: 9px; flex: none; background: var(--dex-scorecard-ink); fill: none; stroke: var(--dex-scorecard-accent); stroke-width: 2.4; stroke-linecap: round; stroke-linejoin: round; }
  & small { display: block; font-size: 11px; font-weight: 500; letter-spacing: 0; color: var(--dex-scorecard-mute); }
}
.dex-scorecard__nav {
  display: grid; gap: 2px;
  & button {
    position: relative; display: flex; align-items: center; gap: 10px; padding: 9px 10px; border-radius: 10px;
    color: var(--dex-scorecard-mute); font-weight: 550; transition: background-color .2s, color .2s;
    &:hover { background: var(--dex-scorecard-soft); color: var(--dex-scorecard-ink); }
    &[aria-current="page"] { background: var(--dex-scorecard-card); color: var(--dex-scorecard-ink); font-weight: 650; box-shadow: 0 1px 0 var(--dex-scorecard-line), 0 8px 18px -12px color-mix(in oklch, var(--dex-scorecard-ink) 45%, transparent); }
    &[aria-current="page"]::before { content: ""; position: absolute; left: -14px; top: 9px; bottom: 9px; width: 3px; border-radius: 0 3px 3px 0; background: var(--dex-scorecard-accent); }
  }
}
.dex-scorecard__meet {
  margin-top: auto; padding: 14px 8px 0; border-top: 1px solid var(--dex-scorecard-line);
  color: var(--dex-scorecard-mute); font-size: 12px; text-wrap: pretty;
}
.dex-scorecard__date { font-size: 15px; font-weight: 700; letter-spacing: -.02em; color: var(--dex-scorecard-ink); margin: 2px 0 4px !important; }
.dex-scorecard__share {
  display: flex; align-items: center; justify-content: center; gap: 8px; margin-top: 10px; width: 100%; padding: 9px 10px; border-radius: 10px;
  background: var(--dex-scorecard-ink); color: var(--dex-scorecard-bg) !important; font-weight: 650; font-size: 12.5px;
  transition: transform .25s var(--dex-scorecard-out), background-color .2s;
  &:hover { background: color-mix(in oklch, var(--dex-scorecard-ink) 86%, var(--dex-scorecard-accent)); }
  &:active { transform: scale(.97); }
  & .dex-scorecard__ic { width: 16px; height: 16px; color: var(--dex-scorecard-accent); }
}
.dex-scorecard__cap { font-size: 10.5px; font-weight: 700; letter-spacing: .12em; text-transform: uppercase; color: var(--dex-scorecard-faint); }

/* ---------------------------------------------------------------- main */
.dex-scorecard__main { min-width: 0; min-height: 0; display: grid; grid-template-rows: auto minmax(0, 1fr); gap: 14px; padding: 18px 20px 18px; }
.dex-scorecard__head { display: flex; align-items: end; justify-content: space-between; gap: 12px 20px; flex-wrap: wrap; }
.dex-scorecard__eyebrow { font-size: 11px; font-weight: 650; letter-spacing: .1em; text-transform: uppercase; color: var(--dex-scorecard-faint); }
.dex-scorecard__title h2 { font-size: clamp(19px, 2.3cqi, 26px); font-weight: 780; letter-spacing: -.035em; line-height: 1.12; text-wrap: balance; }

.dex-scorecard__scrub {
  position: relative; display: grid; grid-template-columns: repeat(8, minmax(0, 1fr)); padding: 4px; border-radius: 13px;
  width: min(100%, 480px); background: var(--dex-scorecard-soft); box-shadow: inset 0 0 0 1px var(--dex-scorecard-line);
  & button {
    position: relative; z-index: 1; display: grid; justify-items: center; padding: 5px 0 6px; border-radius: 9px;
    color: var(--dex-scorecard-mute); transition: color .25s;
    & b { font-size: 12.5px; font-weight: 700; letter-spacing: -.01em; font-variant-numeric: tabular-nums; }
    & small { font-size: 10px; font-family: var(--dex-scorecard-mono); color: var(--dex-scorecard-faint); }
    &:hover { color: var(--dex-scorecard-ink); }
    &[aria-checked="true"] { color: var(--dex-scorecard-bg); }
    &[aria-checked="true"] small { color: color-mix(in oklch, var(--dex-scorecard-bg) 70%, transparent); }
    &.yr::before { content: ""; position: absolute; left: -1px; top: 9px; bottom: 9px; width: 1px; background: var(--dex-scorecard-line); }
  }
}
.dex-scorecard__thumb {
  position: absolute; left: 4px; top: 4px; bottom: 4px; width: calc((100% - 8px) / 8); border-radius: 9px;
  background: var(--dex-scorecard-ink);
  box-shadow: 0 6px 14px -6px color-mix(in oklch, var(--dex-scorecard-ink) 70%, transparent), inset 0 -2px 0 var(--dex-scorecard-accent);
  transform: translateX(calc(var(--q, 7) * 100%));
  transition: transform .6s var(--dex-scorecard-spring);
}

.dex-scorecard__view { min-height: 0; overflow: auto; scrollbar-width: thin; margin: 0 -6px; padding: 0 6px 4px; }
.dex-scorecard__panel {
  position: relative; min-width: 0; border-radius: 16px; background: var(--dex-scorecard-card);
  box-shadow: inset 0 0 0 1px var(--dex-scorecard-line), 0 18px 36px -32px color-mix(in oklch, var(--dex-scorecard-ink) 70%, transparent);
  animation: dex-scorecard-rise .7s var(--dex-scorecard-out) both; animation-delay: calc(var(--i, 0) * 70ms);
}

/* score view */
.dex-scorecard__view[data-view="score"] {
  display: grid; gap: 12px; align-content: start;
  grid-template-columns: minmax(0, 1.55fr) minmax(0, 1fr);
  grid-template-rows: max-content max-content;
  grid-template-areas: "hero sum" "tiles tiles";
}
.dex-scorecard__hero { grid-area: hero; display: grid; grid-template-columns: minmax(150px, .8fr) minmax(0, 1.4fr); gap: 6px; padding: 16px 12px 10px 18px; min-height: 190px; }
.dex-scorecard__big { font-size: clamp(34px, 4.6cqi, 52px); font-weight: 780; letter-spacing: -.05em; line-height: 1; margin: 10px 0 8px !important; font-variant-numeric: tabular-nums; }
.dex-scorecard__herosub { font-size: 12.5px; color: var(--dex-scorecard-mute); text-wrap: pretty; font-variant-numeric: tabular-nums; & b { color: var(--dex-scorecard-ink); font-weight: 650; } & .up { color: var(--dex-scorecard-good); } & .dn { color: var(--dex-scorecard-bad); } }
.dex-scorecard__plot { position: relative; min-height: 0; min-width: 0; }
.dex-scorecard__hero .dex-scorecard__plot { min-height: 160px; }
.dex-scorecard__chart {
  position: absolute; inset: 0; width: 100%; height: 100%; display: block; overflow: visible; cursor: crosshair;
  & text { font: 10px var(--dex-scorecard-mono); fill: var(--dex-scorecard-faint); font-variant-numeric: tabular-nums; }
  & .gl { stroke: var(--dex-scorecard-line); }
  & .base { stroke: color-mix(in oklch, var(--dex-scorecard-ink) 30%, transparent); }
  & .band { fill: var(--dex-scorecard-glow); transition: transform .55s var(--dex-scorecard-spring); }
  & .area { fill: url(#dex-scorecard-g); }
  & .act { fill: none; stroke: var(--dex-scorecard-ink); stroke-width: 2.2; stroke-linejoin: round; stroke-linecap: round; }
  & .plan { fill: none; stroke: color-mix(in oklch, var(--dex-scorecard-ink) 45%, transparent); stroke-width: 1.4; stroke-dasharray: 4 4; }
  & .pt { fill: var(--dex-scorecard-card); stroke: var(--dex-scorecard-ink); stroke-width: 1.8; }
  & .pt.sel { fill: var(--dex-scorecard-accent); r: 5.5px; }
  & .xl.sel { fill: var(--dex-scorecard-ink); font-weight: 700; }
  & .hl { stroke: var(--dex-scorecard-ink); stroke-width: 1; stroke-dasharray: 2 3; opacity: 0; }
  & .hp { fill: var(--dex-scorecard-ink); opacity: 0; }
  &.hov .hl, &.hov .hp { opacity: 1; }
  & .vl { font: 650 10.5px var(--dex-scorecard-sans); fill: var(--dex-scorecard-ink); }
}
.dex-scorecard__chart.enter {
  & .act { stroke-dasharray: 1 1; stroke-dashoffset: 1; animation: dex-scorecard-draw 1.1s var(--dex-scorecard-out) .15s forwards; }
  & .plan { animation: dex-scorecard-fade .9s ease-out .1s both; }
  & .area { animation: dex-scorecard-wipe 1.1s var(--dex-scorecard-out) .15s both; }
  & .pt { transform-box: fill-box; transform-origin: center; animation: dex-scorecard-pop .5s var(--dex-scorecard-spring) both; animation-delay: calc(200ms + var(--i) * 70ms); }
}

.dex-scorecard__sum { grid-area: sum; padding: 16px 18px; display: flex; flex-direction: column; gap: 12px; }
.dex-scorecard__counts {
  display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 8px;
  & div { padding: 8px 10px; border-radius: 11px; background: var(--dex-scorecard-soft); }
  & b { display: block; font-size: 24px; font-weight: 760; letter-spacing: -.04em; line-height: 1.1; font-variant-numeric: tabular-nums; }
  & span { display: flex; align-items: center; gap: 6px; font-size: 11.5px; color: var(--dex-scorecard-mute); white-space: nowrap; }
  & i { flex: none; width: 8px; height: 8px; border-radius: 50%; background: var(--c); }
}
.dex-scorecard__notes {
  display: grid; gap: 7px; font-size: 12.5px; color: var(--dex-scorecard-mute); text-wrap: pretty;
  & li { position: relative; padding-left: 14px; animation: dex-scorecard-rise .5s var(--dex-scorecard-out) both; animation-delay: calc(var(--i, 0) * 60ms); }
  & li::before { content: ""; position: absolute; left: 0; top: .6em; width: 6px; height: 6px; border-radius: 2px; background: var(--c, var(--dex-scorecard-faint)); }
  & b { color: var(--dex-scorecard-ink); font-weight: 650; font-variant-numeric: tabular-nums; }
}

.dex-scorecard__tiles { grid-area: tiles; display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); grid-auto-rows: auto auto auto 46px; gap: 0 12px; }
.dex-scorecard__tile {
  grid-row: span 4; display: grid; grid-template-rows: subgrid; row-gap: 2px; margin-bottom: 12px; padding: 13px 14px 10px; border-radius: 15px;
  background: var(--dex-scorecard-card); box-shadow: inset 0 0 0 1px var(--dex-scorecard-line);
  transition: box-shadow .25s, transform .35s var(--dex-scorecard-out);
  animation: dex-scorecard-rise .65s var(--dex-scorecard-out) both; animation-delay: calc(140ms + var(--i, 0) * 45ms);
  &:hover { transform: translateY(-2px); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--dex-scorecard-ink) 30%, transparent), 0 14px 26px -18px color-mix(in oklch, var(--dex-scorecard-ink) 60%, transparent); }
  &:active { transform: translateY(0) scale(.985); }
  & .th { display: flex; align-items: center; justify-content: space-between; gap: 8px; font-size: 12px; font-weight: 600; color: var(--dex-scorecard-mute); }
  & .tn { min-width: 0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .tv { font-size: clamp(20px, 2.3cqi, 27px); font-weight: 760; letter-spacing: -.04em; line-height: 1.15; font-variant-numeric: tabular-nums; }
  & .td { font-size: 11.5px; color: var(--dex-scorecard-mute); font-variant-numeric: tabular-nums; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .td .up { color: var(--dex-scorecard-good); font-weight: 650; }
  & .td .dn { color: var(--dex-scorecard-bad); font-weight: 650; }
  & svg { width: 100%; height: 46px; display: block; overflow: visible; margin-top: 4px; }
  & .sp { fill: none; stroke: var(--dex-scorecard-ink); stroke-width: 1.6; stroke-linejoin: round; }
  & .spp { fill: none; stroke: color-mix(in oklch, var(--dex-scorecard-ink) 35%, transparent); stroke-width: 1; stroke-dasharray: 2 3; }
  & .spd { fill: var(--dex-scorecard-accent); stroke: var(--dex-scorecard-ink); stroke-width: 1.4; transition: transform .55s var(--dex-scorecard-spring); }
}
.dex-scorecard__chip {
  display: inline-flex; align-items: center; gap: 5px; padding: 2px 7px 2px 6px; border-radius: 999px; font-size: 10.5px; font-weight: 700; letter-spacing: .02em;
  color: color-mix(in oklch, var(--c) 82%, var(--dex-scorecard-ink)); background: color-mix(in oklch, var(--c) 13%, transparent); white-space: nowrap;
  &::before { content: ""; width: 6px; height: 6px; border-radius: 50%; background: var(--c); }
}
.dex-scorecard [data-s="ok"] { --c: var(--dex-scorecard-good); }
.dex-scorecard [data-s="risk"] { --c: var(--dex-scorecard-risk); }
.dex-scorecard [data-s="off"] { --c: var(--dex-scorecard-bad); }

/* trend view */
.dex-scorecard__view[data-view="trend"] {
  display: grid; gap: 12px; grid-template-columns: minmax(0, 1fr) 250px; grid-template-rows: auto minmax(300px, 1fr);
  grid-template-areas: "pills pills" "chart list";
}
.dex-scorecard__pills {
  grid-area: pills; display: flex; gap: 6px; flex-wrap: wrap;
  & button {
    padding: 6px 11px; border-radius: 999px; font-size: 12px; font-weight: 600; color: var(--dex-scorecard-mute);
    box-shadow: inset 0 0 0 1px var(--dex-scorecard-line); transition: background-color .2s, color .2s, box-shadow .2s;
    animation: dex-scorecard-rise .45s var(--dex-scorecard-out) both; animation-delay: calc(var(--i, 0) * 30ms);
    &:hover { color: var(--dex-scorecard-ink); background: var(--dex-scorecard-soft); }
    &[aria-checked="true"] { background: var(--dex-scorecard-ink); color: var(--dex-scorecard-bg); box-shadow: none; }
  }
}
.dex-scorecard__tpanel { grid-area: chart; display: flex; flex-direction: column; padding: 16px 16px 12px; min-height: 0; }
.dex-scorecard__tphead {
  display: flex; justify-content: space-between; gap: 12px; flex-wrap: wrap; margin-bottom: 10px;
  & h3 { font-size: 16px; font-weight: 720; letter-spacing: -.02em; text-wrap: balance; }
  & p { font-size: 12px; color: var(--dex-scorecard-mute); text-wrap: pretty; }
}
.dex-scorecard__legend {
  display: flex; gap: 14px; font-size: 11.5px; color: var(--dex-scorecard-mute); align-items: center;
  & span { display: inline-flex; align-items: center; gap: 6px; }
  & b { font-weight: 500; }
  & i { width: 16px; height: 0; border-top: 2px solid var(--dex-scorecard-ink); }
  & i.p { border-top: 1.5px dashed color-mix(in oklch, var(--dex-scorecard-ink) 50%, transparent); }
}
.dex-scorecard__tpanel .dex-scorecard__plot { flex: 1; }
.dex-scorecard__qlist {
  grid-area: list; padding: 14px 10px 10px; display: flex; flex-direction: column; gap: 8px; min-height: 0; overflow: auto;
  & .dex-scorecard__cap { padding: 0 6px; }
  & [role="listbox"] { display: grid; gap: 2px; }
  & [role="option"] {
    display: grid; grid-template-columns: 54px 1fr auto; align-items: center; gap: 8px; padding: 7px 8px; border-radius: 9px; cursor: pointer;
    font-variant-numeric: tabular-nums; font-size: 12.5px; transition: background-color .18s;
    animation: dex-scorecard-rise .45s var(--dex-scorecard-out) both; animation-delay: calc(var(--i, 0) * 35ms);
    & .q { font-weight: 650; }
    & .v { font-weight: 650; text-align: right; }
    & .var { font-size: 11px; min-width: 52px; text-align: right; font-weight: 650; color: var(--c); }
    &:hover { background: var(--dex-scorecard-soft); }
    &[aria-selected="true"] { background: color-mix(in oklch, var(--dex-scorecard-accent) 26%, var(--dex-scorecard-card)); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--dex-scorecard-accent) 60%, transparent); }
  }
}

/* table view */
.dex-scorecard__view[data-view="table"] { display: flex; flex-direction: column; gap: 10px; overflow: hidden; }
.dex-scorecard__tbar { display: flex; align-items: center; justify-content: space-between; gap: 10px; flex-wrap: wrap; & .dex-scorecard__cap { letter-spacing: .02em; text-transform: none; font-weight: 500; font-size: 12px; color: var(--dex-scorecard-mute); text-wrap: pretty; } }
.dex-scorecard__seg {
  display: inline-flex; padding: 3px; border-radius: 11px; background: var(--dex-scorecard-soft); box-shadow: inset 0 0 0 1px var(--dex-scorecard-line);
  & button { padding: 5px 11px; border-radius: 8px; font-size: 12px; font-weight: 600; color: var(--dex-scorecard-mute); transition: background-color .2s, color .2s; }
  & button:hover { color: var(--dex-scorecard-ink); }
  & button[aria-checked="true"] { background: var(--dex-scorecard-card); color: var(--dex-scorecard-ink); box-shadow: 0 1px 2px color-mix(in oklch, var(--dex-scorecard-ink) 20%, transparent); }
}
.dex-scorecard__tablewrap { flex: 0 1 auto; min-height: 0; overflow: auto; scrollbar-width: thin; animation: none; }
.dex-scorecard__table {
  width: 100%; border-collapse: separate; border-spacing: 0; font-variant-numeric: tabular-nums; font-size: 12.5px;
  & th, & td { padding: 0; text-align: right; white-space: nowrap; border-bottom: 1px solid var(--dex-scorecard-line); }
  & thead th { position: sticky; top: 0; z-index: 2; background: var(--dex-scorecard-card); font-weight: 600; font-size: 11.5px; color: var(--dex-scorecard-mute); }
  & thead th > span, & thead th > button { display: block; padding: 10px 10px 8px; }
  & thead button { width: 100%; text-align: right; border-radius: 0; transition: color .2s, background-color .2s; }
  & thead button:hover { color: var(--dex-scorecard-ink); background: var(--dex-scorecard-soft); }
  & thead button[aria-current="true"] { color: var(--dex-scorecard-ink); box-shadow: inset 0 -2px 0 var(--dex-scorecard-accent); }
  & th:first-child, & td:first-child { position: sticky; left: 0; z-index: 1; text-align: left; background: var(--dex-scorecard-card); }
  & thead th:first-child { z-index: 3; }
  & td { padding: 9px 10px; }
  & td:first-child { font-weight: 650; padding-left: 14px; min-width: 160px; }
  & td.c { background: color-mix(in oklch, var(--c) calc(var(--t) * 22%), transparent); }
  & td.c.sel { box-shadow: inset 2px 0 0 var(--dex-scorecard-accent), inset -2px 0 0 var(--dex-scorecard-accent); font-weight: 700; }
  & tbody tr { cursor: pointer; transition: background-color .15s; }
  & tbody tr:hover td { background-color: var(--dex-scorecard-soft); }
  & tbody tr:hover td.c { background: color-mix(in oklch, var(--c) calc(var(--t) * 22% + 6%), transparent); }
  & tbody tr:focus-visible { outline-offset: -2px; }
  & tbody tr:last-child td { border-bottom: 0; }
}

/* overlays */
.dex-scorecard__tip {
  position: absolute; left: 0; top: 0; z-index: 30; pointer-events: none; min-width: 170px; padding: 9px 11px; border-radius: 11px;
  background: var(--dex-scorecard-ink); color: var(--dex-scorecard-bg); font-size: 12px; line-height: 1.5;
  box-shadow: 0 14px 30px -14px color-mix(in oklch, var(--dex-scorecard-ink) 80%, transparent);
  opacity: 0; scale: .96; transition: opacity .14s, scale .22s var(--dex-scorecard-out);
  & b { display: block; font-weight: 700; margin-bottom: 2px; }
  & span { display: flex; justify-content: space-between; gap: 16px; font-variant-numeric: tabular-nums; color: color-mix(in oklch, var(--dex-scorecard-bg) 70%, transparent); }
  & em { font-style: normal; color: var(--dex-scorecard-bg); font-weight: 650; }
  &.on { opacity: 1; scale: 1; }
}
.dex-scorecard__toast {
  position: absolute; left: 50%; bottom: 18px; z-index: 40; translate: -50% 0; padding: 10px 14px; border-radius: 12px; max-width: calc(100% - 32px);
  background: var(--dex-scorecard-ink); color: var(--dex-scorecard-bg); font-weight: 600; font-size: 12.5px;
