const RM = !!(window.matchMedia && matchMedia('(prefers-reduced-motion: reduce)').matches);
const $ = (s, el) => (el || root).querySelector(s);
const $$ = (s, el) => Array.from((el || root).querySelectorAll(s));
const UID = 'dex-scorecard-' + Math.random().toString(36).slice(2, 8);
const r1 = (v) => Math.round(v * 100) / 100;

/* ------------------------------------------------------------------ data
   Eight closed quarters. Revenue, net new ARR, cash, runway and burn multiple are
   derived from ARR and burn, so every tile agrees with every other tile. */
const QS = [['Q4', "'24", '31 Dec 2024'], ['Q1', "'25", '31 Mar 2025'], ['Q2', "'25", '30 Jun 2025'], ['Q3', "'25", '30 Sep 2025'],
  ['Q4', "'25", '31 Dec 2025'], ['Q1', "'26", '31 Mar 2026'], ['Q2', "'26", '30 Jun 2026'], ['Q3', "'26", '30 Sep 2026']];
const qn = (i) => QS[i][0] + ' ' + QS[i][1];
const ARR = [18.4, 20.1, 22.3, 24.0, 26.2, 28.9, 31.0, 33.6], ARRP = [18.0, 20.0, 22.0, 24.5, 26.5, 28.5, 31.5, 33.0];
const ARR0 = 16.9, ARRP0 = 16.8, ARRM1 = 15.6;
const REV = ARR.map((v, i) => r1(((i ? ARR[i - 1] : ARR0) + v) / 8));
const REVP = ARRP.map((v, i) => r1(((i ? ARRP[i - 1] : ARRP0) + v) / 8));
const NNA = ARR.map((v, i) => r1(v - (i ? ARR[i - 1] : ARR0)));
const GM = [71.2, 71.8, 72.5, 72.1, 73.4, 74.0, 74.6, 75.3], GMP = [71.0, 71.5, 72.0, 72.5, 73.0, 73.5, 74.0, 74.5];
const BURN = [6.8, 6.5, 6.9, 6.2, 5.8, 5.1, 4.6, 4.1], BURNP = [7.0, 6.8, 6.6, 6.4, 6.0, 5.6, 5.2, 4.8];
let cash = 95.2;
const CASH = BURN.map((b) => (cash = r1(cash - b)));
const RUN = CASH.map((c, i) => r1(c / (BURN[i] / 3)));
const HC = [212, 226, 241, 249, 258, 266, 271, 278], HCP = [215, 230, 245, 255, 265, 275, 285, 295];
const NPS = [38, 41, 40, 44, 47, 46, 51, 53], NPSP = [40, 41, 42, 44, 45, 47, 49, 50];
const NRR = [112, 114, 113, 116, 118, 117, 119, 121], NRRP = [113, 114, 115, 116, 117, 118, 119, 120];
const BM = BURN.map((b, i) => r1(b / NNA[i]));

const usd1 = (v) => '$' + v.toFixed(1) + 'M';
const M = [
  { k: 'arr', name: 'ARR', long: 'Annual recurring revenue', a: ARR, p: ARRP, a0: ARR0, kind: 'up', tol: 0.5, f: usd1, d: 'pct',
    desc: 'Contracted recurring revenue at quarter end, annualised.' },
  { k: 'rev', name: 'Revenue', long: 'Revenue', a: REV, p: REVP, a0: r1((ARRM1 + ARR0) / 8), kind: 'up', tol: 0.12, f: (v) => '$' + v.toFixed(2) + 'M', d: 'pct',
    desc: 'Recognised in the quarter: the average of opening and closing ARR, divided by four.' },
  { k: 'gm', name: 'Gross margin', long: 'Gross margin', a: GM, p: GMP, a0: 70.6, kind: 'up', tol: 1, f: (v) => v.toFixed(1) + '%', d: 'pts',
    desc: 'Revenue less hosting, card-network fees and support, as a share of revenue.' },
  { k: 'burn', name: 'Net burn', long: 'Net burn', a: BURN, p: BURNP, a0: 7.1, kind: 'down', tol: 0.2, f: usd1, d: 'pct',
    desc: 'Cash out less cash in for the quarter. Lower is better.' },
  { k: 'run', name: 'Runway', long: 'Runway', a: RUN, a0: 40.2, kind: 'min', floor: 30, warn: 24, f: (v) => v.toFixed(1) + ' mo', d: 'mo',
    desc: 'Closing cash over the quarter’s average monthly net burn. The board floor is 30 months.' },
  { k: 'hc', name: 'Headcount', long: 'Headcount', a: HC, p: HCP, a0: 203, kind: 'band', f: (v) => String(Math.round(v)), d: 'abs',
    desc: 'Full-time employees at quarter end, against the approved hiring plan.' },
  { k: 'nps', name: 'NPS', long: 'Net promoter score', a: NPS, p: NPSP, a0: 37, kind: 'up', tol: 3, f: (v) => String(Math.round(v)), d: 'abs',
    desc: 'Relationship NPS from the quarterly survey of account admins.' },
  { k: 'nrr', name: 'NRR', long: 'Net revenue retention', a: NRR, p: NRRP, a0: 111, kind: 'up', tol: 2, f: (v) => Math.round(v) + '%', d: 'pts',
    desc: 'ARR today from customers a year old, over the same customers’ ARR a year ago.' },
  { k: 'bm', name: 'Burn multiple', long: 'Burn multiple', a: BM, a0: 5.46, kind: 'max', cap: 2, warn: 3, f: (v) => v.toFixed(2) + '×', d: 'x',
    desc: 'Net burn over net new ARR. The board ceiling is 2.0×; lower is better.' }
];
const MK = Object.fromEntries(M.map((m) => [m.k, m]));
const ref = (m, i) => (m.p ? m.p[i] : m.kind === 'min' ? m.floor : m.cap);
const LBL = { ok: 'On track', risk: 'At risk', off: 'Off track' };
function status(m, i) {
  const a = m.a[i];
  if (m.kind === 'min') return a >= m.floor ? 'ok' : a >= m.warn ? 'risk' : 'off';
  if (m.kind === 'max') return a <= m.cap ? 'ok' : a <= m.warn ? 'risk' : 'off';
  const p = m.p[i];
  if (m.kind === 'band') { const d = Math.abs(a - p) / p; return d <= 0.03 ? 'ok' : d <= 0.08 ? 'risk' : 'off'; }
  const gap = m.kind === 'up' ? a - p : p - a;
  return gap >= 0 ? 'ok' : gap >= -m.tol ? 'risk' : 'off';
}
function attain(m, i) {
  const a = m.a[i], p = ref(m, i);
  if (m.kind === 'down' || m.kind === 'max') return p / a;
  if (m.kind === 'band') return 1 - Math.abs(a - p) / p;
  return a / p;
}
function vsPlan(m, i) {
  const a = m.a[i], p = ref(m, i);
  if (m.kind === 'min') return (a - p).toFixed(1) + ' mo ' + (a >= p ? 'above' : 'below') + ' floor';
  if (m.kind === 'max') return Math.abs(a - p).toFixed(2) + '× ' + (a <= p ? 'under' : 'over') + ' ceiling';
  const sg = a - p >= 0 ? '+' : '−';
  if (m.d === 'pts') return sg + Math.abs(a - p).toFixed(1) + ' pts vs plan';
  if (m.k === 'nps') return sg + Math.abs(a - p) + ' vs plan';
  return sg + Math.abs((a - p) / p * 100).toFixed(1) + '% vs plan';
}
function delta(m, i) {
  const a = m.a[i], b = i ? m.a[i - 1] : m.a0, d = a - b;
  const good = m.kind === 'down' || m.kind === 'max' ? d < 0 : m.kind === 'band' ? null : d > 0;
  const sg = d > 0 ? '+' : d < 0 ? '−' : '±';
  const ad = Math.abs(d);
  const txt = m.d === 'pct' ? sg + (ad / b * 100).toFixed(1) + '%' : m.d === 'pts' ? sg + ad.toFixed(1) + ' pts' :
    m.d === 'mo' ? sg + ad.toFixed(1) + ' mo' : m.d === 'x' ? sg + ad.toFixed(2) + '×' : sg + Math.round(ad);
  return '<span class="' + (good == null || d === 0 ? '' : good ? 'up' : 'dn') + '">' + txt + '</span> vs ' + (i ? qn(i - 1) : "Q3 '24");
}

/* ------------------------------------------------------------------ helpers */
function ticks(lo, hi, n) {
  const raw = (hi - lo) / n, mag = Math.pow(10, Math.floor(Math.log10(raw))), e = raw / mag;
  const st = (e >= 7.5 ? 10 : e >= 3.5 ? 5 : e >= 1.5 ? 2 : 1) * mag, out = [];
  for (let v = Math.floor(lo / st) * st; v <= Math.ceil(hi / st) * st + st / 2; v += st) out.push(+v.toFixed(8));
  return out;
}
const tws = new WeakMap();
function tweenNum(el, from, to, fmt, dur) {
  const tok = {}; tws.set(el, tok);
  if (RM || from === to || !isFinite(from)) { el.textContent = fmt(to); return; }
  const t0 = performance.now(), D = dur || 620;
  const step = (now) => {
    if (!root.isConnected) return;
    if (tws.get(el) !== tok) return;
    const t = Math.min(1, (now - t0) / D), k = 1 - Math.pow(1 - t, 4);
    el.textContent = fmt(from + (to - from) * k);
    if (t < 1) requestAnimationFrame(step);
  };
  requestAnimationFrame(step);
}
const tip = $('.dex-scorecard__tip'), toastEl = $('.dex-scorecard__toast');
function tipAt(x, y) {
  const r = root.getBoundingClientRect(), w = tip.offsetWidth, h = tip.offsetHeight;
  const l = Math.min(Math.max(8, x - r.left + 14), r.width - w - 8);
  let t = y - r.top - h - 12; if (t < 8) t = y - r.top + 16;
  tip.style.translate = Math.round(l) + 'px ' + Math.round(t) + 'px';
}
let toastT = 0;
function toast(msg) {
  toastEl.textContent = msg; toastEl.classList.add('on');
  clearTimeout(toastT); toastT = setTimeout(() => toastEl.classList.remove('on'), 2600);
}
function roving(group, sel, pick) {
  group.addEventListener('keydown', (e) => {
    const items = $$(sel, group).filter((b) => b.offsetParent !== null);
    const i = items.indexOf(document.activeElement); if (i < 0) return;
    const k = e.key, n = items.length;
    const j = k === 'ArrowRight' || k === 'ArrowDown' ? (i + 1) % n : k === 'ArrowLeft' || k === 'ArrowUp' ? (i - 1 + n) % n : k === 'Home' ? 0 : k === 'End' ? n - 1 : -1;
    if (j < 0) return;
    e.preventDefault(); items[j].focus(); pick(items[j]);
  });
}

/* ------------------------------------------------------------------ state */
let q = 7, view = 'score', metric = 'arr', sortBy = 'board';

/* ------------------------------------------------------------------ charts */
const sizes = new WeakMap();
function drawChart(svg, m, enter) {
  const W = svg.clientWidth, H = svg.clientHeight;
  if (!W || !H) return;
  sizes.set(svg, W + 'x' + H);
  const hero = svg.dataset.chart === 'hero';
  const L = hero ? 40 : 50, R = 10, T = 16, B = 24;
  const lo0 = Math.min(...m.a, ...m.a.map((_, i) => ref(m, i))), hi0 = Math.max(...m.a, ...m.a.map((_, i) => ref(m, i)));
  const pad = (hi0 - lo0) * 0.14 || 1;
  const tk = ticks(lo0 - pad, hi0 + pad, hero ? 3 : 5), lo = tk[0], hi = tk[tk.length - 1];
  const step = (W - L - R) / 8, x = (i) => L + step * (i + 0.5), y = (v) => T + (H - T - B) * (1 - (v - lo) / (hi - lo));
  const yf = (v) => m.k === 'hc' || m.k === 'nps' || m.k === 'nrr' ? String(Math.round(v)) : m.k === 'bm' ? v.toFixed(1) + '×' : m.k === 'run' ? Math.round(v) : (m.k === 'gm' ? v.toFixed(0) + '%' : '$' + (+v.toFixed(2)) + 'M');
  const gid = UID + '-' + svg.dataset.chart;
  const pts = m.a.map((v, i) => [x(i), y(v)]);
  const line = 'M' + pts.map((p) => p[0].toFixed(1) + ' ' + p[1].toFixed(1)).join('L');
  const area = line + 'L' + x(7).toFixed(1) + ' ' + (H - B) + 'L' + x(0).toFixed(1) + ' ' + (H - B) + 'Z';
  const plan = m.p ? 'M' + m.p.map((v, i) => x(i).toFixed(1) + ' ' + y(v).toFixed(1)).join('L') : 'M' + (L) + ' ' + y(ref(m, 0)).toFixed(1) + 'H' + (W - R);
  let s = '<defs><linearGradient id="' + gid + '" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="var(--dex-scorecard-accent)" stop-opacity=".55"/><stop offset="1" stop-color="var(--dex-scorecard-accent)" stop-opacity="0"/></linearGradient></defs>';
  s += '<rect class="band" x="' + (x(0) - step * 0.42).toFixed(1) + '" y="' + T + '" width="' + (step * 0.84).toFixed(1) + '" height="' + (H - T - B) + '" rx="8"/>';
  tk.forEach((v) => { s += '<line class="gl" x1="' + L + '" x2="' + (W - R) + '" y1="' + y(v).toFixed(1) + '" y2="' + y(v).toFixed(1) + '"/><text x="' + (L - 8) + '" y="' + (y(v) + 3.5).toFixed(1) + '" text-anchor="end">' + yf(v) + '</text>'; });
  s += '<line class="base" x1="' + L + '" x2="' + (W - R) + '" y1="' + (H - B) + '" y2="' + (H - B) + '"/>';
  QS.forEach((qq, i) => { s += '<text class="xl" x="' + x(i).toFixed(1) + '" y="' + (H - 7) + '" text-anchor="middle">' + (hero ? qq[0] : qq[0] + ' ' + qq[1]) + '</text>'; });
  s += '<path class="area" fill="url(#' + gid + ')" d="' + area + '"/>';
  s += '<path class="plan" d="' + plan + '"/>';
  if (!m.p) s += '<text x="' + (W - R) + '" y="' + (y(ref(m, 0)) - 6).toFixed(1) + '" text-anchor="end">' + (m.kind === 'min' ? 'floor ' : 'ceiling ') + m.f(ref(m, 0)) + '</text>';
  s += '<path class="act" pathLength="1" d="' + line + '"/>';
  pts.forEach((p, i) => { s += '<circle class="pt" style="--i:' + i + '" cx="' + p[0].toFixed(1) + '" cy="' + p[1].toFixed(1) + '" r="' + (hero ? 3.5 : 4) + '"/>'; });
  s += '<text class="vl" text-anchor="middle"></text>';
  s += '<line class="hl" y1="' + T + '" y2="' + (H - B) + '"/><circle class="hp" r="3"/>';
  s += '<rect class="hit" x="' + L + '" y="0" width="' + (W - L - R) + '" height="' + H + '" fill="transparent"/>';
  svg.innerHTML = s;
