  if (band) band.style.transform = 'translateX(' + (g.x(q) - g.x(0)).toFixed(1) + 'px)';
  svg.querySelectorAll('.pt').forEach((c, i) => c.classList.toggle('sel', i === q));
  svg.querySelectorAll('.xl').forEach((t, i) => t.classList.toggle('sel', i === q));
