      (m.p ? 'Plan' : m.kind === 'min' ? 'Floor' : 'Ceiling') + ' <em>' + m.f(ref(m, i)) + '</em></span><span>' + vsPlan(m, i).replace(/ vs plan$/, '') + ' <em>' + LBL[st] + '</em></span>';
