}

let shown = {};
function renderScore(prevQ) {
  const arr = MK.arr;
  tweenNum($('[data-hero-v]'), prevQ == null ? NaN : arr.a[prevQ], arr.a[q], arr.f);
  const nn = NNA[q], qoq = (ARR[q] / (q ? ARR[q - 1] : ARR0) - 1) * 100, vp = (ARR[q] / ARRP[q] - 1) * 100;
  $('[data-hero-s]').innerHTML = '<b>+$' + nn.toFixed(1) + 'M</b> net new in ' + qn(q) + ' · <span class="up">+' + qoq.toFixed(1) + '%</span> on the quarter<br>Plan ' + usd1(ARRP[q]) +
    ' · <span class="' + (vp >= 0 ? 'up' : 'dn') + '">' + (vp >= 0 ? '+' : '−') + Math.abs(vp).toFixed(1) + '%</span> ' + (vp >= 0 ? 'ahead' : 'behind');
  $$('.dex-scorecard__tile').forEach((t) => {
    const m = MK[t.dataset.k], st = status(m, q);
    tweenNum(t.querySelector('[data-v]'), prevQ == null ? NaN : m.a[prevQ], m.a[q], m.f);
    t.querySelector('[data-d]').innerHTML = delta(m, q);
    const chip = t.querySelector('[data-chip]'); chip.dataset.s = st; chip.textContent = LBL[st];
    const sv = t.querySelector('[data-spark]'); if (sv._s) markSpark(sv);
  });
  // summary
  const all = M.map((m) => ({ m, s: status(m, q) }));
  const cnt = { ok: 0, risk: 0, off: 0 }; all.forEach((o) => cnt[o.s]++);
  $('[data-counts]').innerHTML = ['ok', 'risk', 'off'].map((k) => '<div data-s="' + k + '"><b>' + cnt[k] + '</b><span><i></i>' + LBL[k] + '</span></div>').join('');
  const notes = [];
  notes.push(['ok', 'ARR closed at <b>' + usd1(ARR[q]) + '</b>, ' + (qoq >= 0 ? 'up ' : 'down ') + '<b>' + Math.abs(qoq).toFixed(1) + '%</b> on the quarter and ' + Math.abs(vp).toFixed(1) + '% ' + (vp >= 0 ? 'ahead of' : 'behind') + ' plan.']);
  notes.push([status(MK.run, q), 'Net burn of <b>' + usd1(BURN[q]) + '</b> leaves <b>' + RUN[q].toFixed(1) + ' months</b> of runway on ' + usd1(CASH[q]) + ' cash.']);
  const ex = all.filter((o) => o.s !== 'ok' && o.m.k !== 'run').sort((a, b) => (a.s === 'off' ? 0 : 1) - (b.s === 'off' ? 0 : 1));
  if (!ex.length) notes.push(['ok', 'Every other metric is on or ahead of plan this quarter.']);
  ex.slice(0, 2).forEach((o) => notes.push([o.s, o.m.long + ' <b>' + o.m.f(o.m.a[q]) + '</b> against ' + (o.m.p ? 'a plan of ' : o.m.kind === 'min' ? 'a floor of ' : 'a ceiling of ') + o.m.f(ref(o.m, q)) + ' (' + vsPlan(o.m, q).replace(/ vs plan$/, '') + ').']));
  if (ex.length > 2) notes.push(['risk', (ex.length - 2) + ' more ' + (ex.length - 2 === 1 ? 'metric is' : 'metrics are') + ' below plan — see the quarter table.']);
  $('[data-notes]').innerHTML = notes.map((n, i) => '<li data-s="' + n[0] + '" style="--i:' + i + '">' + n[1] + '</li>').join('');
}

/* ------------------------------------------------------------------ trend view */
const pills = $('[data-pills]');
pills.innerHTML = M.map((m, i) => '<button type="button" role="radio" style="--i:' + i + '" data-k="' + m.k + '">' + m.long + '</button>').join('');
pills.addEventListener('click', (e) => { const b = e.target.closest('button'); if (b && b.dataset.k !== metric) { metric = b.dataset.k; renderTrend(true); } });
roving(pills, 'button', (b) => { metric = b.dataset.k; renderTrend(true); });
const qlist = $('[data-qlist]');
qlist.addEventListener('click', (e) => { const o = e.target.closest('[role="option"]'); if (o) setQ(+o.dataset.q); });
roving(qlist, '[role="option"]', (o) => setQ(+o.dataset.q));
qlist.addEventListener('keydown', (e) => { if (e.key === 'Enter' || e.key === ' ') { const o = e.target.closest('[role="option"]'); if (o) { e.preventDefault(); setQ(+o.dataset.q); } } });

function renderTrend(full) {
  const m = MK[metric];
  $$('button', pills).forEach((b) => { const on = b.dataset.k === metric; b.setAttribute('aria-checked', on); b.tabIndex = on ? 0 : -1; });
  $('[data-t-name]').textContent = m.long;
  $('[data-t-desc]').textContent = m.desc;
  $('[data-t-planlbl]').textContent = m.p ? 'Plan' : m.kind === 'min' ? 'Board floor' : 'Board ceiling';
  if (full) drawChart($('[data-chart="trend"]'), m, true); else markChart($('[data-chart="trend"]'));
  qlist.innerHTML = QS.map((qq, i) => i).reverse().map((i, n) => {
    const st = status(m, i);
    return '<div role="option" style="--i:' + n + '" data-q="' + i + '" data-s="' + st + '" aria-selected="' + (i === q) + '" tabindex="' + (i === q ? 0 : -1) + '">' +
      '<span class="q">' + qn(i) + '</span><span class="v">' + m.f(m.a[i]) + '</span><span class="var">' + (m.p ? vsPlan(m, i).replace(/ vs plan$/, '') : LBL[st]) + '</span></div>';
  }).join('');
}

/* ------------------------------------------------------------------ table view */
const thead = $('[data-thead]'), tbody = $('[data-tbody]');
thead.innerHTML = '<th scope="col"><span>Metric</span></th>' + QS.map((qq, i) => '<th scope="col"><button type="button" data-q="' + i + '" aria-label="Show ' + qn(i) + '">' + qn(i) + '</button></th>').join('') +
  '<th scope="col"><span>Plan</span></th><th scope="col"><span>Status</span></th>';
thead.addEventListener('click', (e) => { const b = e.target.closest('button[data-q]'); if (b) setQ(+b.dataset.q); });
const SORD = { off: 0, risk: 1, ok: 2 };
function rowOrder() {
  const ks = M.map((m) => m.k);
  if (sortBy === 'att') ks.sort((a, b) => attain(MK[a], q) - attain(MK[b], q));
  if (sortBy === 'status') ks.sort((a, b) => SORD[status(MK[a], q)] - SORD[status(MK[b], q)] || attain(MK[a], q) - attain(MK[b], q));
  return ks;
}
function renderTable(animate) {
  $$('button[data-q]', thead).forEach((b) => { if (+b.dataset.q === q) b.setAttribute('aria-current', 'true'); else b.removeAttribute('aria-current'); });
  const before = new Map($$('tr', tbody).map((tr) => [tr.dataset.k, tr.getBoundingClientRect().top]));
  const rows = rowOrder().map((k) => {
    const m = MK[k];
    let tr = tbody.querySelector('tr[data-k="' + k + '"]');
    if (!tr) { tr = document.createElement('tr'); tr.dataset.k = k; tr.tabIndex = 0; tr.setAttribute('aria-label', m.long + ', open trend'); }
    const st = status(m, q);
    tr.innerHTML = '<td>' + m.long + '</td>' + m.a.map((v, i) => {
      const s = status(m, i), t = Math.min(1, 0.3 + Math.abs(attain(m, i) - 1) * 6);
      return '<td class="c' + (i === q ? ' sel' : '') + '" data-s="' + s + '" style="--t:' + t.toFixed(2) + '">' + m.f(v) + '</td>';
    }).join('') + '<td>' + m.f(ref(m, q)) + '</td><td><span class="dex-scorecard__chip" data-s="' + st + '">' + LBL[st] + '</span></td>';
    return tr;
  });
  rows.forEach((tr) => tbody.appendChild(tr));
  if (animate && !RM) rows.forEach((tr) => {
    const b = before.get(tr.dataset.k); if (b == null) return;
    const dy = b - tr.getBoundingClientRect().top;
    if (Math.abs(dy) > 1) tr.animate([{ transform: 'translateY(' + dy + 'px)' }, { transform: 'none' }], { duration: 520, easing: 'cubic-bezier(.2,.9,.25,1.05)' });
  });
}
tbody.addEventListener('click', (e) => { const tr = e.target.closest('tr'); if (tr) { metric = tr.dataset.k; go('trend'); } });
tbody.addEventListener('keydown', (e) => {
  const tr = e.target.closest('tr'); if (!tr) return;
  if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); metric = tr.dataset.k; go('trend'); }
  if (e.key === 'ArrowDown' && tr.nextElementSibling) { e.preventDefault(); tr.nextElementSibling.focus(); }
  if (e.key === 'ArrowUp' && tr.previousElementSibling) { e.preventDefault(); tr.previousElementSibling.focus(); }
});
const sortSeg = $('[data-sort]');
function setSort(v) {
  sortBy = v;
  $$('button', sortSeg).forEach((b) => { const on = b.dataset.v === v; b.setAttribute('aria-checked', on); b.tabIndex = on ? 0 : -1; });
  renderTable(true);
}
sortSeg.addEventListener('click', (e) => { const b = e.target.closest('button'); if (b && b.dataset.v !== sortBy) setSort(b.dataset.v); });
roving(sortSeg, 'button', (b) => setSort(b.dataset.v));

/* ------------------------------------------------------------------ quarter + views */
function setQ(i) {
  if (i === q || i < 0 || i > 7) return;
  const prev = q; q = i;
  $$('button', scrub).forEach((b, n) => { b.setAttribute('aria-checked', n === q); b.tabIndex = n === q ? 0 : -1; });
  scrub.style.setProperty('--q', q);
  $('[data-q-long]').textContent = QS[q][2];
  $('[data-q-short]').textContent = qn(q);
  renderScore(prev);
  $$('.dex-scorecard__chart').forEach(markChart);
  if (view === 'trend') renderTrend(false);
  if (view === 'table') renderTable(sortBy !== 'board');
}
const nav = $('.dex-scorecard__nav');
function go(v) {
  view = v;
  $$('button', nav).forEach((b) => { if (b.dataset.view === v) b.setAttribute('aria-current', 'page'); else b.removeAttribute('aria-current'); });
  $$('.dex-scorecard__view').forEach((s) => { s.hidden = s.dataset.view !== v; });
  tip.classList.remove('on');
  if (v === 'trend') renderTrend(true);
  if (v === 'table') renderTable(false);
  if (v === 'score') { drawChart($('[data-chart="hero"]'), MK.arr, true); $$('[data-spark]').forEach((s) => drawSpark(s, MK[s.parentElement.dataset.k])); }
}
nav.addEventListener('click', (e) => { const b = e.target.closest('button'); if (b && b.dataset.view !== view) go(b.dataset.view); });
nav.addEventListener('keydown', (e) => {
  const bs = $$('button', nav), i = bs.indexOf(document.activeElement); if (i < 0) return;
  if (e.key === 'ArrowDown' || e.key === 'ArrowRight') { e.preventDefault(); bs[(i + 1) % bs.length].focus(); }
  if (e.key === 'ArrowUp' || e.key === 'ArrowLeft') { e.preventDefault(); bs[(i + bs.length - 1) % bs.length].focus(); }
});
$('[data-act="snap"]').addEventListener('click', () => toast(qn(q) + ' scorecard added to the 21 Oct board pack as page 3.'));
root.addEventListener('keydown', (e) => { if (e.key === 'Escape') { tip.classList.remove('on'); toastEl.classList.remove('on'); } });

$$('.dex-scorecard__chart').forEach(hoverChart);

/* ------------------------------------------------------------------ mount */
$$('button', scrub).forEach((b, n) => { b.setAttribute('aria-checked', n === q); b.tabIndex = n === q ? 0 : -1; });
scrub.style.setProperty('--q', q);
renderScore(null);
drawChart($('[data-chart="hero"]'), MK.arr, true);
$$('[data-spark]').forEach((s) => drawSpark(s, MK[s.parentElement.dataset.k]));
if (window.ResizeObserver) {
  const ro = new ResizeObserver((entries) => {
    if (!root.isConnected) { ro.disconnect(); return; }
    entries.forEach((en) => {
      const el = en.target, k = el.clientWidth + 'x' + el.clientHeight;
      if (!el.clientWidth || sizes.get(el) === k) return;
      if (el.dataset.chart) drawChart(el, el.dataset.chart === 'hero' ? MK.arr : MK[metric], false);
      else drawSpark(el, MK[el.parentElement.dataset.k]);
    });
  });
  $$('.dex-scorecard__chart, [data-spark]').forEach((el) => ro.observe(el));
}

