@property --dex-boardpack-p { syntax: "<number>"; inherits: true; initial-value: 0; }

.dex-boardpack {
  --dex-boardpack-bg: oklch(0.985 0.004 250);
  --dex-boardpack-ink: oklch(0.26 0.03 255);
  --dex-boardpack-fav: oklch(0.52 0.09 165);
  --dex-boardpack-unf: oklch(0.48 0.15 22);
  --dex-boardpack-paper: color-mix(in oklch, var(--dex-boardpack-bg) 30%, white);
  --dex-boardpack-line: color-mix(in oklch, var(--dex-boardpack-ink) 13%, transparent);
  --dex-boardpack-hair: color-mix(in oklch, var(--dex-boardpack-ink) 7%, transparent);
  --dex-boardpack-soft: color-mix(in oklch, var(--dex-boardpack-ink) 4.5%, transparent);
  --dex-boardpack-mute: color-mix(in oklch, var(--dex-boardpack-ink) 64%, var(--dex-boardpack-bg));
  --dex-boardpack-faint: color-mix(in oklch, var(--dex-boardpack-ink) 42%, var(--dex-boardpack-bg));
  --dex-boardpack-sel: color-mix(in oklch, var(--dex-boardpack-ink) 7%, var(--dex-boardpack-paper));
  --dex-boardpack-serif: ui-serif, "New York", "Iowan Old Style", Charter, Georgia, serif;
  --dex-boardpack-sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --dex-boardpack-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --dex-boardpack-out: cubic-bezier(.16, 1, .3, 1);
  --dex-boardpack-spring: linear(0, .009, .035 2.1%, .141 4.4%, .723 12.9%, .938 16.7%, 1.017 19.4%, 1.067, 1.077 24.3%, 1.065 26.6%, 1.022 31.3%, .997 35.6%, .988 39.5%, .994 47.1%, 1.001);
  width: 100%;
  height: var(--dex-boardpack-h, 680px);
  container-type: inline-size;
  position: relative; isolation: isolate; overflow: hidden;
  border-radius: 14px;
  background: var(--dex-boardpack-bg);
  color: var(--dex-boardpack-ink);
  font: 13px/1.45 var(--dex-boardpack-sans);
  accent-color: var(--dex-boardpack-ink);
  scrollbar-width: thin;
  scrollbar-color: color-mix(in oklch, var(--dex-boardpack-ink) 22%, transparent) transparent;
  box-shadow: inset 0 0 0 1px var(--dex-boardpack-line);
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, h3, h4, p, ul, li, form) { margin: 0; padding: 0; }
  & :where(button) { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; text-align: inherit; }
  & :focus-visible { outline: 2px solid var(--dex-boardpack-ink); outline-offset: 2px; border-radius: 6px; }
  & [hidden] { display: none !important; }
}
.dex-boardpack__ic { width: 17px; height: 17px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
.dex-boardpack__vh { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
.dex-boardpack__cap { font-size: 10.5px; font-weight: 650; letter-spacing: .13em; text-transform: uppercase; color: var(--dex-boardpack-faint); }
.dex-boardpack__shell { height: 100%; display: grid; grid-template-columns: 218px minmax(0, 1fr); }

/* ---------------------------------------------------------------- side */
.dex-boardpack__side {
  display: flex; flex-direction: column; gap: 6px; min-height: 0; overflow: auto; padding: 22px 14px 16px;
  border-right: 1px solid var(--dex-boardpack-line);
  background: color-mix(in oklch, var(--dex-boardpack-bg) 92%, var(--dex-boardpack-ink));
}
.dex-boardpack__brand {
  display: flex; align-items: center; gap: 10px; padding: 0 6px 20px;
  font: 600 16px/1.2 var(--dex-boardpack-serif); letter-spacing: -.01em;
  & svg { width: 30px; height: 30px; flex: none; padding: 6px; border-radius: 50%; background: var(--dex-boardpack-ink); fill: none; stroke: var(--dex-boardpack-paper); stroke-width: 1.8; stroke-linecap: round; }
  & small { display: block; margin-top: 2px; font: 500 11px var(--dex-boardpack-sans); color: var(--dex-boardpack-mute); letter-spacing: 0; }
}
.dex-boardpack__nav {
  display: grid; gap: 2px;
  & button {
    position: relative; display: flex; align-items: center; gap: 10px; padding: 9px 10px; border-radius: 9px; color: var(--dex-boardpack-mute); font-weight: 550;
    transition: background-color .2s, color .2s;
    & .n { display: grid; place-items: center; width: 22px; height: 22px; flex: none; border-radius: 50%; font: 600 11.5px var(--dex-boardpack-serif); box-shadow: inset 0 0 0 1px var(--dex-boardpack-line); transition: background-color .25s, color .25s; }
    &:hover { background: var(--dex-boardpack-soft); color: var(--dex-boardpack-ink); }
    &[aria-current="page"] { color: var(--dex-boardpack-ink); font-weight: 650; background: var(--dex-boardpack-paper); box-shadow: 0 1px 0 var(--dex-boardpack-line), 0 8px 18px -14px color-mix(in oklch, var(--dex-boardpack-ink) 50%, transparent); }
    &[aria-current="page"] .n { background: var(--dex-boardpack-ink); color: var(--dex-boardpack-paper); box-shadow: none; }
  }
}
.dex-boardpack__badge {
  margin-left: auto; min-width: 20px; padding: 1px 6px; border-radius: 999px; text-align: center; font-size: 11px; font-weight: 700;
  background: color-mix(in oklch, var(--dex-boardpack-unf) 14%, transparent); color: var(--dex-boardpack-unf);
  &:empty { display: none; }
}
.dex-boardpack__sign {
  margin-top: auto; display: grid; grid-template-columns: auto 1fr; align-items: center; gap: 10px 12px; padding: 14px 6px 0;
  border-top: 1px solid var(--dex-boardpack-line); font-size: 12px; color: var(--dex-boardpack-mute);
  & p { text-wrap: pretty; }
}
.dex-boardpack__ring {
  --dex-boardpack-p: 0;
  width: 46px; height: 46px; border-radius: 50%; display: grid; place-items: center; position: relative;
  background: conic-gradient(var(--dex-boardpack-fav) calc(var(--dex-boardpack-p) * 1%), var(--dex-boardpack-line) 0);
  transition: --dex-boardpack-p .9s var(--dex-boardpack-out);
  &::before { content: ""; position: absolute; inset: 4px; border-radius: 50%; background: var(--dex-boardpack-bg); }
  & span { position: relative; font: 600 12px var(--dex-boardpack-serif); color: var(--dex-boardpack-ink); font-variant-numeric: tabular-nums; }
}
.dex-boardpack__approve {
  grid-column: 1 / -1; display: flex; align-items: center; justify-content: center; gap: 8px; padding: 9px 12px; border-radius: 9px;
  background: var(--dex-boardpack-ink); color: var(--dex-boardpack-paper); font-weight: 650; font-size: 12.5px;
  transition: opacity .25s, transform .25s var(--dex-boardpack-out), background-color .25s;
  &[aria-disabled="true"] { opacity: .38; cursor: not-allowed; }
  &:not([aria-disabled="true"]):active { transform: scale(.97); }
  &.done { background: var(--dex-boardpack-fav); }
}

/* ---------------------------------------------------------------- main */
.dex-boardpack__main { min-width: 0; min-height: 0; display: grid; grid-template-rows: auto minmax(0, 1fr); gap: 14px; padding: 20px 22px 18px; }
.dex-boardpack__head { display: flex; align-items: end; justify-content: space-between; gap: 12px 20px; flex-wrap: wrap; padding-bottom: 12px; border-bottom: 1px solid var(--dex-boardpack-ink); }
.dex-boardpack__title h2 { margin-top: 4px; font: 600 clamp(21px, 2.6cqi, 30px)/1.1 var(--dex-boardpack-serif); letter-spacing: -.02em; text-wrap: balance; }
.dex-boardpack__ctrls { display: flex; align-items: center; gap: 12px 16px; flex-wrap: wrap; }
.dex-boardpack__seg {
  display: inline-flex; padding: 3px; border-radius: 10px; background: var(--dex-boardpack-soft); box-shadow: inset 0 0 0 1px var(--dex-boardpack-line);
  & button { padding: 5px 12px; border-radius: 7px; font-size: 12.5px; font-weight: 600; color: var(--dex-boardpack-mute); transition: background-color .2s, color .2s, box-shadow .2s; }
  & button:hover { color: var(--dex-boardpack-ink); }
  & button[aria-checked="true"] { background: var(--dex-boardpack-paper); color: var(--dex-boardpack-ink); box-shadow: 0 1px 2px color-mix(in oklch, var(--dex-boardpack-ink) 22%, transparent); }
}
.dex-boardpack__seg--sm button { padding: 4px 10px; font-size: 12px; }
.dex-boardpack__thr {
  display: grid; gap: 2px; font-size: 11.5px; color: var(--dex-boardpack-mute);
  & b { color: var(--dex-boardpack-ink); font-variant-numeric: tabular-nums; }
  & input { width: 150px; margin: 0; }
}

.dex-boardpack__view { min-height: 0; }
.dex-boardpack__paper {
  position: relative; min-width: 0; min-height: 0; background: var(--dex-boardpack-paper); border-radius: 10px;
  box-shadow: 0 0 0 1px var(--dex-boardpack-hair), 0 1px 2px var(--dex-boardpack-hair), 0 20px 40px -36px color-mix(in oklch, var(--dex-boardpack-ink) 70%, transparent);
  animation: dex-boardpack-rise .7s var(--dex-boardpack-out) both; animation-delay: calc(var(--i, 0) * 80ms);
}
.dex-boardpack__view[data-view="pl"] { display: grid; grid-template-columns: minmax(0, 1fr) 292px; gap: 14px; }
.dex-boardpack__plpanel { display: flex; flex-direction: column; }
.dex-boardpack__tbar { display: flex; align-items: center; gap: 10px 14px; flex-wrap: wrap; padding: 12px 14px 10px; border-bottom: 1px solid var(--dex-boardpack-hair); }
.dex-boardpack__toggle {
  display: inline-flex; align-items: center; gap: 8px; padding: 4px 4px; font-size: 12px; font-weight: 600; color: var(--dex-boardpack-mute);
  & .sw { position: relative; width: 28px; height: 16px; border-radius: 999px; background: var(--dex-boardpack-line); transition: background-color .25s; }
  & .sw::after { content: ""; position: absolute; left: 2px; top: 2px; width: 12px; height: 12px; border-radius: 50%; background: var(--dex-boardpack-paper); box-shadow: 0 1px 2px color-mix(in oklch, var(--dex-boardpack-ink) 40%, transparent); transition: transform .4s var(--dex-boardpack-spring); }
  &[aria-pressed="true"] { color: var(--dex-boardpack-ink); }
  &[aria-pressed="true"] .sw { background: var(--dex-boardpack-ink); }
  &[aria-pressed="true"] .sw::after { transform: translateX(12px); }
}
.dex-boardpack__legend {
  margin-left: auto; display: flex; align-items: center; gap: 6px; font-size: 11px; color: var(--dex-boardpack-mute);
  & i { width: 10px; height: 8px; border-radius: 2px; margin-left: 6px; }
  & .u { background: var(--dex-boardpack-unf); } & .f { background: var(--dex-boardpack-fav); }
}
.dex-boardpack__tscroll { flex: 1; min-height: 0; overflow: auto; scrollbar-width: thin; }
.dex-boardpack__table {
  width: 100%; min-width: 540px; border-collapse: collapse; font-variant-numeric: tabular-nums;
  & th { position: sticky; top: 0; z-index: 2; background: var(--dex-boardpack-paper); padding: 9px 8px 7px; font-size: 10.5px; font-weight: 650; letter-spacing: .08em; text-transform: uppercase; color: var(--dex-boardpack-faint); text-align: right; border-bottom: 1px solid var(--dex-boardpack-line); white-space: nowrap; }
  & th:first-child { text-align: left; padding-left: 16px; }
  & th.dvh { width: 94px; & span { display: inline-block; width: 33.33%; text-align: center; font-family: var(--dex-boardpack-mono); letter-spacing: 0; } & span:first-child { text-align: left; } & span:last-child { text-align: right; } }
  & td { padding: 7px 8px; text-align: right; white-space: nowrap; border-bottom: 1px solid var(--dex-boardpack-hair); }
  & td:first-child { text-align: left; padding-left: 16px; white-space: normal; min-width: 150px; }
  & td:first-child, & th:first-child { position: sticky; left: 0; z-index: 1; background: var(--dex-boardpack-paper); }
  & th:first-child { z-index: 3; }
  & tr.ln:hover td:first-child { background: color-mix(in oklch, var(--dex-boardpack-ink) 4.5%, var(--dex-boardpack-paper)); }
  & tr[aria-selected="true"] td:first-child { background: var(--dex-boardpack-sel); }
  & tr.hrow td { padding: 12px 10px 4px 16px; font: 600 10.5px var(--dex-boardpack-sans); letter-spacing: .12em; text-transform: uppercase; color: var(--dex-boardpack-faint); border-bottom: 0; }
  & tr.ln { cursor: pointer; transition: background-color .18s; }
  & tr.ln td:first-child { padding-left: 24px; }
  & td:last-child, & th:last-child { padding-right: 12px; width: 30px; }
  & small { display: block; font: 500 11px var(--dex-boardpack-sans); color: var(--dex-boardpack-mute); }
  & tr.ln:hover { background: var(--dex-boardpack-soft); }
  & tr.sub td { font-weight: 700; border-top: 1px solid var(--dex-boardpack-line); }
  & tr.sub td:first-child, & tr.tot td:first-child { padding-left: 16px; font-family: var(--dex-boardpack-serif); font-size: 14px; }
  & tr.tot td { font-weight: 750; border-top: 1px solid var(--dex-boardpack-ink); border-bottom: 3px double var(--dex-boardpack-ink); }
  & tr[aria-selected="true"] { background: var(--dex-boardpack-sel); }
  & tr[aria-selected="true"] td:first-child { box-shadow: inset 3px 0 0 var(--dex-boardpack-ink); }
  & tr:focus-visible { outline-offset: -2px; }
  & .vf { color: var(--dex-boardpack-fav); font-weight: 650; }
  & .vu { color: var(--dex-boardpack-unf); font-weight: 650; }
  & .fu { margin-left: 3px; font-size: 10px; font-weight: 700; opacity: .8; }
  & tr.gone { display: none; }
}
.dex-boardpack__dv {
  position: relative; display: block; height: 12px; width: 82px; margin-left: auto;
  &::before { content: ""; position: absolute; left: 50%; top: -4px; bottom: -4px; width: 1px; background: var(--dex-boardpack-line); }
  & i { position: absolute; top: 0; bottom: 0; width: 50%; border-radius: 2px; transform: scaleX(var(--v, 0)); transition: transform .6s var(--dex-boardpack-spring); }
  & i.f { left: 50%; transform-origin: left; background: var(--dex-boardpack-fav); }
  & i.u { right: 50%; transform-origin: right; background: var(--dex-boardpack-unf); }
  & i.m { opacity: .35; }
}
.dex-boardpack__table.enter .dex-boardpack__dv i { animation: dex-boardpack-grow .9s var(--dex-boardpack-out) both; animation-delay: calc(200ms + var(--i, 0) * 35ms); }
.dex-boardpack__st {
  display: inline-grid; place-items: center; width: 18px; height: 18px; border-radius: 50%; vertical-align: middle;
  &.need { background: var(--dex-boardpack-unf); color: var(--dex-boardpack-paper); font: 800 11px/1 var(--dex-boardpack-sans); }
  &.ok { box-shadow: inset 0 0 0 1.5px var(--dex-boardpack-fav); color: var(--dex-boardpack-fav); }
  &.ok svg { width: 11px; height: 11px; fill: none; stroke: currentColor; stroke-width: 2.6; stroke-linecap: round; stroke-linejoin: round; }
}

/* detail */
.dex-boardpack__detail { display: flex; flex-direction: column; gap: 6px; padding: 16px 16px 14px; overflow: auto; scrollbar-width: thin; --i: 1; }
.dex-boardpack__detail h3 { font: 600 21px/1.15 var(--dex-boardpack-serif); letter-spacing: -.015em; text-wrap: balance; }
.dex-boardpack__dfig { font-size: 12.5px; color: var(--dex-boardpack-mute); font-variant-numeric: tabular-nums; & b { font-weight: 700; } & .vf { color: var(--dex-boardpack-fav); } & .vu { color: var(--dex-boardpack-unf); } }
.dex-boardpack__mplot { position: relative; height: 128px; flex: none; margin: 4px -4px 2px; }
.dex-boardpack__mchart {
  position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; cursor: crosshair;
  & text { font: 9.5px var(--dex-boardpack-mono); fill: var(--dex-boardpack-faint); }
  & .zl { stroke: color-mix(in oklch, var(--dex-boardpack-ink) 40%, transparent); }
  & .gl { stroke: var(--dex-boardpack-hair); }
  & rect.f { fill: var(--dex-boardpack-fav); }
  & rect.u { fill: var(--dex-boardpack-unf); }
  & rect.out { opacity: .28; }
  & rect.hov { opacity: 1; stroke: var(--dex-boardpack-ink); stroke-width: 1; }
  & .ml.in { fill: var(--dex-boardpack-ink); font-weight: 700; }
}
.dex-boardpack__mchart.enter rect.bar { transform-box: fill-box; animation: dex-boardpack-growy .7s var(--dex-boardpack-out) both; animation-delay: calc(var(--i) * 40ms); }
.dex-boardpack__mchart rect.bar.p { transform-origin: bottom; }
.dex-boardpack__mchart rect.bar.n { transform-origin: top; }
.dex-boardpack__note {
  display: grid; gap: 8px; padding-top: 10px; border-top: 1px solid var(--dex-boardpack-hair);
  & blockquote { margin: 0; font: italic 400 13.5px/1.5 var(--dex-boardpack-serif); text-wrap: pretty; color: var(--dex-boardpack-ink); }
  & .who { display: flex; align-items: center; justify-content: space-between; gap: 8px; font-size: 11.5px; color: var(--dex-boardpack-mute); }
  & .notes { display: grid; gap: 6px; }
  & .notes li { list-style: none; padding: 7px 9px; border-radius: 8px; background: var(--dex-boardpack-soft); font-size: 12px; text-wrap: pretty; animation: dex-boardpack-rise .45s var(--dex-boardpack-out) both; }
  & .notes b { display: block; font-size: 10.5px; color: var(--dex-boardpack-mute); font-weight: 600; }
  & .quiet { font-size: 12px; color: var(--dex-boardpack-mute); text-wrap: pretty; }
}
.dex-boardpack__explain {
  display: inline-flex; align-items: center; gap: 6px; padding: 5px 10px; border-radius: 999px; font-size: 11.5px; font-weight: 650; white-space: nowrap;
  box-shadow: inset 0 0 0 1px var(--dex-boardpack-line); color: var(--dex-boardpack-ink); transition: background-color .2s, color .2s, box-shadow .2s;
  & svg { width: 13px; height: 13px; fill: none; stroke: currentColor; stroke-width: 2.4; stroke-linecap: round; stroke-linejoin: round; opacity: .35; transition: opacity .2s; }
  &:hover { background: var(--dex-boardpack-soft); }
  &[aria-pressed="true"] { background: color-mix(in oklch, var(--dex-boardpack-fav) 14%, transparent); color: color-mix(in oklch, var(--dex-boardpack-fav) 75%, var(--dex-boardpack-ink)); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--dex-boardpack-fav) 45%, transparent); }
  &[aria-pressed="true"] svg { opacity: 1; }
}
.dex-boardpack__form {
  display: grid; gap: 6px; margin-top: auto; padding-top: 10px;
  & textarea { width: 100%; resize: none; padding: 8px 10px; border-radius: 8px; border: 1px solid var(--dex-boardpack-line); background: var(--dex-boardpack-bg); font: 12.5px/1.4 var(--dex-boardpack-sans); color: inherit; }
  & textarea:focus-visible { outline: 2px solid var(--dex-boardpack-ink); outline-offset: 0; }
  & textarea[aria-invalid="true"] { border-color: var(--dex-boardpack-unf); }
  & button { padding: 6px 12px; border-radius: 8px; background: var(--dex-boardpack-ink); color: var(--dex-boardpack-paper); font-size: 12px; font-weight: 650; }
}
.dex-boardpack__frow { display: flex; align-items: center; justify-content: space-between; gap: 8px; }
.dex-boardpack__err { font-size: 11.5px; color: var(--dex-boardpack-unf); }

/* summary */
.dex-boardpack__view[data-view="sum"] { display: grid; grid-template-rows: max-content minmax(260px, 1fr); gap: 14px; overflow: auto; scrollbar-width: thin; }
.dex-boardpack__heads { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 14px; }
.dex-boardpack__headc {
  padding: 16px 18px 14px;
  & .big { margin: 6px 0 4px; font: 600 clamp(28px, 3.6cqi, 40px)/1 var(--dex-boardpack-serif); letter-spacing: -.02em; font-variant-numeric: tabular-nums lining-nums; }
  & .sub { font-size: 12.5px; color: var(--dex-boardpack-mute); font-variant-numeric: tabular-nums; text-wrap: pretty; }
  & .vf { color: var(--dex-boardpack-fav); font-weight: 650; } & .vu { color: var(--dex-boardpack-unf); font-weight: 650; }
  & .bul { position: relative; height: 10px; margin-top: 12px; border-radius: 3px; background: var(--dex-boardpack-soft); }
  & .bul i { position: absolute; left: 0; top: 2px; bottom: 2px; width: calc(var(--a) * 1%); border-radius: 2px; background: var(--dex-boardpack-ink); transform-origin: left; animation: dex-boardpack-grow .9s var(--dex-boardpack-out) both .2s; }
  & .bul b { position: absolute; top: -3px; bottom: -3px; left: calc(var(--b) * 1%); width: 2px; background: var(--dex-boardpack-unf); }
}
.dex-boardpack__bridge { display: flex; flex-direction: column; padding: 14px 16px 10px; --i: 3; }
.dex-boardpack__bhead { display: flex; align-items: baseline; justify-content: space-between; gap: 10px; flex-wrap: wrap; & h3 { font: 600 17px var(--dex-boardpack-serif); } & p { font-size: 12px; color: var(--dex-boardpack-mute); } }
.dex-boardpack__bplot { position: relative; flex: 1; min-height: 200px; }
.dex-boardpack__bchart {
  position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible;
  & text { font: 11px var(--dex-boardpack-sans); fill: var(--dex-boardpack-mute); font-variant-numeric: tabular-nums; }
  & .gl { stroke: var(--dex-boardpack-hair); }
  & .ax { font: 10px var(--dex-boardpack-mono); fill: var(--dex-boardpack-faint); }
  & .cn { stroke: color-mix(in oklch, var(--dex-boardpack-ink) 40%, transparent); stroke-dasharray: 3 3; }
  & .tot rect { fill: var(--dex-boardpack-ink); }
  & .f rect { fill: var(--dex-boardpack-fav); }
  & .u rect { fill: var(--dex-boardpack-unf); }
  & .vl { font-weight: 700; fill: var(--dex-boardpack-ink); }
  & .nm { font: 600 12.5px var(--dex-boardpack-serif); fill: var(--dex-boardpack-ink); }
  & g.step { cursor: pointer; outline: none; }
  & g.step .hit { fill: transparent; }
  & g.step:hover .hit, & g.step:focus-visible .hit { fill: var(--dex-boardpack-soft); }
  & g.step:focus-visible .hit { stroke: var(--dex-boardpack-ink); stroke-width: 1.5; }
}
.dex-boardpack__bchart.enter .bar { transform-box: fill-box; transform-origin: left; animation: dex-boardpack-grow .8s var(--dex-boardpack-out) both; animation-delay: calc(150ms + var(--i) * 110ms); }

/* commentary letter */
.dex-boardpack__view[data-view="com"] { overflow: auto; scrollbar-width: thin; }
.dex-boardpack__letter { max-width: 700px; margin: 0 auto; padding: 4px 4px 24px; display: grid; gap: 14px; }
.dex-boardpack__intro { font: 400 15px/1.55 var(--dex-boardpack-serif); text-wrap: pretty; color: var(--dex-boardpack-ink); & b { font-weight: 650; } }
.dex-boardpack__item {
  display: grid; gap: 6px; padding: 16px 18px; border-left: 3px solid var(--c, var(--dex-boardpack-line));
  & h4 { display: flex; align-items: baseline; justify-content: space-between; gap: 10px; font: 600 17px/1.2 var(--dex-boardpack-serif); }
  & h4 span { font: 650 12.5px var(--dex-boardpack-sans); color: var(--c); font-variant-numeric: tabular-nums; white-space: nowrap; }
  & p { font: 400 14px/1.55 var(--dex-boardpack-serif); text-wrap: pretty; }
  & .who { display: flex; align-items: center; justify-content: space-between; gap: 8px; font-size: 11.5px; color: var(--dex-boardpack-mute); flex-wrap: wrap; }
  &.u { --c: var(--dex-boardpack-unf); } &.f { --c: var(--dex-boardpack-fav); }
}
@supports (animation-timeline: view()) {
  .dex-boardpack__item { animation: dex-boardpack-rise linear both; animation-timeline: view(); animation-range: entry 0% entry 70%; }
}

/* overlays */
.dex-boardpack__tip {
  position: absolute; left: 0; top: 0; z-index: 30; pointer-events: none; min-width: 160px; padding: 8px 10px; border-radius: 8px;
  background: var(--dex-boardpack-ink); color: var(--dex-boardpack-paper); font-size: 12px; line-height: 1.5;
  box-shadow: 0 12px 28px -12px color-mix(in oklch, var(--dex-boardpack-ink) 80%, transparent);
  opacity: 0; scale: .96; transition: opacity .14s, scale .2s var(--dex-boardpack-out);
  & b { display: block; font: 600 13px var(--dex-boardpack-serif); margin-bottom: 2px; }
  & span { display: flex; justify-content: space-between; gap: 14px; font-variant-numeric: tabular-nums; color: color-mix(in oklch, var(--dex-boardpack-paper) 70%, transparent); }
  & em { font-style: normal; font-weight: 650; color: var(--dex-boardpack-paper); }
  &.on { opacity: 1; scale: 1; }
}
.dex-boardpack__toast {
  position: absolute; left: 50%; bottom: 18px; z-index: 40; translate: -50% 0; max-width: calc(100% - 32px); padding: 10px 14px; border-radius: 10px;
  background: var(--dex-boardpack-ink); color: var(--dex-boardpack-paper); font-weight: 600; font-size: 12.5px; pointer-events: none;
  box-shadow: 0 18px 40px -16px color-mix(in oklch, var(--dex-boardpack-ink) 80%, transparent);
  opacity: 0; transform: translateY(12px); transition: opacity .25s, transform .5s var(--dex-boardpack-spring);
  &.on { opacity: 1; transform: none; }
  &:empty { display: none; }
}

@keyframes dex-boardpack-rise { from { opacity: 0; transform: translateY(10px); } }
@keyframes dex-boardpack-grow { from { transform: scaleX(0); } }
@keyframes dex-boardpack-growy { from { transform: scaleY(0); } }

@container (width < 980px) {
  .dex-boardpack__shell { grid-template-columns: 66px minmax(0, 1fr); }
  .dex-boardpack__side { align-items: center; padding: 18px 10px; }
  .dex-boardpack__lbl { display: none; }
  .dex-boardpack__brand { padding: 0 0 14px; }
  .dex-boardpack__nav button { padding: 9px; justify-content: center; }
  .dex-boardpack__badge { position: absolute; top: 2px; right: 0; min-width: 16px; padding: 0 4px; font-size: 10px; background: var(--dex-boardpack-unf); color: var(--dex-boardpack-paper); }
  .dex-boardpack__sign { grid-template-columns: 1fr; justify-items: center; padding: 12px 0 0; }
  .dex-boardpack__approve { width: 40px; height: 40px; padding: 0; }
  .dex-boardpack__view[data-view="pl"] { grid-template-columns: minmax(0, 1fr) 260px; }
  .dex-boardpack__table { min-width: 440px; & th.dvh { width: 60px; } & th.dvh span { display: none; } & td, & th { padding-inline: 5px; } & td:first-child { min-width: 112px; } & tr.ln td:first-child { padding-left: 16px; } }
  .dex-boardpack__dv { width: 54px; }
  .dex-boardpack__legend { display: none; }
}
@container (width < 760px) {
  .dex-boardpack__shell { grid-template-columns: minmax(0, 1fr); grid-template-rows: auto minmax(0, 1fr); }
  .dex-boardpack__side { flex-direction: row; align-items: center; padding: 10px 12px; border-right: 0; border-bottom: 1px solid var(--dex-boardpack-line); overflow: visible; }
  .dex-boardpack__brand { padding: 0 6px 0 0; }
  .dex-boardpack__nav { display: flex; gap: 4px; }
  .dex-boardpack__sign { margin: 0 0 0 auto; padding: 0; border: 0; grid-template-columns: auto auto; gap: 8px; }
  .dex-boardpack__ring { width: 38px; height: 38px; }
  .dex-boardpack__approve { width: 38px; height: 38px; grid-column: auto; }
  .dex-boardpack__main { padding: 14px; overflow: auto; grid-template-rows: auto auto; }
  .dex-boardpack__view[data-view="pl"] { grid-template-columns: minmax(0, 1fr); grid-template-rows: 420px max-content; }
  .dex-boardpack__detail { overflow: visible; }
  .dex-boardpack__heads { grid-template-columns: minmax(0, 1fr); }
  .dex-boardpack__view[data-view="sum"], .dex-boardpack__view[data-view="com"] { overflow: visible; }
  .dex-boardpack__bplot { min-height: 240px; }
  .dex-boardpack__legend { display: none; }
}
@container (width < 480px) {
  .dex-boardpack__thr input { width: 120px; }
  .dex-boardpack__item { padding: 14px; }
}

@media (prefers-reduced-motion: reduce) {
  .dex-boardpack__paper, .dex-boardpack__item, .dex-boardpack__note .notes li { animation: none; }
  .dex-boardpack__table.enter .dex-boardpack__dv i, .dex-boardpack__mchart.enter rect.bar, .dex-boardpack__bchart.enter .bar, .dex-boardpack__headc .bul i { animation: none; }
  .dex-boardpack__dv i, .dex-boardpack__ring, .dex-boardpack__toggle .sw::after, .dex-boardpack__toast { transition: none; }
}

