const RM = !!(window.matchMedia && matchMedia('(prefers-reduced-motion: reduce)').matches);
const $ = (s, el) => (el || root).querySelector(s);
const $$ = (s, el) => Array.from((el || root).querySelectorAll(s));
const NF = new Intl.NumberFormat('en-US');
const k$ = (v) => (v < 0 ? '−$' : '$') + NF.format(Math.abs(Math.round(v))) + 'k';
const sgn = (v) => (v > 0 ? '+' : v < 0 ? '−' : '±');
const pc = (v) => sgn(v) + Math.abs(v * 100).toFixed(1) + '%';
const esc = (s) => String(s).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));

/* ------------------------------------------------------------------ data ($ thousands, Jan-Sep 2026) */
const MON = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep'];
const PER = {
  m: { idx: [8], name: 'September', long: 'In September', floor: 20 },
  q: { idx: [6, 7, 8], name: 'Q3', long: 'In the third quarter', floor: 50 },
  y: { idx: [0, 1, 2, 3, 4, 5, 6, 7, 8], name: 'Year to date', long: 'Year to date', floor: 100 }
};
const LEAF = {
  ins: { name: 'Instruments', kind: 'rev', who: 'Tomas Rehnquist, VP Sales',
    b: [1450, 1480, 1720, 1500, 1540, 1810, 1520, 1560, 1880], a: [1432, 1505, 1698, 1521, 1510, 1846, 1548, 1502, 1570],
    note: 'Two Kestrel-9 confocal systems for Aalborg University Hospital ($310k) cleared customs on 5 October, a week after the cut-off. Both are installed; the revenue lands in October, so this is timing rather than lost demand.' },
  con: { name: 'Consumables', kind: 'rev', who: 'Ines Barrow, Commercial Operations',
    b: [610, 615, 640, 630, 640, 660, 650, 655, 680], a: [622, 631, 668, 655, 671, 702, 688, 709, 742],
    note: 'The Lindqvist Diagnostics reagent contract renewed in April at 1.4 times the prior volume. Run-rate has held above budget every month since, and the Q4 forecast is lifted by $160k.' },
  svc: { name: 'Service contracts', kind: 'rev', who: 'Ines Barrow, Commercial Operations',
    b: [390, 392, 395, 398, 400, 402, 405, 408, 410], a: [388, 390, 396, 401, 404, 405, 411, 414, 419],
    note: 'Tracking budget. The attach rate on new instruments is 71% against the 70% planned.' },
  mat: { name: 'Materials', kind: 'cost', who: 'Dev Malhotra, COO',
    b: [610, 622, 700, 626, 640, 734, 637, 654, 763], a: [598, 630, 690, 640, 628, 751, 652, 640, 672],
    note: 'Lower in September because the two Kestrel-9 builds were held, partly offset by a 4% resin price rise from the Malmö supplier since June.' },
  lab: { name: 'Direct labour', kind: 'cost', who: 'Dev Malhotra, COO',
    b: [300, 300, 310, 305, 305, 315, 310, 310, 320], a: [302, 305, 318, 309, 311, 322, 318, 329, 341],
    note: 'Overtime on the second assembly shift to clear the Q3 build plan. The shift converts to permanent hires in November at a lower hourly cost.' },
  frt: { name: 'Freight & duty', kind: 'cost', who: 'Dev Malhotra, COO',
    b: [58, 59, 66, 60, 61, 70, 61, 62, 72], a: [57, 60, 64, 61, 60, 69, 78, 81, 93],
    note: 'The 12% EU tariff surcharge on optical assemblies took effect on 1 July and was not in budget. Routing through the Rotterdam bonded warehouse from November should recover about half.' },
  rnd: { name: 'Research & development', kind: 'cost', who: 'Dr Hana Okafor, CTO',
    b: [520, 520, 530, 535, 535, 540, 545, 545, 550], a: [508, 512, 515, 526, 531, 522, 534, 529, 538],
    note: 'Two senior optics hires budgeted for July now start in October. No change to the Kestrel-11 milestone.' },
  snm: { name: 'Sales & marketing', kind: 'cost', who: 'Tomas Rehnquist, VP Sales',
    b: [430, 440, 470, 445, 450, 480, 455, 460, 520], a: [425, 452, 478, 440, 462, 476, 470, 488, 571],
    note: 'The Lab Expo Frankfurt booth ($58k) was invoiced in September; the budget had it in October. Full-year spend is on budget.' },
  gna: { name: 'General & admin', kind: 'cost', who: 'Clara Wynn, CFO',
    b: [260, 260, 265, 265, 265, 270, 270, 270, 275], a: [262, 258, 266, 270, 264, 268, 275, 291, 286],
    note: 'ERP migration consultants ran four weeks past plan. Cutover completed on 14 September and no further spend is expected.' }
};
const sumS = (ids, f) => MON.map((_, i) => ids.reduce((t, id) => t + LEAF[id][f][i], 0));
const SUB = {
  trev: { name: 'Total revenue', kind: 'rev', parts: ['ins', 'con', 'svc'] },
  tcos: { name: 'Total cost of sales', kind: 'cost', parts: ['mat', 'lab', 'frt'] },
  topx: { name: 'Total operating expenses', kind: 'cost', parts: ['rnd', 'snm', 'gna'] }
};
Object.values(SUB).forEach((s) => { s.a = sumS(s.parts, 'a'); s.b = sumS(s.parts, 'b'); });
SUB.gp = { name: 'Gross profit', kind: 'rev', a: SUB.trev.a.map((v, i) => v - SUB.tcos.a[i]), b: SUB.trev.b.map((v, i) => v - SUB.tcos.b[i]) };
SUB.ebitda = { name: 'EBITDA', kind: 'rev', a: SUB.gp.a.map((v, i) => v - SUB.topx.a[i]), b: SUB.gp.b.map((v, i) => v - SUB.topx.b[i]) };
const ALL = Object.assign({}, LEAF, SUB);
const ROWS = [['h', 'Revenue'], ['l', 'ins'], ['l', 'con'], ['l', 'svc'], ['s', 'trev'],
  ['h', 'Cost of sales'], ['l', 'mat'], ['l', 'lab'], ['l', 'frt'], ['s', 'tcos'], ['s', 'gp'],
  ['h', 'Operating expenses'], ['l', 'rnd'], ['l', 'snm'], ['l', 'gna'], ['s', 'topx'], ['t', 'ebitda']];

/* ------------------------------------------------------------------ state */
let per = 'm', thr = 5, order = 'pl', onlyMat = false, sel = 'ins', view = 'pl', approved = false;
const explained = new Set(['frt', 'snm']);
const notes = {};

function fig(id) {
  const L = ALL[id], ix = PER[per].idx;
  const a = ix.reduce((t, i) => t + L.a[i], 0), b = ix.reduce((t, i) => t + L.b[i], 0);
  const fav = L.kind === 'rev' ? a - b : b - a;
  return { a, b, fav, p: b ? fav / Math.abs(b) : 0 };
}
const isMat = (id) => { if (!LEAF[id]) return false; const f = fig(id); return Math.abs(f.p) * 100 >= thr && Math.abs(f.fav) >= PER[per].floor; };
const matList = () => Object.keys(LEAF).filter(isMat);

/* ------------------------------------------------------------------ helpers */
const tip = $('.dex-boardpack__tip'), toastEl = $('.dex-boardpack__toast');
function tipAt(x, y) {
  const r = root.getBoundingClientRect(), w = tip.offsetWidth, h = tip.offsetHeight;
  const l = Math.min(Math.max(8, x - r.left + 14), r.width - w - 8);
  let t = y - r.top - h - 12; if (t < 8) t = y - r.top + 16;
  tip.style.translate = Math.round(l) + 'px ' + Math.round(t) + 'px';
}
let toastT = 0;
function toast(msg) { toastEl.textContent = msg; toastEl.classList.add('on'); clearTimeout(toastT); toastT = setTimeout(() => toastEl.classList.remove('on'), 2800); }
function radios(group, cur, pick) {
  const set = (v) => $$('button', group).forEach((b) => { const on = b.dataset.v === v; b.setAttribute('aria-checked', on); b.tabIndex = on ? 0 : -1; });
  group.addEventListener('click', (e) => { const b = e.target.closest('button'); if (b && b.getAttribute('aria-checked') !== 'true') { set(b.dataset.v); pick(b.dataset.v); } });
  group.addEventListener('keydown', (e) => {
    const bs = $$('button', group), i = bs.indexOf(document.activeElement); if (i < 0) return;
    const j = e.key === 'ArrowRight' || e.key === 'ArrowDown' ? (i + 1) % bs.length : e.key === 'ArrowLeft' || e.key === 'ArrowUp' ? (i - 1 + bs.length) % bs.length : -1;
    if (j < 0) return; e.preventDefault(); bs[j].focus(); set(bs[j].dataset.v); pick(bs[j].dataset.v);
  });
  set(cur);
}
const CHECK = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 12.5l4.5 4.5L19 7.5"/></svg>';

/* ------------------------------------------------------------------ table */
const tbody = $('[data-tbody]'), table = $('.dex-boardpack__table');
tbody.innerHTML = ROWS.map((r, n) => {
  if (r[0] === 'h') return '<tr class="hrow" data-n="' + n + '"><td colspan="7">' + r[1] + '</td></tr>';
  const id = r[1], L = ALL[id], cls = r[0] === 'l' ? 'ln' : r[0] === 's' ? 'sub' : 'tot';
  return '<tr class="' + cls + '" data-n="' + n + '" data-id="' + id + '" tabindex="-1" aria-selected="false" style="--i:' + n + '"><td>' + L.name + (id === 'gp' ? '<small data-gm></small>' : '') + '</td>' +
    '<td data-a></td><td data-b></td><td data-v></td><td data-p></td><td><span class="dex-boardpack__dv"><i class="f"></i><i class="u"></i></span></td><td data-st></td></tr>';
}).join('');
table.classList.add('enter');
function paintRows() {
  $$('tr[data-id]', tbody).forEach((tr) => {
    const id = tr.dataset.id, f = fig(id), cls = f.fav >= 0 ? 'vf' : 'vu';
    tr.querySelector('[data-a]').textContent = NF.format(f.a);
    tr.querySelector('[data-b]').textContent = NF.format(f.b);
    tr.querySelector('[data-v]').innerHTML = '<span class="' + cls + '">' + sgn(f.fav) + NF.format(Math.abs(f.fav)) + '<span class="fu">' + (f.fav >= 0 ? 'F' : 'U') + '</span></span>';
    tr.querySelector('[data-p]').innerHTML = '<span class="' + cls + '">' + pc(f.p) + '</span>';
    const v = Math.min(1, Math.abs(f.p) / 0.25).toFixed(3), mat = isMat(id);
    const [fi, ui] = tr.querySelectorAll('.dex-boardpack__dv i');
    fi.style.setProperty('--v', f.fav >= 0 ? v : 0); ui.style.setProperty('--v', f.fav < 0 ? v : 0);
    fi.classList.toggle('m', !mat && !!LEAF[id]); ui.classList.toggle('m', !mat && !!LEAF[id]);
    tr.querySelector('[data-st]').innerHTML = mat ? (explained.has(id) ? '<span class="dex-boardpack__st ok" title="Explained">' + CHECK + '</span>' : '<span class="dex-boardpack__st need" title="Needs commentary">!</span>') : '';
    tr.dataset.mat = mat ? 1 : 0;
    if (id === 'gp') tr.querySelector('[data-gm]').textContent = (f.a / fig('trev').a * 100).toFixed(1) + '% margin';
  });
}
function arrange(animate) {
  const trs = $$('tr', tbody);
  const before = new Map(trs.map((tr) => { const r = tr.getBoundingClientRect(); return [tr, r.height ? r.top : null]; }));
  let seq;
  if (order === 'var') {
    const leaves = trs.filter((tr) => tr.classList.contains('ln')).sort((x, y) => Math.abs(fig(y.dataset.id).fav) - Math.abs(fig(x.dataset.id).fav));
    seq = leaves.concat(trs.filter((tr) => !tr.classList.contains('ln')));
    trs.forEach((tr) => tr.classList.toggle('gone', !tr.classList.contains('ln') || (onlyMat && tr.dataset.mat !== '1')));
  } else {
    seq = trs.slice().sort((x, y) => +x.dataset.n - +y.dataset.n);
    trs.forEach((tr) => tr.classList.toggle('gone', onlyMat && tr.classList.contains('ln') && tr.dataset.mat !== '1'));
  }
  seq.forEach((tr) => tbody.appendChild(tr));
  if (!animate || RM) return;
  trs.forEach((tr) => {
    if (tr.classList.contains('gone')) return;
    const b = before.get(tr), r = tr.getBoundingClientRect();
    if (b == null) tr.animate([{ opacity: 0 }, { opacity: 1 }], { duration: 320, easing: 'ease-out' });
    else if (Math.abs(b - r.top) > 1) tr.animate([{ transform: 'translateY(' + (b - r.top) + 'px)' }, { transform: 'none' }], { duration: 520, easing: 'cubic-bezier(.2,.9,.25,1)' });
  });
}
function selectRow(id, focus) {
  sel = id;
  $$('tr[data-id]', tbody).forEach((tr) => { const on = tr.dataset.id === id; tr.setAttribute('aria-selected', on); tr.tabIndex = on ? 0 : -1; if (on && focus) tr.focus(); });
  renderDetail();
}
tbody.addEventListener('click', (e) => { const tr = e.target.closest('tr[data-id]'); if (tr && tr.dataset.id !== sel) selectRow(tr.dataset.id); });
tbody.addEventListener('keydown', (e) => {
  const rows = $$('tr[data-id]', tbody).filter((tr) => !tr.classList.contains('gone'));
  const i = rows.indexOf(document.activeElement); if (i < 0) return;
  const j = e.key === 'ArrowDown' ? Math.min(rows.length - 1, i + 1) : e.key === 'ArrowUp' ? Math.max(0, i - 1) : e.key === 'Home' ? 0 : e.key === 'End' ? rows.length - 1 : -1;
  if (j >= 0) { e.preventDefault(); selectRow(rows[j].dataset.id, true); }
  if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); if (LEAF[sel] && isMat(sel)) toggleExplained(sel); }
});

/* ------------------------------------------------------------------ detail */
const mchart = $('[data-mchart]');
let mDrawn = false;
function drawMonthly(id, enter) {
  const W = mchart.clientWidth, H = mchart.clientHeight; if (!W || !H) return;
  mchart._size = W + 'x' + H;
  const L = ALL[id], vals = MON.map((_, i) => L.kind === 'rev' ? L.a[i] - L.b[i] : L.b[i] - L.a[i]);
  const mx = Math.max(10, ...vals.map(Math.abs)), raw = mx / 2, mag = Math.pow(10, Math.floor(Math.log10(raw))), st = Math.ceil(raw / mag) * mag, top = st * 2;
  const P = 34, T = 8, B = 18, x = (i) => P + (W - P - 4) * (i + 0.5) / 9, bw = Math.min(18, (W - P) / 9 * 0.62), y = (v) => T + (H - T - B) * (1 - (v + top) / (2 * top));
  const ix = PER[per].idx;
  let s = '';
  [-top, -st, 0, st, top].forEach((v) => { s += '<line class="' + (v ? 'gl' : 'zl') + '" x1="' + P + '" x2="' + W + '" y1="' + y(v).toFixed(1) + '" y2="' + y(v).toFixed(1) + '"/><text x="' + (P - 6) + '" y="' + (y(v) + 3).toFixed(1) + '" text-anchor="end">' + (v > 0 ? '+' : v < 0 ? '−' : '') + NF.format(Math.abs(v)) + '</text>'; });
  vals.forEach((v, i) => {
    const y0 = y(0), y1 = y(v), on = ix.includes(i);
    s += '<rect class="bar ' + (v >= 0 ? 'f p' : 'u n') + (on ? '' : ' out') + '" data-m="' + i + '" style="--i:' + i + '" x="' + (x(i) - bw / 2).toFixed(1) + '" y="' + Math.min(y0, y1).toFixed(1) + '" width="' + bw.toFixed(1) + '" height="' + Math.max(1, Math.abs(y1 - y0)).toFixed(1) + '" rx="2"/>';
    s += '<text class="ml' + (on ? ' in' : '') + '" x="' + x(i).toFixed(1) + '" y="' + (H - 4) + '" text-anchor="middle">' + MON[i][0] + '</text>';
  });
  mchart.innerHTML = s;
  mchart.classList.toggle('enter', !!enter);
  mchart._vals = vals; mchart._x = x; mchart._P = P;
}
mchart.addEventListener('pointermove', (e) => {
  if (!mchart._vals) return;
  const r = mchart.getBoundingClientRect(), px = e.clientX - r.left, W = r.width;
  const i = Math.max(0, Math.min(8, Math.floor((px - mchart._P) / ((W - mchart._P - 4) / 9))));
  $$('rect.bar', mchart).forEach((b) => b.classList.toggle('hov', +b.dataset.m === i));
  const L = ALL[sel], v = mchart._vals[i];
  tip.innerHTML = '<b>' + MON[i] + ' 2026 · ' + esc(L.name) + '</b><span>Actual <em>' + k$(L.a[i]) + '</em></span><span>Budget <em>' + k$(L.b[i]) + '</em></span><span>Variance <em>' + sgn(v) + '$' + NF.format(Math.abs(v)) + 'k ' + (v >= 0 ? 'F' : 'U') + '</em></span>';
  tip.classList.add('on'); tipAt(e.clientX, e.clientY);
});
mchart.addEventListener('pointerleave', () => { tip.classList.remove('on'); $$('rect.hov', mchart).forEach((b) => b.classList.remove('hov')); });

function noteBlock(id) {
  const L = ALL[id];
  if (!LEAF[id]) {
    const parts = L.parts || (id === 'gp' ? ['trev', 'tcos'] : ['gp', 'topx']);
    const big = parts.map((p) => [p, fig(p).fav]).sort((x, y) => Math.abs(y[1]) - Math.abs(x[1]))[0];
    return '<p class="quiet">' + esc(L.name) + ' rolls up ' + parts.map((p) => esc(ALL[p].name.toLowerCase())).join(', ') + '. The largest contributor this period is <b>' + esc(ALL[big[0]].name.toLowerCase()) + '</b> at ' + sgn(big[1]) + '$' + NF.format(Math.abs(big[1])) + 'k.</p>';
  }
  const mat = isMat(id), ex = explained.has(id);
  const list = (notes[id] || []).map((n) => '<li><b>' + esc(n.who) + ' · ' + esc(n.when) + '</b>' + esc(n.text) + '</li>').join('');
  return '<blockquote>' + esc(L.note) + '</blockquote><div class="who"><span>' + esc(L.who) + '</span>' +
    (mat ? '<button type="button" class="dex-boardpack__explain" data-explain="' + id + '" aria-pressed="' + ex + '">' + CHECK + (ex ? 'Explained' : 'Mark explained') + '</button>' : '<span>Within materiality</span>') + '</div>' +
    (list ? '<ul class="notes">' + list + '</ul>' : '');
}
function renderDetail(enter) {
  const L = ALL[sel], f = fig(sel), P = PER[per];
  $('[data-d-kicker]').textContent = (LEAF[sel] ? (L.kind === 'rev' ? 'Revenue line' : 'Cost line') : 'Subtotal') + ' · ' + P.name;
  $('[data-d-name]').textContent = L.name;
  $('[data-d-fig]').innerHTML = 'Actual ' + k$(f.a) + ' · Budget ' + k$(f.b) + '<br><b class="' + (f.fav >= 0 ? 'vf' : 'vu') + '">' + sgn(f.fav) + '$' + NF.format(Math.abs(f.fav)) + 'k (' + pc(f.p) + ') ' + (f.fav >= 0 ? 'favourable' : 'unfavourable') + '</b>';
  $('[data-d-note]').innerHTML = noteBlock(sel);
  $('[data-form]').hidden = !LEAF[sel];
  drawMonthly(sel, enter || !mDrawn); mDrawn = true;
}
const detail = $('[data-detail]');
detail.addEventListener('click', (e) => { const b = e.target.closest('[data-explain]'); if (b) toggleExplained(b.dataset.explain); });
const form = $('[data-form]'), ta = $('[data-ta]'), err = $('[data-err]');
form.addEventListener('submit', (e) => {
  e.preventDefault();
  const t = ta.value.trim();
  if (t.length < 3) { ta.setAttribute('aria-invalid', 'true'); err.textContent = 'Write a note of at least three characters.'; ta.focus(); return; }
  ta.removeAttribute('aria-invalid'); err.textContent = '';
  (notes[sel] = notes[sel] || []).push({ who: 'Clara Wynn', when: 'just now', text: t });
  ta.value = '';
  $('[data-d-note]').innerHTML = noteBlock(sel);
  toast('Note added to ' + ALL[sel].name + '.');
});
ta.addEventListener('input', () => { if (ta.getAttribute('aria-invalid')) { ta.removeAttribute('aria-invalid'); err.textContent = ''; } });

/* ------------------------------------------------------------------ sign-off */
const approveBtn = $('[data-approve]');
function renderSign() {
  const mats = matList(), done = mats.filter((id) => explained.has(id)).length, left = mats.length - done;
  if (left > 0) approved = false;
  const ring = $('[data-ring]');
  ring.style.setProperty('--dex-boardpack-p', mats.length ? (done / mats.length * 100).toFixed(1) : 100);
  $('[data-ring-n]').textContent = done + '/' + mats.length;
  $('[data-sign-txt]').textContent = left ? left + ' material variance' + (left > 1 ? 's' : '') + ' still need' + (left > 1 ? '' : 's') + ' commentary.' : approved ? 'Approved for circulation.' : 'Every material variance is explained.';
  $('[data-badge]').textContent = left || '';
  approveBtn.classList.toggle('done', approved);
  $('[data-approve-lbl]').textContent = approved ? 'Approved' : 'Approve for circulation';
  if (left || approved) {
    approveBtn.setAttribute('aria-disabled', 'true');
    approveBtn.title = approved ? 'Already approved for circulation' : 'Explain every material variance first (' + left + ' left)';
  } else { approveBtn.removeAttribute('aria-disabled'); approveBtn.title = 'Approve the pack for circulation to the board'; }
}
approveBtn.addEventListener('click', () => {
  if (approveBtn.getAttribute('aria-disabled') === 'true') { toast(approveBtn.title + '.'); return; }
  approved = true; renderSign();
  toast('Board pack approved and queued for circulation on Fri 16 Oct.');
});
function toggleExplained(id) {
  if (explained.has(id)) explained.delete(id); else explained.add(id);
  paintRows(); renderSign();
  if (sel === id) $('[data-d-note]').innerHTML = noteBlock(id);
  if (view === 'com') renderLetter();
  const b = root.querySelector('[data-explain="' + id + '"]'); if (b) b.focus();
}

/* ------------------------------------------------------------------ summary */
const bchart = $('[data-bchart]');
function renderSummary() {
  const P = PER[per], r = fig('trev'), g = fig('gp'), e = fig('ebitda');
  const gmA = g.a / r.a, gmB = g.b / r.b;
  const card = (i, cap, big, sub, a, b) => '<div class="dex-boardpack__paper dex-boardpack__headc" style="--i:' + i + '"><p class="dex-boardpack__cap">' + cap + '</p><p class="big">' + big + '</p><p class="sub">' + sub + '</p>' +
    '<div class="bul" style="--a:' + a.toFixed(1) + ';--b:' + b.toFixed(1) + '" aria-hidden="true"><i></i><b></b></div></div>';
  const mx = (x, y) => Math.max(x, y) * 1.12;
  $('[data-heads]').innerHTML =
    card(0, 'Revenue · ' + P.name, k$(r.a), 'Budget ' + k$(r.b) + ' · <span class="' + (r.fav >= 0 ? 'vf' : 'vu') + '">' + pc(r.p) + '</span>', r.a / mx(r.a, r.b) * 100, r.b / mx(r.a, r.b) * 100) +
    card(1, 'Gross margin', (gmA * 100).toFixed(1) + '%', 'Budget ' + (gmB * 100).toFixed(1) + '% · <span class="' + (gmA >= gmB ? 'vf' : 'vu') + '">' + sgn(gmA - gmB) + Math.abs((gmA - gmB) * 100).toFixed(1) + ' pts</span>', gmA * 100, gmB * 100) +
    card(2, 'EBITDA · ' + P.name, k$(e.a), 'Budget ' + k$(e.b) + ' · <span class="' + (e.fav >= 0 ? 'vf' : 'vu') + '">' + sgn(e.fav) + '$' + NF.format(Math.abs(e.fav)) + 'k</span>', Math.max(0, e.a) / mx(e.a, e.b) * 100, e.b / mx(e.a, e.b) * 100);
  drawBridge(true);
}
function drawBridge(enter) {
  const W = bchart.clientWidth, H = bchart.clientHeight; if (!W || !H) return;
  bchart._size = W + 'x' + H;
  const e = fig('ebitda'), steps = [['Budget EBITDA', e.b, 'tot', null], ['Revenue', fig('trev').fav, null, 'trev'], ['Cost of sales', fig('tcos').fav, null, 'tcos'], ['Operating expenses', fig('topx').fav, null, 'topx'], ['Actual EBITDA', e.a, 'tot', 'ebitda']];
  let run = 0; const segs = steps.map((s) => { if (s[2] === 'tot') { run = s[1]; return [0, s[1]]; } const a = run; run += s[1]; return [a, run]; });
  const lo = Math.min(0, ...segs.flat()), hi = Math.max(...segs.flat());
  const LW = Math.min(170, W * 0.3), RW = 92, x = (v) => LW + (W - LW - RW) * (v - lo) / (hi - lo || 1);
  const rowH = (H - 24) / steps.length, bh = Math.min(30, rowH * 0.56);
  let s = '';
  const span = hi - lo, raw = span / 4, mag = Math.pow(10, Math.floor(Math.log10(raw))), st = Math.ceil(raw / mag) * mag;
  for (let v = Math.ceil(lo / st) * st; v <= hi; v += st) s += '<line class="gl" x1="' + x(v).toFixed(1) + '" x2="' + x(v).toFixed(1) + '" y1="0" y2="' + (H - 18) + '"/><text class="ax" x="' + x(v).toFixed(1) + '" y="' + (H - 4) + '" text-anchor="middle">' + NF.format(v) + '</text>';
  steps.forEach((stp, i) => {
    const [a, b] = segs[i], y = rowH * i + (rowH - bh) / 2, cls = stp[2] === 'tot' ? 'tot' : stp[1] >= 0 ? 'f' : 'u';
    const val = stp[2] === 'tot' ? k$(stp[1]) : sgn(stp[1]) + '$' + NF.format(Math.abs(stp[1])) + 'k';
    const act = stp[3] ? ' role="button" tabindex="0" data-go="' + stp[3] + '" aria-label="' + stp[0] + ', ' + val + '. Open lines"' : '';
    s += '<g class="' + cls + (stp[3] ? ' step' : '') + '"' + act + '>' + (stp[3] ? '<rect class="hit" x="2" y="' + (rowH * i + 2).toFixed(1) + '" width="' + (W - 4) + '" height="' + (rowH - 4).toFixed(1) + '" rx="8"/>' : '') +
      '<text class="nm" x="12" y="' + (y + bh / 2 + 4).toFixed(1) + '">' + stp[0] + '</text>' +
      '<rect class="bar" style="--i:' + i + ';transform-origin:' + (cls === 'u' ? 'right' : 'left') + '" x="' + x(Math.min(a, b)).toFixed(1) + '" y="' + y.toFixed(1) + '" width="' + Math.max(2, Math.abs(x(b) - x(a))).toFixed(1) + '" height="' + bh.toFixed(1) + '" rx="3"/>' +
      '<text class="vl" x="' + (W - 8) + '" y="' + (y + bh / 2 + 4).toFixed(1) + '" text-anchor="end">' + val + '</text></g>';
    if (i < steps.length - 1) s += '<line class="cn" x1="' + x(b).toFixed(1) + '" x2="' + x(b).toFixed(1) + '" y1="' + (y + bh).toFixed(1) + '" y2="' + (rowH * (i + 1) + (rowH - bh) / 2).toFixed(1) + '"/>';
  });
  bchart.innerHTML = s;
  bchart.classList.toggle('enter', !!enter);
}
function openFromBridge(id) { go('pl'); selectRow(id, true); }
bchart.addEventListener('click', (e) => { const g = e.target.closest('[data-go]'); if (g) openFromBridge(g.dataset.go); });
bchart.addEventListener('keydown', (e) => { const g = e.target.closest('[data-go]'); if (g && (e.key === 'Enter' || e.key === ' ')) { e.preventDefault(); openFromBridge(g.dataset.go); } });

/* ------------------------------------------------------------------ commentary */
const letter = $('[data-letter]');
function renderLetter() {
  const P = PER[per], r = fig('trev'), e = fig('ebitda'), mats = matList().sort((x, y) => Math.abs(fig(y).fav) - Math.abs(fig(x).fav));
  const done = mats.filter((id) => explained.has(id)).length;
  let s = '<p class="dex-boardpack__intro">' + P.long + ', revenue was <b>' + k$(r.a) + '</b> against a budget of ' + k$(r.b) + ' (' + pc(r.p) + ') and EBITDA was <b>' + k$(e.a) + '</b> against ' + k$(e.b) + '. ' +
    (mats.length ? '<b>' + mats.length + '</b> line' + (mats.length > 1 ? 's' : '') + ' breach the ' + thr + '% materiality threshold; ' + done + ' ' + (done === 1 ? 'is' : 'are') + ' explained below.' : 'No line breaches the ' + thr + '% materiality threshold.') + '</p>';
  s += mats.map((id) => {
    const f = fig(id), L = LEAF[id], ex = explained.has(id);
    return '<article class="dex-boardpack__paper dex-boardpack__item ' + (f.fav >= 0 ? 'f' : 'u') + '"><h4>' + L.name + '<span>' + sgn(f.fav) + '$' + NF.format(Math.abs(f.fav)) + 'k · ' + pc(f.p) + '</span></h4><p>' + esc(L.note) + '</p>' +
      '<div class="who"><span>' + esc(L.who) + ' · actual ' + k$(f.a) + ', budget ' + k$(f.b) + '</span><button type="button" class="dex-boardpack__explain" data-explain="' + id + '" aria-pressed="' + ex + '">' + CHECK + (ex ? 'Explained' : 'Mark explained') + '</button></div></article>';
  }).join('');
  letter.innerHTML = s;
}
letter.addEventListener('click', (e) => { const b = e.target.closest('[data-explain]'); if (b) toggleExplained(b.dataset.explain); });

/* ------------------------------------------------------------------ controls + views */
const HEAD = { sum: ['Section 1 · Headlines', 'Headlines for '], pl: ['Section 2 · Unaudited management accounts · $ thousands', 'Profit & loss against budget'], com: ['Section 3 · Variance commentary', 'What moved, and why'] };
function setHead() {
  $('[data-kicker]').textContent = HEAD[view][0];
  $('[data-h2]').textContent = view === 'sum' ? HEAD.sum[1] + (per === 'm' ? 'September' : per === 'q' ? 'the third quarter' : 'the year to date') : HEAD[view][1];
}
function go(v) {
  view = v;
  $$('.dex-boardpack__nav button').forEach((b) => { if (b.dataset.view === v) b.setAttribute('aria-current', 'page'); else b.removeAttribute('aria-current'); });
  $$('.dex-boardpack__view').forEach((s) => { s.hidden = s.dataset.view !== v; });
  tip.classList.remove('on');
  setHead();
  if (v === 'sum') renderSummary();
  if (v === 'com') renderLetter();
  if (v === 'pl') renderDetail(true);
}
$('.dex-boardpack__nav').addEventListener('click', (e) => { const b = e.target.closest('button'); if (b && b.dataset.view !== view) go(b.dataset.view); });
$('.dex-boardpack__nav').addEventListener('keydown', (e) => {
  const bs = $$('.dex-boardpack__nav button'), i = bs.indexOf(document.activeElement); if (i < 0) return;
  if (e.key === 'ArrowDown' || e.key === 'ArrowRight') { e.preventDefault(); bs[(i + 1) % bs.length].focus(); }
  if (e.key === 'ArrowUp' || e.key === 'ArrowLeft') { e.preventDefault(); bs[(i + bs.length - 1) % bs.length].focus(); }
});
function refresh() {
  table.classList.remove('enter');
  paintRows(); renderSign(); setHead();
  if (onlyMat || order === 'var') arrange(true);
  if (view === 'pl') renderDetail();
  if (view === 'sum') renderSummary();
  if (view === 'com') renderLetter();
}
radios($('[data-period]'), per, (v) => { per = v; refresh(); });
radios($('[data-order]'), order, (v) => { order = v; table.classList.remove('enter'); arrange(true); });
const exc = $('[data-exc]');
exc.addEventListener('click', () => { onlyMat = !onlyMat; exc.setAttribute('aria-pressed', onlyMat); table.classList.remove('enter'); arrange(true); });
const thrIn = $('[data-thr]');
thrIn.addEventListener('input', () => { thr = +thrIn.value; $('[data-thr-v]').textContent = thr + '%'; table.classList.remove('enter'); paintRows(); renderSign(); if (onlyMat) arrange(true); if (view === 'pl') $('[data-d-note]').innerHTML = noteBlock(sel); if (view === 'com') renderLetter(); });
root.addEventListener('keydown', (e) => { if (e.key === 'Escape') { tip.classList.remove('on'); toastEl.classList.remove('on'); } });

/* ------------------------------------------------------------------ mount */
paintRows();
selectRow(sel);
renderSign();
setHead();
if (window.ResizeObserver) {
  const ro = new ResizeObserver(() => {
    if (!root.isConnected) { ro.disconnect(); return; }
    if (view === 'pl' && mchart.clientWidth && mchart._size !== mchart.clientWidth + 'x' + mchart.clientHeight) drawMonthly(sel, false);
    if (view === 'sum' && bchart.clientWidth && bchart._size !== bchart.clientWidth + 'x' + bchart.clientHeight) drawBridge(false);
  });
  ro.observe(mchart); ro.observe(bchart);
}

