const RM = !!(window.matchMedia && matchMedia('(prefers-reduced-motion: reduce)').matches);
const $ = (s, el) => (el || root).querySelector(s);
const $$ = (s, el) => Array.from((el || root).querySelectorAll(s));
const UID = 'dex-planactual-' + Math.random().toString(36).slice(2, 8);
const SVGNS = 'http://www.w3.org/2000/svg';

/* ------------------------------------------------------------------ data ($M; Q4 FY26 is a forecast) */
const Q = [['Q1', 'FY25'], ['Q2', 'FY25'], ['Q3', 'FY25'], ['Q4', 'FY25'], ['Q1', 'FY26'], ['Q2', 'FY26'], ['Q3', 'FY26'], ['Q4', 'FY26']];
