    return '<div class="r" style="--i:' + n + ';--c:' + r.c + '"><b><i></i>' + r.name + '</b><span class="v"><em>' + f(r.a) + '</em> / ' + f(r.p) + ' <span class="' + (vv.good ? 'up' : 'dn') + '">' + vv.txt + '</span></span>' +
      '<span class="bul" aria-hidden="true" style="--a:' + (r.a / mx * 100).toFixed(1) + ';--p:' + (r.p / mx * 100).toFixed(1) + '"><i></i><s></s></span></div>';
  }).join('') + '</div>';
  if (rows.length > 1) {
    const vs = rows.map((r) => ({ r, d: (metric === 'gm' ? r.a - r.p : (r.a - r.p) * ((metric === 'opx' || r.up === false) ? -1 : 1)) }));
    const best = vs.slice().sort((x, y) => y.d - x.d)[0], worst = vs.slice().sort((x, y) => x.d - y.d)[0];
    const u = (d) => (metric === 'gm' ? Math.abs(d).toFixed(1) + ' pts' : '$' + Math.abs(d).toFixed(1) + 'M');
    h += '<p class="dex-planactual__say">' + (best.d > 0 ? '<b>' + best.r.name + '</b> is ' + u(best.d) + ' better than plan' : 'No line beat plan') + (worst.d < 0 ? '; <b>' + worst.r.name + '</b> is ' + u(worst.d) + ' worse.' : '.') + '</p>';
  }
  $('[data-detail]').innerHTML = h;
}
function renderKpis() {
  const m = MK[metric], f = (v) => fmt(metric, v);
  const k = [
    ['FY25 full year', fyTotal(metric, 25, 3, 'a'), fyTotal(metric, 25, 3, 'p'), 'Four quarters actual'],
    ['FY26 to date', fyTotal(metric, 26, 6, 'a'), fyTotal(metric, 26, 6, 'p'), 'Q1–Q3 actual'],
    ['FY26 outlook', fyTotal(metric, 26, 7, 'a'), fyTotal(metric, 26, 7, 'p'), 'With Q4 forecast'],
    ['Q4 FY26 forecast', at(metric, 7, 'a', false).tot, at(metric, 7, 'p', false).tot, 'Range ' + f(at(metric, 7, 'a', false).tot * (1 - RANGE)) + '–' + f(at(metric, 7, 'a', false).tot * (1 + RANGE))]
  ];
  $('[data-kpis]').innerHTML = k.map((x, i) => { const v = vari(metric, x[1], x[2]); return '<div style="--i:' + i + '"><dt>' + x[0] + ' vs ' + (basis === 'refc' ? 'reforecast' : 'plan') + '</dt><dd>' + f(x[1]) + '<small class="' + (v.good ? 'up' : 'dn') + '">' + v.txt + '</small></dd><p class="sub">' + x[3] + ' · plan ' + f(x[2]) + '</p></div>'; }).join('');
  void m;
}

/* ------------------------------------------------------------------ table */
const SORTS = [['i', 'Quarter'], ['p', 'Plan'], ['a', 'Actual'], ['d', 'Variance'], ['r', 'Variance %'], ['t', 'Attainment']];
const ARROW = '<svg viewBox="0 0 10 10" aria-hidden="true"><path d="M2 3.5L5 6.5 8 3.5"/></svg>';
$('[data-thead]').innerHTML = SORTS.map((s) => '<th scope="col" data-k="' + s[0] + '"><button type="button">' + s[1] + ARROW + '</button></th>').join('');
$('[data-thead]').addEventListener('click', (e) => {
  const th = e.target.closest('th'); if (!th) return;
  if (tableSort.k === th.dataset.k) tableSort.dir *= -1; else { tableSort.k = th.dataset.k; tableSort.dir = th.dataset.k === 'i' ? 1 : -1; }
  renderTable(true);
});
function renderTable(animate) {
  const m = MK[metric];
  $$('[data-thead] th').forEach((th) => { if (th.dataset.k === tableSort.k) th.setAttribute('aria-sort', tableSort.dir > 0 ? 'ascending' : 'descending'); else th.removeAttribute('aria-sort'); });
  const rows = Q.map((_, i) => {
    const a = at(metric, i, 'a').tot, p = at(metric, i, 'p').tot, v = vari(metric, a, p);
    const att = m.pct ? a / p * 100 : m.up ? (p > 0 ? a / p * 100 : a >= p ? 100 : 100 * p / a) : p / a * 100;
    return { i, a, p, d: (a - p) * (m.up ? 1 : -1), r: v.r, t: att, v };
  });
  rows.sort((x, y) => (x[tableSort.k] - y[tableSort.k]) * tableSort.dir);
  const tb = $('[data-tbody]');
  const before = new Map($$('tr', tb).map((tr) => [tr.dataset.i, tr.getBoundingClientRect().top]));
  tb.innerHTML = rows.map((r) => '<tr data-i="' + r.i + '" class="' + (r.i === FC ? 'fc' : '') + '"><td>' + qn(r.i) + (r.i === FC ? '<span class="tag">FCST</span>' : '') + '</td><td>' + fmt(metric, r.p) + '</td><td>' + fmt(metric, r.a) + '</td>' +
    '<td class="' + (r.v.good ? 'up' : 'dn') + '">' + (m.pct ? r.v.txt : (r.a - r.p >= 0 ? '+' : '−') + '$' + Math.abs(r.a - r.p).toFixed(metric === 'oi' ? 2 : 1) + 'M') + '</td><td class="' + (metric === 'oi' ? '' : r.v.good ? 'up' : 'dn') + '">' + (metric === 'oi' ? '<abbr title="Not meaningful: the plan is close to or below zero">n/m</abbr>' : m.pct ? (r.a / r.p * 100 - 100).toFixed(1) + '%' : r.v.txt) + '</td>' +
    '<td>' + (metric === 'oi' ? '<abbr title="Not meaningful for a loss-making plan">n/m</abbr>' : '<span class="att" style="--a:' + Math.max(0, r.t).toFixed(1) + ';--c:' + (r.v.good ? 'var(--dex-planactual-accent)' : 'var(--dex-planactual-neg)') + '"><i></i><s></s></span> ' + Math.round(r.t) + '%') + '</td></tr>').join('');
  const ft = (fy, upto, lbl) => { const a = fyTotal(metric, fy, upto, 'a'), p = fyTotal(metric, fy, upto, 'p'), v = vari(metric, a, p); return '<tr><td>' + lbl + '</td><td>' + fmt(metric, p) + '</td><td>' + fmt(metric, a) + '</td><td class="' + (v.good ? 'up' : 'dn') + '">' + (m.pct ? v.txt : (a - p >= 0 ? '+' : '−') + '$' + Math.abs(a - p).toFixed(1) + 'M') + '</td><td class="' + (v.good ? 'up' : 'dn') + '">' + (metric === 'oi' ? 'n/m' : v.txt) + '</td><td></td></tr>'; };
  $('[data-tfoot]').innerHTML = ft(25, 3, 'FY25 total') + ft(26, 7, 'FY26 outlook');
  if (animate && !RM) $$('tr', tb).forEach((tr) => { const b = before.get(tr.dataset.i); if (b == null) return; const d = b - tr.getBoundingClientRect().top; if (Math.abs(d) > 1) tr.animate([{ transform: 'translateY(' + d + 'px)' }, { transform: 'none' }], { duration: 480, easing: 'cubic-bezier(.2,.9,.25,1)' }); });
}

/* ------------------------------------------------------------------ chips, tabs, controls */
const chips = $('[data-chips]');
function renderChips() {
  const m = MK[metric], pd = partsDef(metric) || SEGS, st = m.parts === 'fn' ? fnOn : segOn, dis = !m.parts;
  chips.setAttribute('aria-label', m.parts === 'fn' ? 'Functions' : 'Segments');
  chips.innerHTML = pd.map((s) => '<button type="button" style="--c:' + s.c + '" data-k="' + s.k + '" aria-pressed="' + (dis ? 'true' : st[s.k]) + '"' + (dis ? ' aria-disabled="true" title="Operating income is reported for the whole company"' : ' title="Show or hide ' + s.name + '"') + '><i></i>' + s.name + '</button>').join('');
}
chips.addEventListener('click', (e) => {
  const b = e.target.closest('button'); if (!b) return;
  const m = MK[metric]; if (!m.parts || b.getAttribute('aria-disabled') === 'true') return;
  const st = m.parts === 'fn' ? fnOn : segOn;
  st[b.dataset.k] = !st[b.dataset.k];
  if (!Object.values(st).some(Boolean)) Object.keys(st).forEach((k) => { st[k] = true; });
  renderChips(); refresh();
});
const tabs = $('[data-tabs]');
tabs.innerHTML = METRICS.map((m) => '<button type="button" role="tab" data-k="' + m.k + '">' + m.name + '</button>').join('');
function setTabs() { $$('button', tabs).forEach((b) => { const on = b.dataset.k === metric; b.setAttribute('aria-selected', on); b.tabIndex = on ? 0 : -1; }); }
tabs.addEventListener('click', (e) => { const b = e.target.closest('button'); if (b && b.dataset.k !== metric) { metric = b.dataset.k; setTabs(); renderChips(); refresh(); } });
tabs.addEventListener('keydown', (e) => {
  const bs = $$('button', tabs), i = bs.indexOf(document.activeElement); if (i < 0) return;
  const j = e.key === 'ArrowRight' ? (i + 1) % bs.length : e.key === 'ArrowLeft' ? (i - 1 + bs.length) % bs.length : -1;
  if (j < 0) return; e.preventDefault(); bs[j].focus(); metric = bs[j].dataset.k; setTabs(); renderChips(); refresh();
});
radios($('[data-basis]'), basis, (v) => { basis = v; refresh(); });
radios($('[data-mode]'), mode, (v) => { mode = v; refresh(); });
function refresh() {
  tip.classList.remove('on');
  $('[data-h2]').textContent = (mode === 'ytd' ? 'Year-to-date ' + MK[metric].name.toLowerCase() : MK[metric].name + ' by quarter');
  renderKpis();
  if (view === 'chart') { render(false); renderDetail(); }
  else renderTable(false);
}
function selectQ(i) { sq = i; markSel(); renderDetail(); }
function go(v) {
  view = v;
  $$('.dex-planactual__rail button').forEach((b) => { if (b.dataset.view === v) b.setAttribute('aria-current', 'page'); else b.removeAttribute('aria-current'); });
  $$('.dex-planactual__view').forEach((s) => { s.hidden = s.dataset.view !== v; });
  tip.classList.remove('on');
  if (v === 'chart') { G = null; shown = null; render(true); renderDetail(); } else renderTable(false);
}
$('.dex-planactual__rail').addEventListener('click', (e) => { const b = e.target.closest('button'); if (b && b.dataset.view !== view) go(b.dataset.view); });
root.addEventListener('keydown', (e) => { if (e.key === 'Escape') tip.classList.remove('on'); });

/* ------------------------------------------------------------------ mount */
setTabs(); renderChips();
$('[data-h2]').textContent = MK[metric].name + ' by quarter';
renderKpis(); render(true); renderDetail();
if (window.ResizeObserver) {
  const ro = new ResizeObserver(() => {
    if (!root.isConnected) { ro.disconnect(); return; }
    if (view !== 'chart' || !svg.clientWidth) return;
    if (svg._size === svg.clientWidth + 'x' + svg.clientHeight) return;
    G = null; shown = null; render(false);
  });
  ro.observe(svg);
}

css:
.dex-runway {
  --dex-runway-bg: oklch(0.21 0.012 60);
  --dex-runway-ink: oklch(0.95 0.02 85);
  --dex-runway-accent: oklch(0.8 0.15 70);
  --dex-runway-danger: oklch(0.66 0.2 30);
  --dex-runway-ok: oklch(0.78 0.09 150);
  --dex-runway-panel: color-mix(in oklch, var(--dex-runway-bg) 90%, var(--dex-runway-ink));
  --dex-runway-deep: color-mix(in oklch, var(--dex-runway-bg) 75%, black);
  --dex-runway-line: color-mix(in oklch, var(--dex-runway-ink) 12%, transparent);
  --dex-runway-soft: color-mix(in oklch, var(--dex-runway-ink) 6%, transparent);
  --dex-runway-mute: color-mix(in oklch, var(--dex-runway-ink) 62%, var(--dex-runway-bg));
  --dex-runway-faint: color-mix(in oklch, var(--dex-runway-ink) 40%, var(--dex-runway-bg));
  --dex-runway-sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --dex-runway-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --dex-runway-out: cubic-bezier(.16, 1, .3, 1);
  --dex-runway-spring: linear(0, .006, .025 2.8%, .101 6.1%, .539 18.9%, .721 25.3%, .849 31.5%, .937 38.1%, .968 41.8%, .991 45.7%, 1.006 50.1%, 1.015 55%, 1.017 63.9%, 1.001);
  width: 100%;
  height: var(--dex-runway-h, 680px);
  container-type: inline-size;
  position: relative; isolation: isolate; overflow: hidden;
  border-radius: 18px;
  background: var(--dex-runway-bg);
  color: var(--dex-runway-ink);
  font: 13px/1.45 var(--dex-runway-sans);
  color-scheme: dark;
  accent-color: var(--dex-runway-accent);
  scrollbar-width: thin;
  scrollbar-color: color-mix(in oklch, var(--dex-runway-ink) 22%, transparent) transparent;
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, h3, p, dl, dd, dt) { margin: 0; padding: 0; }
  & :where(button) { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; text-align: inherit; }
  & :focus-visible { outline: 2px solid var(--dex-runway-accent); outline-offset: 2px; border-radius: 6px; }
  & [hidden] { display: none !important; }
}
.dex-runway__ic { width: 18px; height: 18px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }
.dex-runway__cap { font-size: 10.5px; font-weight: 650; letter-spacing: .13em; text-transform: uppercase; color: var(--dex-runway-faint); }
.dex-runway__shell { height: 100%; display: grid; grid-template-columns: 196px minmax(0, 1fr); }

.dex-runway__side { display: flex; flex-direction: column; gap: 6px; padding: 20px 12px 16px; min-height: 0; overflow: auto; background: var(--dex-runway-deep); border-right: 1px solid var(--dex-runway-line); }
.dex-runway__brand {
  display: flex; align-items: center; gap: 10px; padding: 0 6px 18px; font-weight: 760; font-size: 15px; letter-spacing: -.02em;
  & svg { width: 30px; height: 30px; flex: none; padding: 5px; border-radius: 9px; background: var(--dex-runway-accent); fill: none; stroke: var(--dex-runway-bg); stroke-width: 2; stroke-linejoin: round; }
  & small { display: block; font-size: 11px; font-weight: 500; letter-spacing: 0; color: var(--dex-runway-mute); }
}
.dex-runway__nav {
  display: grid; gap: 2px;
  & button {
    position: relative; display: flex; align-items: center; gap: 10px; padding: 9px 10px; border-radius: 10px; color: var(--dex-runway-mute); font-weight: 550; transition: background-color .2s, color .2s;
    &:hover { background: var(--dex-runway-soft); color: var(--dex-runway-ink); }
    &[aria-current="page"] { background: color-mix(in oklch, var(--dex-runway-accent) 14%, transparent); color: var(--dex-runway-ink); font-weight: 650; }
    &[aria-current="page"] .dex-runway__ic { color: var(--dex-runway-accent); }
  }
}
.dex-runway__count { margin-left: auto; min-width: 18px; padding: 0 6px; border-radius: 999px; font-size: 11px; text-align: center; background: var(--dex-runway-accent); color: var(--dex-runway-bg); &:empty { display: none; } }
.dex-runway__asof {
  margin-top: auto; display: grid; gap: 3px; padding: 12px 8px 0; border-top: 1px solid var(--dex-runway-line); font-size: 12px; color: var(--dex-runway-mute);
  & b { color: var(--dex-runway-ink); font-variant-numeric: tabular-nums; }
}
.dex-runway__fine { margin-top: 4px !important; font-size: 11px; color: var(--dex-runway-faint); text-wrap: pretty; }

.dex-runway__main { min-width: 0; min-height: 0; padding: 16px 18px; }
.dex-runway__view { height: 100%; min-height: 0; }
.dex-runway__view[data-view="plan"] { display: grid; grid-template-columns: 252px minmax(0, 1fr); gap: 14px; }

/* controls */
.dex-runway__ctl {
  display: flex; flex-direction: column; gap: 12px; min-height: 0; overflow: auto; padding: 14px; border-radius: 16px; background: var(--dex-runway-panel); box-shadow: inset 0 0 0 1px var(--dex-runway-line);
  animation: dex-runway-rise .7s var(--dex-runway-out) both;
}
.dex-runway__presets {
  display: grid; grid-template-columns: repeat(3, 1fr); padding: 3px; border-radius: 11px; background: var(--dex-runway-deep);
  & button { padding: 6px 0; border-radius: 8px; font-size: 12px; font-weight: 650; text-align: center; color: var(--dex-runway-mute); transition: background-color .2s, color .2s; }
  & button:hover { color: var(--dex-runway-ink); }
  & button[aria-checked="true"] { background: var(--dex-runway-accent); color: var(--dex-runway-bg); }
}
.dex-runway__field {
  display: grid; gap: 4px;
  & input { width: 100%; margin: 0; height: 18px; }
  & input:disabled { opacity: .4; }
  & small { font-size: 11px; color: var(--dex-runway-faint); text-wrap: pretty; }
}
.dex-runway__lab { display: flex; justify-content: space-between; align-items: baseline; gap: 8px; font-size: 12px; color: var(--dex-runway-mute); & output { font-weight: 700; color: var(--dex-runway-ink); font-variant-numeric: tabular-nums; } }
.dex-runway__raise { display: grid; gap: 10px; padding: 12px; border-radius: 12px; background: var(--dex-runway-deep); transition: opacity .25s; &:has([aria-checked="false"]) .dex-runway__field { opacity: .45; } }
.dex-runway__rhead { display: flex; align-items: center; justify-content: space-between; gap: 8px; & small { display: block; font-size: 11.5px; color: var(--dex-runway-mute); font-variant-numeric: tabular-nums; } }
.dex-runway__switch {
  position: relative; width: 38px; height: 22px; flex: none; border-radius: 999px; background: color-mix(in oklch, var(--dex-runway-ink) 18%, transparent); transition: background-color .25s;
  & i { position: absolute; left: 3px; top: 3px; width: 16px; height: 16px; border-radius: 50%; background: var(--dex-runway-ink); transition: transform .45s var(--dex-runway-spring); }
  &[aria-checked="true"] { background: var(--dex-runway-accent); }
  &[aria-checked="true"] i { transform: translateX(16px); background: var(--dex-runway-bg); }
}
.dex-runway__pin {
  display: flex; align-items: center; justify-content: center; gap: 8px; margin-top: auto; padding: 9px 12px; border-radius: 10px; font-weight: 650; font-size: 12.5px;
  box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--dex-runway-accent) 55%, transparent); color: var(--dex-runway-accent); transition: background-color .2s, transform .25s var(--dex-runway-out), opacity .2s;
  &:hover { background: color-mix(in oklch, var(--dex-runway-accent) 12%, transparent); }
  &:active { transform: scale(.97); }
  &:disabled { opacity: .4; cursor: not-allowed; }
}

/* outcome */
.dex-runway__out { min-width: 0; min-height: 0; display: grid; grid-template-rows: auto minmax(0, 1fr); gap: 12px; }
.dex-runway__kpis {
  display: grid; grid-template-columns: 1.25fr repeat(3, minmax(0, 1fr)); gap: 10px;
  & > div { position: relative; padding: 11px 14px 12px; border-radius: 14px; background: var(--dex-runway-panel); box-shadow: inset 0 0 0 1px var(--dex-runway-line); animation: dex-runway-rise .6s var(--dex-runway-out) both; animation-delay: calc(80ms + var(--i, 0) * 55ms); overflow: hidden; }
  & dt { font-size: 11.5px; color: var(--dex-runway-mute); }
  & dd { font-size: clamp(18px, 2.2cqi, 24px); font-weight: 760; letter-spacing: -.03em; line-height: 1.15; font-variant-numeric: tabular-nums; white-space: nowrap; }
  & .sub { font-size: 11.5px; color: var(--dex-runway-faint); font-variant-numeric: tabular-nums; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .hero { background: radial-gradient(120% 140% at 0% 0%, color-mix(in oklch, var(--c, var(--dex-runway-accent)) 26%, transparent), transparent 60%), var(--dex-runway-panel); }
  & .hero dd { font-size: clamp(26px, 3.4cqi, 36px); color: var(--c, var(--dex-runway-accent)); transition: color .3s; }
  & .hero dd small { font-size: 14px; font-weight: 650; margin-left: 4px; }
  & .alive { --c: var(--dex-runway-ok); }
  & .dead { --c: var(--dex-runway-danger); }
}
.dex-runway__chartp {
  min-height: 0; display: flex; flex-direction: column; gap: 6px; padding: 12px 12px 10px 4px; border-radius: 16px; background: var(--dex-runway-panel); box-shadow: inset 0 0 0 1px var(--dex-runway-line);
  animation: dex-runway-rise .7s var(--dex-runway-out) .15s both;
}
.dex-runway__plot { position: relative; flex: 1; min-height: 240px; }
.dex-runway__svg {
  position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; cursor: crosshair; touch-action: none;
  & text { font: 10px var(--dex-runway-mono); fill: var(--dex-runway-faint); font-variant-numeric: tabular-nums; }
  & .gl { stroke: var(--dex-runway-line); }
  & .zl { stroke: color-mix(in oklch, var(--dex-runway-ink) 55%, transparent); stroke-width: 1; }
  & .line { fill: none; stroke-width: 2.4; stroke-linejoin: round; stroke-linecap: round; }
  & .ghost { fill: none; stroke: color-mix(in oklch, var(--dex-runway-ink) 45%, transparent); stroke-width: 1.4; stroke-dasharray: 5 4; }
  & .gtag { font: 700 10px var(--dex-runway-sans); fill: var(--dex-runway-mute); }
  & .burn { fill: color-mix(in oklch, var(--dex-runway-accent) 55%, transparent); }
  & .burn.p { fill: var(--dex-runway-ok); }
  & .burn.cut { fill: color-mix(in oklch, var(--dex-runway-danger) 70%, transparent); }
  & .pl { font: 650 10px var(--dex-runway-sans); letter-spacing: .1em; fill: var(--dex-runway-faint); }
  & .rline { stroke: var(--dex-runway-accent); stroke-width: 1.2; stroke-dasharray: 3 3; }
  & .raise { cursor: ew-resize; outline: none; }
  & .raise .knob { fill: var(--dex-runway-accent); stroke: var(--dex-runway-bg); stroke-width: 2; transition: r .2s; }
  & .raise .rl { font: 700 10.5px var(--dex-runway-sans); fill: var(--dex-runway-bg); }
  & .raise .rb { fill: var(--dex-runway-accent); }
  & .raise:hover .knob, & .raise:focus-visible .knob, & .raise.drag .knob { r: 8px; }
  & .raise:focus-visible .rb { stroke: var(--dex-runway-ink); stroke-width: 2; }
  & .raise.off { display: none; }
  & .cliff circle { fill: var(--dex-runway-danger); }
  & .cliff .ring { fill: none; stroke: var(--dex-runway-danger); transform-box: fill-box; transform-origin: center; animation: dex-runway-ping 1.8s var(--dex-runway-out) infinite; }
  & .cliff text, & .be text { font: 700 11px var(--dex-runway-sans); }
  & .cliff text { fill: var(--dex-runway-danger); }
  & .be circle { fill: var(--dex-runway-ok); }
  & .be text { fill: var(--dex-runway-ok); }
  & .hl { stroke: var(--dex-runway-ink); stroke-dasharray: 2 3; opacity: 0; }
