const RM = !!(window.matchMedia && matchMedia('(prefers-reduced-motion: reduce)').matches);
const $ = (s, el) => (el || root).querySelector(s);
const $$ = (s, el) => Array.from((el || root).querySelectorAll(s));
const UID = 'dex-runway-' + Math.random().toString(36).slice(2, 8);

/* ------------------------------------------------------------------ model
   Opening position at 30 Sep 2026. Month 0 is October 2026; 36 months to September 2029. */
const OPEN = { cash: 41.8, mrr: 1.62, heads: 142, other: 0.70 };
const MONTHS = 36, DECAY = 0.99, OTHER_GROWTH = 1.008;
const MN = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const mlab = (m, long) => { const d = 9 + m, y = 2026 + Math.floor(d / 12); return MN[d % 12] + (long ? ' ' + y : " '" + String(y).slice(2)); };
const PRESETS = {
  base: { name: 'Base', g: 4.0, gm: 80, h: 2, c: 14.4, raise: true, amt: 25, rm: 8 },
  lean: { name: 'Lean', g: 3.2, gm: 81, h: 0, c: 14.4, raise: false, amt: 25, rm: 8 },
  aggr: { name: 'Aggressive', g: 5.2, gm: 78, h: 5, c: 15.0, raise: true, amt: 40, rm: 5 }
};
function simulate(s) {
  let cash = OPEN.cash, mrr = OPEN.mrr, heads = OPEN.heads, cliff = null, be = null, low = { v: Infinity, m: 0 }, peak = 0, peakM = 0;
  const rows = [];
  for (let m = 0; m < MONTHS; m++) {
    if (m > 0) { mrr *= 1 + s.g / 100 * Math.pow(DECAY, m); heads += s.h; }
    const gp = mrr * s.gm / 100, pay = heads * s.c / 1000, oth = OPEN.other * Math.pow(OTHER_GROWTH, m);
    const burn = pay + oth - gp, fin = s.raise && m === s.rm ? s.amt : 0;
    cash = cash - burn + fin;
    if (cliff == null && cash < 0) cliff = m;
    if (be == null && burn <= 0) be = m;
    if (cash < low.v) low = { v: cash, m };
    if (burn > peak) { peak = burn; peakM = m; }
    rows.push({ m, mrr, gp, pay, oth, burn, fin, cash, heads });
  }
  return { rows, cliff, be, low, peak, peakM, end: cash };
}

/* ------------------------------------------------------------------ state */
let S = Object.assign({}, PRESETS.base), preset = 'base', view = 'plan', R = simulate(S), first = true;
const pins = [];
const PIN_NAMES = ['A', 'B', 'C'];

/* ------------------------------------------------------------------ helpers */
const tip = $('.dex-runway__tip'), toastEl = $('.dex-runway__toast');
const m$ = (v, d) => (v < 0 ? '−$' : '$') + Math.abs(v).toFixed(d == null ? 1 : d) + 'M';
function tipAt(x, y) {
  const r = root.getBoundingClientRect(), w = tip.offsetWidth, h = tip.offsetHeight;
  const l = Math.min(Math.max(8, x - r.left + 16), r.width - w - 8);
  let t = y - r.top - h - 14; if (t < 8) t = y - r.top + 18;
  tip.style.translate = Math.round(l) + 'px ' + Math.round(t) + 'px';
}
let toastT = 0;
function toast(msg) { toastEl.textContent = msg; toastEl.classList.add('on'); clearTimeout(toastT); toastT = setTimeout(() => toastEl.classList.remove('on'), 2600); }
function verdict(r) {
  if (r.cliff != null) return { cls: 'dead', big: (r.cliff) + '<small>months</small>', txt: 'Cash runs out in ' + mlab(r.cliff, true) };
  if (r.be != null) return { cls: 'alive', big: 'Alive', txt: 'Profitable from ' + mlab(r.be, true) };
  return { cls: '', big: '36+<small>months</small>', txt: 'Cash lasts the whole horizon' };
}

/* ------------------------------------------------------------------ inputs */
const inputs = Object.fromEntries($$('[data-in]').map((el) => [el.dataset.in, el]));
const outs = Object.fromEntries($$('[data-o]').map((el) => [el.dataset.o, el]));
const OUTF = { g: (v) => v.toFixed(1) + '%', gm: (v) => Math.round(v) + '%', h: (v) => String(Math.round(v)), c: (v) => '$' + v.toFixed(1) + 'k', amt: (v) => '$' + Math.round(v) + 'M' };
const raiseSw = $('[data-raise]'), presetsEl = $('[data-presets]');
function syncInputs() {
  Object.keys(inputs).forEach((k) => { inputs[k].value = S[k]; outs[k].textContent = OUTF[k](+S[k]); });
  raiseSw.setAttribute('aria-checked', S.raise);
  inputs.amt.disabled = !S.raise;
  $('[data-raise-when]').textContent = S.raise ? 'Closes ' + mlab(S.rm, true) : 'Not in this scenario';
  $$('button', presetsEl).forEach((b) => { const on = b.dataset.p === preset; b.setAttribute('aria-checked', on); b.tabIndex = on || (!preset && b.dataset.p === 'base') ? 0 : -1; });
}
Object.entries(inputs).forEach(([k, el]) => el.addEventListener('input', () => { S[k] = +el.value; preset = null; update(); }));
raiseSw.addEventListener('click', () => { S.raise = !S.raise; preset = null; update(); toast(S.raise ? 'Series C of ' + m$(S.amt, 0) + ' added in ' + mlab(S.rm, true) + '.' : 'Series C removed from this scenario.'); });
let presetTok = 0;
function applyPreset(k, quiet) {
  const to = PRESETS[k], from = Object.assign({}, S), tok = ++presetTok;
  preset = k; S.raise = to.raise; S.rm = to.rm;
  if (RM) { Object.assign(S, to); update(); return; }
  const t0 = performance.now(), D = 560;
  const step = (now) => {
    if (!root.isConnected) return;
    if (tok !== presetTok) return;
    const t = Math.min(1, (now - t0) / D), e = 1 - Math.pow(1 - t, 3);
    ['g', 'gm', 'h', 'c', 'amt'].forEach((key) => { S[key] = from[key] + (to[key] - from[key]) * e; });
    if (t >= 1) Object.assign(S, to);
    update(true);
    if (t < 1) requestAnimationFrame(step);
  };
  requestAnimationFrame(step);
  if (!quiet) toast(to.name + ' preset loaded.');
}
presetsEl.addEventListener('click', (e) => { const b = e.target.closest('button'); if (b && b.dataset.p !== preset) applyPreset(b.dataset.p); });
presetsEl.addEventListener('keydown', (e) => {
  const bs = $$('button', presetsEl), i = bs.indexOf(document.activeElement); if (i < 0) return;
  const j = e.key === 'ArrowRight' || e.key === 'ArrowDown' ? (i + 1) % 3 : e.key === 'ArrowLeft' || e.key === 'ArrowUp' ? (i + 2) % 3 : -1;
  if (j < 0) return; e.preventDefault(); bs[j].focus(); applyPreset(bs[j].dataset.p);
});

/* ------------------------------------------------------------------ chart */
const svg = $('[data-chart]');
let G = null;
function build() {
  const W = svg.clientWidth, H = svg.clientHeight; if (!W || !H) return false;
  const L = 50, Rr = 14, T = 14, burnH = Math.max(48, H * 0.2), B = 22, mainB = H - B - burnH - 18;
  svg.innerHTML = '<defs><linearGradient id="' + UID + '-a" gradientUnits="userSpaceOnUse" x1="0" x2="0" y1="' + T + '" y2="' + mainB + '"></linearGradient>' +
    '<linearGradient id="' + UID + '-l" gradientUnits="userSpaceOnUse" x1="0" x2="0" y1="' + T + '" y2="' + mainB + '"></linearGradient></defs>' +
    '<g class="grid"></g><g class="ghosts"></g><path class="area" fill="url(#' + UID + '-a)"/><path class="line" pathLength="1" stroke="url(#' + UID + '-l)"/>' +
    '<text class="pl" x="' + L + '" y="' + (mainB + 30) + '">NET BURN A MONTH</text><g class="burns"></g><g class="marks"></g>' +
    '<line class="hl" y1="' + T + '" y2="' + (H - B) + '"/><circle class="hp" r="3.5"/>' +
    '<g class="raise" tabindex="0" role="slider" aria-label="Series C close month, drag or use the arrow keys" aria-valuemin="1" aria-valuemax="30"><line class="rline"/><rect class="rb" rx="9" height="18"/><text class="rl" text-anchor="middle"></text><circle class="knob" r="6"/></g>';
  G = { W, H, L, R: Rr, T, B, burnH, mainB, x: (m) => L + (W - L - Rr) * m / (MONTHS - 1) };
  svg._size = W + 'x' + H;
  return true;
}
function draw() {
  if (!G && !build()) return;
  const { W, H, L, T, B, burnH, mainB, x } = G, rows = R.rows;
  const all = rows.map((r) => r.cash).concat(pins.flatMap((p) => p.r.rows.map((r) => r.cash)), [OPEN.cash]);
  const hiRaw = Math.max(...all), loRaw = Math.min(0, ...all);
  const st = (() => { const raw = (hiRaw - loRaw) / 5, mag = Math.pow(10, Math.floor(Math.log10(raw))), e = raw / mag; return (e <= 1 ? 1 : e <= 2 ? 2 : e <= 2.5 ? 2.5 : e <= 5 ? 5 : 10) * mag; })();
  const lo = Math.floor(loRaw / st) * st, hi = Math.ceil(hiRaw * 1.04 / st) * st;
  const y = (v) => T + (mainB - T) * (1 - (v - lo) / (hi - lo));
  G.y = y;
  /* grid + axis */
  let g = '';
  for (let v = lo; v <= hi + 1e-9; v += st) g += '<line class="' + (Math.abs(v) < 1e-9 ? 'zl' : 'gl') + '" x1="' + L + '" x2="' + (W - G.R) + '" y1="' + y(v).toFixed(1) + '" y2="' + y(v).toFixed(1) + '"/><text x="' + (L - 8) + '" y="' + (y(v) + 3.5).toFixed(1) + '" text-anchor="end">' + (v < 0 ? '−' : '') + '$' + Math.abs(+v.toFixed(1)) + 'M</text>';
  const every = W < 520 ? 12 : 6;
  for (let m = 0; m < MONTHS; m += every) if (x(MONTHS - 1) - x(m) > 44) g += '<text x="' + x(m).toFixed(1) + '" y="' + (H - 6) + '" text-anchor="' + (m ? 'middle' : 'start') + '">' + mlab(m) + '</text>';
  g += '<text x="' + x(MONTHS - 1).toFixed(1) + '" y="' + (H - 6) + '" text-anchor="end">' + mlab(MONTHS - 1) + '</text>';
  svg.querySelector('.grid').innerHTML = g;
  /* gradients split at the zero line so the curve turns red below it */
  const zf = Math.max(0, Math.min(1, (y(0) - T) / (mainB - T))).toFixed(4);
  svg.querySelector('#' + UID + '-a').innerHTML = '<stop offset="0" stop-color="var(--dex-runway-accent)" stop-opacity=".42"/><stop offset="' + zf + '" stop-color="var(--dex-runway-accent)" stop-opacity=".03"/><stop offset="' + zf + '" stop-color="var(--dex-runway-danger)" stop-opacity=".05"/><stop offset="1" stop-color="var(--dex-runway-danger)" stop-opacity=".45"/>';
  svg.querySelector('#' + UID + '-l').innerHTML = '<stop offset="' + zf + '" stop-color="var(--dex-runway-accent)"/><stop offset="' + zf + '" stop-color="var(--dex-runway-danger)"/>';
  const line = 'M' + rows.map((r, m) => x(m).toFixed(1) + ' ' + y(r.cash).toFixed(1)).join('L');
  svg.querySelector('.line').setAttribute('d', line);
  svg.querySelector('.area').setAttribute('d', line + 'L' + x(MONTHS - 1).toFixed(1) + ' ' + y(0).toFixed(1) + 'L' + x(0).toFixed(1) + ' ' + y(0).toFixed(1) + 'Z');
  svg.querySelector('.ghosts').innerHTML = pins.map((p) => {
    const d = 'M' + p.r.rows.map((r, m) => x(m).toFixed(1) + ' ' + y(r.cash).toFixed(1)).join('L'), last = p.r.rows[MONTHS - 1];
    return '<path class="ghost" d="' + d + '"/><text class="gtag" x="' + (x(MONTHS - 1) + 4).toFixed(1) + '" y="' + (y(last.cash) + 3).toFixed(1) + '">' + p.name + '</text>';
  }).join('');
  /* burn bars hang below their baseline; profitable months rise above it in green */
  const by = mainB + 40, bh = burnH - 26, bmax = Math.max(0.5, ...rows.map((r) => Math.abs(r.burn))), bw = Math.max(2, (W - L - G.R) / MONTHS * 0.6);
  svg.querySelector('.burns').innerHTML = '<line class="gl" x1="' + L + '" x2="' + (W - G.R) + '" y1="' + by + '" y2="' + by + '"/>' + rows.map((r, m) => {
    const hh = Math.abs(r.burn) / bmax * bh * (r.burn > 0 ? 1 : 0.6), cut = R.cliff != null && m >= R.cliff;
    return '<rect class="burn' + (r.burn <= 0 ? ' p' : cut ? ' cut' : '') + '" x="' + (x(m) - bw / 2).toFixed(1) + '" y="' + (r.burn > 0 ? by : by - hh).toFixed(1) + '" width="' + bw.toFixed(1) + '" height="' + Math.max(1, hh).toFixed(1) + '" rx="1"/>';
  }).join('') + '<text x="' + (L - 8) + '" y="' + (by + bh + 3) + '" text-anchor="end">' + m$(bmax) + '</text>';
  /* cliff + breakeven markers */
  let mk = '';
  if (R.cliff != null) {
    const cx = x(R.cliff), cy = y(0);
    mk += '<g class="cliff"><circle class="ring" cx="' + cx.toFixed(1) + '" cy="' + cy.toFixed(1) + '" r="7"/><circle cx="' + cx.toFixed(1) + '" cy="' + cy.toFixed(1) + '" r="4.5"/><text x="' + (cx + (cx > W - 150 ? -10 : 10)).toFixed(1) + '" y="' + (cy - 10).toFixed(1) + '" text-anchor="' + (cx > W - 150 ? 'end' : 'start') + '">Cash out · ' + mlab(R.cliff, true) + '</text></g>';
  }
  if (R.be != null) {
    const bx = x(R.be), byy = y(rows[R.be].cash);
    mk += '<g class="be"><circle cx="' + bx.toFixed(1) + '" cy="' + byy.toFixed(1) + '" r="4.5"/><text x="' + (bx - 8).toFixed(1) + '" y="' + (byy - 12).toFixed(1) + '" text-anchor="end">Profitable · ' + mlab(R.be, true) + '</text></g>';
  }
  svg.querySelector('.marks').innerHTML = mk;
  /* fundraise handle */
  const rg = svg.querySelector('.raise'), rx = x(S.rm);
  rg.classList.toggle('off', !S.raise);
  rg.setAttribute('aria-valuenow', S.rm); rg.setAttribute('aria-valuetext', 'Closes ' + mlab(S.rm, true));
  const rl = rg.querySelector('.rline'); rl.setAttribute('x1', rx); rl.setAttribute('x2', rx); rl.setAttribute('y1', T + 22); rl.setAttribute('y2', mainB);
  const lbl = 'C · ' + m$(S.amt, 0), lw = lbl.length * 6.4 + 14;
  const rb = rg.querySelector('.rb'); rb.setAttribute('x', (rx - lw / 2).toFixed(1)); rb.setAttribute('y', T); rb.setAttribute('width', lw.toFixed(1));
  const tl = rg.querySelector('.rl'); tl.setAttribute('x', rx.toFixed(1)); tl.setAttribute('y', T + 12.5); tl.textContent = lbl;
  const kn = rg.querySelector('.knob'); kn.setAttribute('cx', rx.toFixed(1)); kn.setAttribute('cy', y(rows[S.rm].cash).toFixed(1));
  svg.classList.toggle('enter', first && !RM);
}
/* drag the raise marker along the timeline */
let drag = false;
svg.addEventListener('pointerdown', (e) => {
  if (!e.target.closest('.raise') || !G) return;
  drag = true; svg.setPointerCapture(e.pointerId); svg.querySelector('.raise').classList.add('drag'); e.preventDefault();
});
svg.addEventListener('pointermove', (e) => {
  if (!G) return;
  const r = svg.getBoundingClientRect(), px = e.clientX - r.left;
  const m = Math.max(0, Math.min(MONTHS - 1, Math.round((px - G.L) / (G.W - G.L - G.R) * (MONTHS - 1))));
  if (drag) {
    const mm = Math.max(1, Math.min(30, m));
    if (mm !== S.rm) { S.rm = mm; preset = null; update(); }
    tip.classList.remove('on'); return;
  }
  const row = R.rows[m];
  svg.querySelector('.hl').setAttribute('x1', G.x(m)); svg.querySelector('.hl').setAttribute('x2', G.x(m));
  const hp = svg.querySelector('.hp'); hp.setAttribute('cx', G.x(m)); hp.setAttribute('cy', G.y(row.cash));
  svg.classList.add('hov');
  tip.innerHTML = '<b>' + mlab(m, true) + '</b><span>Cash <em>' + m$(row.cash) + '</em></span><span>' + (row.burn > 0 ? 'Net burn' : 'Net profit') + ' <em>' + m$(Math.abs(row.burn), 2) + '</em></span><span>MRR <em>' + m$(row.mrr, 2) + '</em></span><span>People <em>' + Math.round(row.heads) + '</em></span>' + (row.fin ? '<span>Series C <em>+' + m$(row.fin, 0) + '</em></span>' : '');
  tip.classList.add('on'); tipAt(e.clientX, e.clientY);
});
const endDrag = () => { if (!drag) return; drag = false; const rg = svg.querySelector('.raise'); if (rg) rg.classList.remove('drag'); toast('Series C now closes in ' + mlab(S.rm, true) + '.'); };
svg.addEventListener('pointerup', endDrag);
svg.addEventListener('pointercancel', endDrag);
svg.addEventListener('pointerleave', () => { if (!drag) { svg.classList.remove('hov'); tip.classList.remove('on'); } });
svg.addEventListener('keydown', (e) => {
  if (!e.target.closest('.raise')) return;
  const d = e.key === 'ArrowRight' || e.key === 'ArrowUp' ? 1 : e.key === 'ArrowLeft' || e.key === 'ArrowDown' ? -1 : 0;
  if (e.key === 'Home') { S.rm = 1; } else if (e.key === 'End') { S.rm = 30; } else if (d) { S.rm = Math.max(1, Math.min(30, S.rm + d)); } else return;
  e.preventDefault(); preset = null; update();
});

/* ------------------------------------------------------------------ outputs */
function renderKpis() {
  const v = verdict(R), low = R.low;
  const k = [
    ['hero ' + v.cls, R.cliff != null ? 'Runway' : 'Default status', v.big, v.txt],
    ['', 'Cash at Sep 2029', m$(R.end), R.end < 0 ? 'Funding gap to cover' : S.raise ? 'Including the Series C' : 'With no new funding'],
    ['', 'Lowest cash', m$(low.v), 'in ' + mlab(low.m, true)],
    ['', 'Peak net burn', m$(R.peak, 2), 'a month, in ' + mlab(R.peakM, true)]
  ];
  $('[data-kpis]').innerHTML = k.map((x, i) => '<div class="' + x[0] + '" style="--i:' + i + '"><dt>' + x[1] + '</dt><dd>' + x[2] + '</dd><p class="sub">' + x[3] + '</p></div>').join('');
}
const X_ICON = '<svg viewBox="0 0 10 10" aria-hidden="true"><path d="M2 2l6 6M8 2L2 8"/></svg>';
function renderPins() {
  const el = $('[data-pins]');
  el.innerHTML = '<span class="key"><i></i>This scenario</span>' + (pins.length ? '<span class="key"><i class="g"></i>Pinned</span>' : '<span>Pin a scenario to compare it here.</span>') +
    pins.map((p, i) => '<span class="chip"><b>' + p.name + '</b> ' + p.label + ' · ' + p.sum + '<button type="button" data-unpin="' + i + '" aria-label="Unpin scenario ' + p.name + '" title="Unpin">' + X_ICON + '</button></span>').join('');
  const pinBtn = $('[data-pin]');
  pinBtn.disabled = pins.length >= 3;
  pinBtn.title = pins.length >= 3 ? 'Three scenarios are pinned. Unpin one to compare another.' : 'Keep this curve on the chart for comparison';
  $('[data-pin-count]').textContent = pins.length || '';
}
function describe(s) { return (s.raise ? m$(s.amt, 0) + ' raise' : 'no raise') + ', ' + s.g.toFixed(1) + '% growth, ' + Math.round(s.h) + ' hires/mo'; }
function shortOutcome(r) { return r.cliff != null ? 'out ' + mlab(r.cliff) : r.be != null ? 'profitable ' + mlab(r.be) : '36+ mo'; }
$('[data-pin]').addEventListener('click', () => {
  if (pins.length >= 3) return;
  const used = pins.map((p) => p.name), name = PIN_NAMES.find((n) => !used.includes(n));
  pins.push({ name, s: Object.assign({}, S), r: simulate(S), label: preset ? PRESETS[preset].name : 'Custom', sum: shortOutcome(R) });
  renderPins(); draw();
  toast('Pinned as scenario ' + name + ': ' + describe(S) + '.');
});
$('[data-pins]').addEventListener('click', (e) => {
  const b = e.target.closest('[data-unpin]'); if (!b) return;
  const p = pins.splice(+b.dataset.unpin, 1)[0];
  renderPins(); draw();
  toast('Scenario ' + p.name + ' unpinned.');
});

function renderModel() {
  $('[data-model-sub]').textContent = (preset ? PRESETS[preset].name : 'Custom') + ' scenario: ' + describe(S) + ', ' + Math.round(S.gm) + '% gross margin, $' + S.c.toFixed(1) + 'k a head. $ millions.';
  $('[data-model]').innerHTML = R.rows.map((r) => {
    const cls = R.cliff === r.m ? 'cliff' : R.be === r.m ? 'be' : r.fin ? 'fin' : r.cash < 0 ? 'neg' : '';
    return '<tr class="' + cls + '"><td>' + mlab(r.m, true) + '</td><td>' + r.mrr.toFixed(2) + '</td><td>' + r.gp.toFixed(2) + '</td><td>' + r.pay.toFixed(2) + '</td><td>' + r.oth.toFixed(2) + '</td>' +
      '<td class="' + (r.burn <= 0 ? 'pos' : '') + '">' + (r.burn <= 0 ? '+' + Math.abs(r.burn).toFixed(2) : r.burn.toFixed(2)) + '</td><td>' + (r.fin ? '+' + r.fin.toFixed(1) : '—') + '</td><td>' + r.cash.toFixed(1) + '</td><td>' + Math.round(r.heads) + '</td></tr>';
  }).join('');
}
function spark(r) {
  const vals = r.rows.map((x) => x.cash), lo = Math.min(0, ...vals), hi = Math.max(...vals, OPEN.cash), W = 220, H = 56;
  const y = (v) => 4 + (H - 8) * (1 - (v - lo) / (hi - lo || 1));
  return '<svg viewBox="0 0 ' + W + ' ' + H + '" preserveAspectRatio="none" aria-hidden="true"><line x1="0" x2="' + W + '" y1="' + y(0).toFixed(1) + '" y2="' + y(0).toFixed(1) + '"/><path vector-effect="non-scaling-stroke" d="M' + vals.map((v, i) => (i / (MONTHS - 1) * W).toFixed(1) + ' ' + y(v).toFixed(1)).join('L') + '"/></svg>';
}
function renderCards() {
  const list = Object.entries(PRESETS).map(([k, p]) => ({ key: k, title: p.name, tag: 'Preset', s: p, r: simulate(p) }))
    .concat(pins.map((p, i) => ({ pin: i, title: 'Scenario ' + p.name, tag: p.label, s: p.s, r: p.r })));
  $('[data-cards]').innerHTML = list.map((c, i) => {
    const v = verdict(c.r);
    return '<article class="dex-runway__card ' + v.cls + '" style="--i:' + i + '"><h4>' + c.title + '<small>' + c.tag + '</small></h4>' + spark(c.r) +
      '<dl><dt>Outcome</dt><dd>' + v.txt.replace('Cash runs out in', 'Out of cash').replace('Profitable from', 'Profitable') + '</dd><dt>Ending cash</dt><dd>' + m$(c.r.end) + '</dd><dt>Growth · hires</dt><dd>' + c.s.g.toFixed(1) + '% · ' + Math.round(c.s.h) + '/mo</dd><dt>Series C</dt><dd>' + (c.s.raise ? m$(c.s.amt, 0) + ' · ' + mlab(c.s.rm) : 'None') + '</dd></dl>' +
      '<div class="acts"><button type="button" class="go" ' + (c.key ? 'data-apply="' + c.key + '"' : 'data-load="' + c.pin + '"') + '>Open in planner</button>' + (c.pin != null ? '<button type="button" data-drop="' + c.pin + '">Unpin</button>' : '') + '</div></article>';
  }).join('');
}
$('[data-cards]').addEventListener('click', (e) => {
  const a = e.target.closest('[data-apply]'), l = e.target.closest('[data-load]'), d = e.target.closest('[data-drop]');
  if (a) { go('plan'); applyPreset(a.dataset.apply); }
  if (l) { const p = pins[+l.dataset.load]; Object.assign(S, p.s); preset = null; go('plan'); update(); toast('Scenario ' + p.name + ' loaded into the planner.'); }
  if (d) { const p = pins.splice(+d.dataset.drop, 1)[0]; renderPins(); renderCards(); toast('Scenario ' + p.name + ' unpinned.'); }
});

/* ------------------------------------------------------------------ views */
function update(fromPreset) {
  if (!fromPreset) presetTok++;
  if (first) first = false; else svg.classList.remove('enter');
  R = simulate(S);
  syncInputs(); renderKpis();
  if (view === 'plan') draw();
  if (view === 'model') renderModel();
}
function go(v) {
  view = v;
  $$('.dex-runway__nav button').forEach((b) => { if (b.dataset.view === v) b.setAttribute('aria-current', 'page'); else b.removeAttribute('aria-current'); });
  $$('.dex-runway__view').forEach((s) => { s.hidden = s.dataset.view !== v; });
  tip.classList.remove('on');
  if (v === 'plan') { G = null; draw(); }
  if (v === 'model') renderModel();
  if (v === 'scen') renderCards();
}
$('.dex-runway__nav').addEventListener('click', (e) => { const b = e.target.closest('button'); if (b && b.dataset.view !== view) go(b.dataset.view); });
$('.dex-runway__nav').addEventListener('keydown', (e) => {
  const bs = $$('.dex-runway__nav button'), i = bs.indexOf(document.activeElement); if (i < 0) return;
  if (e.key === 'ArrowDown' || e.key === 'ArrowRight') { e.preventDefault(); bs[(i + 1) % bs.length].focus(); }
  if (e.key === 'ArrowUp' || e.key === 'ArrowLeft') { e.preventDefault(); bs[(i + bs.length - 1) % bs.length].focus(); }
});
root.addEventListener('keydown', (e) => { if (e.key === 'Escape') { tip.classList.remove('on'); toastEl.classList.remove('on'); } });

/* ------------------------------------------------------------------ mount */
syncInputs(); renderKpis(); renderPins(); draw();
if (window.ResizeObserver) {
  const ro = new ResizeObserver(() => {
    if (!root.isConnected) { ro.disconnect(); return; }
    if (view !== 'plan' || !svg.clientWidth || svg._size === svg.clientWidth + 'x' + svg.clientHeight) return;
    G = null; draw();
  });
  ro.observe(svg);
}

css:
.dex-initiatives {
  --dex-initiatives-bg: oklch(0.968 0.007 75);
  --dex-initiatives-ink: oklch(0.25 0.02 50);
  --dex-initiatives-accent: oklch(0.5 0.16 262);
  --dex-initiatives-ok: oklch(0.6 0.12 160);
  --dex-initiatives-risk: oklch(0.74 0.14 72);
  --dex-initiatives-off: oklch(0.58 0.18 28);
  --dex-initiatives-done: oklch(0.64 0.03 260);
  --dex-initiatives-card: color-mix(in oklch, var(--dex-initiatives-bg) 40%, white);
  --dex-initiatives-line: color-mix(in oklch, var(--dex-initiatives-ink) 12%, transparent);
  --dex-initiatives-soft: color-mix(in oklch, var(--dex-initiatives-ink) 5%, transparent);
  --dex-initiatives-mute: color-mix(in oklch, var(--dex-initiatives-ink) 63%, var(--dex-initiatives-bg));
  --dex-initiatives-faint: color-mix(in oklch, var(--dex-initiatives-ink) 42%, var(--dex-initiatives-bg));
  --dex-initiatives-sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --dex-initiatives-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --dex-initiatives-out: cubic-bezier(.16, 1, .3, 1);
  --dex-initiatives-spring: linear(0, .006, .025 2.8%, .101 6.1%, .539 18.9%, .721 25.3%, .849 31.5%, .937 38.1%, .968 41.8%, .991 45.7%, 1.006 50.1%, 1.015 55%, 1.017 63.9%, 1.001);
  width: 100%;
  height: var(--dex-initiatives-h, 680px);
  container-type: inline-size;
  position: relative; isolation: isolate; overflow: hidden; overflow: clip;
  border-radius: 18px;
  background: var(--dex-initiatives-bg);
  color: var(--dex-initiatives-ink);
  font: 13px/1.45 var(--dex-initiatives-sans);
  accent-color: var(--dex-initiatives-accent);
  scrollbar-width: thin;
  scrollbar-color: color-mix(in oklch, var(--dex-initiatives-ink) 20%, transparent) transparent;
  box-shadow: inset 0 0 0 1px var(--dex-initiatives-line);
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, h3, h4, p, ul, li, ol) { margin: 0; padding: 0; }
  & :where(ul, ol) { list-style: none; }
  & :where(button) { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; text-align: inherit; }
  & :focus-visible { outline: 2px solid var(--dex-initiatives-accent); outline-offset: 2px; border-radius: 6px; }
  & [hidden] { display: none !important; }
  & [data-s="ok"] { --c: var(--dex-initiatives-ok); }
  & [data-s="risk"] { --c: var(--dex-initiatives-risk); }
  & [data-s="off"] { --c: var(--dex-initiatives-off); }
  & [data-s="done"] { --c: var(--dex-initiatives-done); }
}
.dex-initiatives__ic { width: 18px; height: 18px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }
.dex-initiatives__cap { font-size: 10.5px; font-weight: 650; letter-spacing: .13em; text-transform: uppercase; color: var(--dex-initiatives-faint); }
.dex-initiatives__shell { height: 100%; display: grid; grid-template-columns: 206px minmax(0, 1fr); }

.dex-initiatives__side { display: flex; flex-direction: column; gap: 6px; padding: 20px 14px 16px; min-height: 0; overflow: auto; border-right: 1px solid var(--dex-initiatives-line); background: color-mix(in oklch, var(--dex-initiatives-bg) 93%, var(--dex-initiatives-ink)); }
