  & svg { width: 30px; height: 30px; flex: none; padding: 5px; border-radius: 9px; background: var(--dex-initiatives-accent); fill: none; stroke: white; stroke-width: 1.9; stroke-linejoin: round; stroke-linecap: round; }
  & small { display: block; font-size: 11px; font-weight: 500; letter-spacing: 0; color: var(--dex-initiatives-mute); }
}
