.dex-initiatives__pillars {
  display: flex; flex-wrap: wrap; gap: 4px; padding: 3px; border-radius: 11px; background: var(--dex-initiatives-soft);
  & button { padding: 5px 10px; border-radius: 8px; font-size: 12px; font-weight: 600; color: var(--dex-initiatives-mute); transition: background-color .2s, color .2s; }
  & button:hover { color: var(--dex-initiatives-ink); }
