}
.dex-initiatives__summary { display: flex; align-items: center; gap: 10px 18px; flex-wrap: wrap; }
.dex-initiatives__stack {
  flex: 1 1 380px; display: flex; gap: 3px; min-width: 0;
  & button {
    position: relative; flex: var(--n) 1 0; min-width: 64px; display: flex; align-items: baseline; gap: 6px; padding: 7px 10px; border-radius: 9px; overflow: hidden; white-space: nowrap;
    background: color-mix(in oklch, var(--c) 18%, var(--dex-initiatives-card)); color: color-mix(in oklch, var(--c) 55%, var(--dex-initiatives-ink));
    font-size: 12px; font-weight: 650; transition: flex-grow .6s var(--dex-initiatives-spring), background-color .2s, opacity .2s, box-shadow .2s;
