  &:has([aria-pressed="true"]) button[aria-pressed="false"] { opacity: .45; }
}
.dex-initiatives__budget { font-size: 12px; color: var(--dex-initiatives-mute); font-variant-numeric: tabular-nums; & b { color: var(--dex-initiatives-ink); } }

.dex-initiatives__view { min-height: 0; }
.dex-initiatives__tablewrap { height: 100%; overflow: auto; scrollbar-width: thin; border-radius: 14px; background: var(--dex-initiatives-card); box-shadow: inset 0 0 0 1px var(--dex-initiatives-line); animation: dex-initiatives-rise .6s var(--dex-initiatives-out) both .1s; }
.dex-initiatives__table {
  width: 100%; min-width: 780px; border-collapse: collapse; font-variant-numeric: tabular-nums;
  & th { position: sticky; top: 0; z-index: 1; background: var(--dex-initiatives-card); text-align: left; font-size: 11px; font-weight: 650; color: var(--dex-initiatives-mute); border-bottom: 1px solid var(--dex-initiatives-line); white-space: nowrap; }
