.dex-initiatives__nm { display: grid; gap: 1px; & b { font-weight: 650; font-size: 13px; letter-spacing: -.01em; } & small { font-size: 11.5px; color: var(--dex-initiatives-mute); } }
.dex-initiatives__pill {
  display: inline-flex; align-items: center; gap: 6px; padding: 2px 8px 2px 7px; border-radius: 999px; font-size: 11.5px; font-weight: 650; white-space: nowrap;
  background: color-mix(in oklch, var(--c) 15%, transparent); color: color-mix(in oklch, var(--c) 60%, var(--dex-initiatives-ink));
