.dex-initiatives__hist { display: flex; gap: 2px; & i { width: 7px; height: 16px; border-radius: 2px; background: var(--c); } & i:last-child { box-shadow: 0 0 0 1.5px var(--dex-initiatives-card), 0 0 0 2.5px var(--c); } }
.dex-initiatives__prog {
