    '<text class="quad" x="' + (L + 8) + '" y="' + (H - B - 8) + '">BEHIND, UNDERSPENT</text><text class="quad" x="' + (W - R - 8) + '" y="' + (H - B - 8) + '" text-anchor="end">AHEAD AND LEAN</text>';
