const RM = !!(window.matchMedia && matchMedia('(prefers-reduced-motion: reduce)').matches);
const $ = (s, el) => (el || root).querySelector(s);
const $$ = (s, el) => Array.from((el || root).querySelectorAll(s));
const NF = new Intl.NumberFormat('en-US');

/* ------------------------------------------------------------------ data: Q3 2026 cohorts by channel
   spend / new customers = CAC. A customer orders `opm` boxes a month while subscribed; survival
   after m months is floor + (1 - floor) * e^(-k m). The first box carries the channel's promotion. */
const CH = [
  { k: 'social', name: 'Paid social', c: 'var(--dex-unit-c1)', n: 18400, spend: 2650000, aov: 62, opm: 2.2, promo: 31, floor: 0.12, kk: 0.38 },
  { k: 'search', name: 'Search', c: 'var(--dex-unit-c2)', n: 11200, spend: 1340000, aov: 70, opm: 2.5, promo: 20, floor: 0.20, kk: 0.30 },
  { k: 'ref', name: 'Referral', c: 'var(--dex-unit-c3)', n: 6900, spend: 410000, aov: 72, opm: 2.7, promo: 25, floor: 0.30, kk: 0.22 },
  { k: 'pod', name: 'Podcasts', c: 'var(--dex-unit-c4)', n: 3100, spend: 520000, aov: 78, opm: 2.6, promo: 35, floor: 0.24, kk: 0.26 },
  { k: 'retail', name: 'Retail partners', c: 'var(--dex-unit-c5)', n: 4600, spend: 690000, aov: 58, opm: 2.0, promo: 15, floor: 0.10, kk: 0.45 }
];
const H = 24, BASE = { cac: 0, aov: 0, cm: 31, churn: 0 };
let W = Object.assign({}, BASE), view = 'curves', focusK = null, sortK = 'ratio', sortDir = -1;
const shown = new Set(CH.map((c) => c.k));

function model(w) {
  const per = CH.map((c) => {
    const cac = c.spend / c.n * (1 + w.cac / 100), aov = c.aov * (1 + w.aov / 100);
    const kk = c.kk * (1 + w.churn / 100), fl = Math.max(0.02, Math.min(0.6, c.floor * (1 - w.churn / 100 * 0.6)));
    const surv = [], contrib = [], cum = [-cac];
    for (let m = 0; m < H; m++) {
      const s = fl + (1 - fl) * Math.exp(-kk * m);
      surv.push(s);
      const v = s * c.opm * aov * w.cm / 100 - (m === 0 ? c.promo : 0);
      contrib.push(v); cum.push(cum[m] + v);
    }
    const ltv = contrib.reduce((a, b) => a + b, 0);
    let pb = null; for (let m = 1; m <= H; m++) if (cum[m] >= 0) { pb = m - 1 + (-cum[m - 1]) / (cum[m] - cum[m - 1]); break; }
    return { c, cac, aov, surv, cum, ltv, ratio: ltv / cac, pb, spend: c.spend * (1 + w.cac / 100) };
  });
  const N = CH.reduce((t, c) => t + c.n, 0);
  const bcum = Array.from({ length: H + 1 }, (_, m) => per.reduce((t, p) => t + p.cum[m] * p.c.n, 0) / N);
  let bpb = null; for (let m = 1; m <= H; m++) if (bcum[m] >= 0) { bpb = m - 1 + (-bcum[m - 1]) / (bcum[m] - bcum[m - 1]); break; }
  const cac = per.reduce((t, p) => t + p.spend, 0) / N, ltv = per.reduce((t, p) => t + p.ltv * p.c.n, 0) / N;
  return { per, N, blend: { cac, ltv, ratio: ltv / cac, pb: bpb, cum: bcum } };
}
let M = model(W);
const M0 = model(BASE);
const pbTxt = (pb) => (pb == null ? 'Over 24 mo' : pb.toFixed(1) + ' mo');

/* ------------------------------------------------------------------ helpers */
const tip = $('.dex-unit__tip');
function tipAt(x, y) {
  const r = root.getBoundingClientRect(), w = tip.offsetWidth, h = tip.offsetHeight;
  const l = Math.min(Math.max(8, x - r.left + 16), r.width - w - 8);
  let t = y - r.top - h - 12; if (t < 8) t = y - r.top + 18;
  tip.style.translate = Math.round(l) + 'px ' + Math.round(t) + 'px';
}
const usd = (v) => (v < 0 ? '−$' : '$') + NF.format(Math.round(Math.abs(v)));

/* ------------------------------------------------------------------ legend */
const legend = $('[data-legend]');
legend.innerHTML = CH.map((c) => '<button type="button" data-k="' + c.k + '" style="--c:' + c.c + '" aria-pressed="true" title="Show or hide ' + c.name + '"><i></i>' + c.name + '</button>').join('');
legend.addEventListener('click', (e) => {
  const b = e.target.closest('button'); if (!b) return;
  if (shown.has(b.dataset.k)) shown.delete(b.dataset.k); else shown.add(b.dataset.k);
  if (!shown.size) CH.forEach((c) => shown.add(c.k));
  if (focusK && !shown.has(focusK)) focusK = null;
  $$('button', legend).forEach((x) => x.setAttribute('aria-pressed', shown.has(x.dataset.k)));
  render();
});

/* ------------------------------------------------------------------ kpis */
function renderKpis() {
  const b = M.blend, b0 = M0.blend, moved = JSON.stringify(W) !== JSON.stringify(BASE);
  const d = (v, v0, f, better) => (moved && Math.abs(v - v0) > 1e-6 ? '<span class="' + ((v > v0) === better ? 'up' : 'dn') + '">' + (v > v0 ? '+' : '−') + f(Math.abs(v - v0)) + '</span> vs actuals' : 'Q3 actuals');
  const k = [
    ['New subscribers', NF.format(M.N), 'from $' + (M.per.reduce((t, p) => t + p.spend, 0) / 1e6).toFixed(2) + 'M of spend'],
    ['Blended CAC', usd(b.cac), d(b.cac, b0.cac, (x) => '$' + x.toFixed(0), false)],
    ['24-month LTV', usd(b.ltv), d(b.ltv, b0.ltv, (x) => '$' + x.toFixed(0), true)],
    ['LTV : CAC', b.ratio.toFixed(1) + '×', d(b.ratio, b0.ratio, (x) => x.toFixed(1) + '×', true)],
    ['Blended payback', pbTxt(b.pb), b.pb != null && b0.pb != null ? d(b.pb, b0.pb, (x) => x.toFixed(1) + ' mo', false) : 'Q3 actuals']
