  const all = vis.flatMap((p) => p.cum);
  const raw = Math.max(...all) - Math.min(...all), mag = Math.pow(10, Math.floor(Math.log10(raw / 5))), st = [1, 2, 2.5, 5, 10].map((e) => e * mag).find((v) => raw / v <= 6);
  const lo = Math.floor(Math.min(0, ...all) / st) * st, hi = Math.ceil(Math.max(0, ...all) / st) * st;
  const L = 52, R = 112, T = 12, B = 26;
  const x = (m) => L + (Wd - L - R) * m / H, y = (v) => T + (Ht - T - B) * (1 - (v - lo) / (hi - lo));
  let s = '<rect class="neg" x="' + L + '" y="' + y(0).toFixed(1) + '" width="' + (Wd - L - R) + '" height="' + (y(lo) - y(0)).toFixed(1) + '"/>';
  for (let v = lo; v <= hi + 1e-9; v += st) s += '<line class="' + (Math.abs(v) < 1e-9 ? 'zl' : 'gl') + '" x1="' + L + '" x2="' + (Wd - R) + '" y1="' + y(v).toFixed(1) + '" y2="' + y(v).toFixed(1) + '"/><text x="' + (L - 8) + '" y="' + (y(v) + 3.5).toFixed(1) + '" text-anchor="end">' + usd(v) + '</text>';
  for (let m = 0; m <= H; m += 3) s += '<text x="' + x(m).toFixed(1) + '" y="' + (Ht - 7) + '" text-anchor="middle">' + (m === 0 ? 'Acq.' : 'M' + m) + '</text>';
  s += '<text class="zt" x="' + (L + 6) + '" y="' + (y(0) + 14).toFixed(1) + '">STILL PAYING BACK</text>';
  /* end labels, pushed apart so they never collide */
  const ends = vis.map((p) => ({ p, y: y(p.cum[H]) })).sort((a, b) => a.y - b.y);
  for (let i = 1; i < ends.length; i++) if (ends[i].y - ends[i - 1].y < 14) ends[i].y = ends[i - 1].y + 14;
  const endY = new Map(ends.map((e) => [e.p.c.k, e.y]));
  vis.forEach((p, i) => {
