    }
    s += '<text class="end" x="' + (Wd - R + 8) + '" y="' + (endY.get(p.c.k) + 4).toFixed(1) + '">' + p.c.name + ' ' + usd(p.cum[H]) + '</text></g>';
  });
  s += '<line class="hl" y1="' + T + '" y2="' + (Ht - B) + '"/>' + vis.map((p) => '<circle class="hp" r="3.5" style="--c:' + p.c.c + '" data-k="' + p.c.k + '"/>').join('');
  svg.innerHTML = s;
  svg.classList.remove('hov'); tip.classList.remove('on');
  svg.classList.toggle('focus', !!focusK);
  svg.classList.toggle('enter', !!enter && !RM);
