}
svg.addEventListener('pointermove', (e) => {
  if (!geo) return;
  const r = svg.getBoundingClientRect(), m = Math.max(0, Math.min(H, Math.round((e.clientX - r.left - geo.L) / (geo.Wd - geo.L - geo.R) * H)));
  const X = geo.x(m).toFixed(1), hl = svg.querySelector('.hl'); hl.setAttribute('x1', X); hl.setAttribute('x2', X);
  geo.vis.forEach((p) => { const c = svg.querySelector('.hp[data-k="' + p.c.k + '"]'); c.setAttribute('cx', X); c.setAttribute('cy', geo.y(p.cum[m]).toFixed(1)); });
