svg.addEventListener('pointerleave', () => { svg.classList.remove('hov'); tip.classList.remove('on'); });
$('[data-clear]').addEventListener('click', () => { focusK = null; renderCurves(false); renderSay(); });

/* ------------------------------------------------------------------ what-if */
const inputs = Object.fromEntries($$('[data-in]').map((el) => [el.dataset.in, el]));
const outs = Object.fromEntries($$('[data-o]').map((el) => [el.dataset.o, el]));
const OF = { cac: (v) => (v > 0 ? '+' : v < 0 ? '−' : '') + Math.abs(v) + '%', aov: (v) => (v > 0 ? '+' : v < 0 ? '−' : '') + Math.abs(v) + '%', cm: (v) => v.toFixed(1) + '%', churn: (v) => (v > 0 ? '+' : v < 0 ? '−' : '') + Math.abs(v) + '%' };
function syncInputs() {
  Object.keys(inputs).forEach((k) => { inputs[k].value = W[k]; outs[k].textContent = OF[k](+W[k]); });
  const moved = JSON.stringify(W) !== JSON.stringify(BASE), r = $('[data-reset]');
  r.disabled = !moved; r.title = moved ? 'Put every assumption back to the Q3 actuals' : 'Already at the Q3 actuals';
}
Object.entries(inputs).forEach(([k, el]) => el.addEventListener('input', () => { W[k] = +el.value; render(); }));
$('[data-reset]').addEventListener('click', () => { W = Object.assign({}, BASE); render(); $('[data-reset]').blur(); });
function renderSay() {
  const vis = M.per.filter((p) => shown.has(p.c.k)), best = vis.slice().sort((a, b) => b.ratio - a.ratio)[0], worst = vis.slice().sort((a, b) => a.ratio - b.ratio)[0];
  const f = focusK ? M.per.find((p) => p.c.k === focusK) : null;
  let t = f ? '<b>' + f.c.name + '</b>: CAC ' + usd(f.cac) + ', 24-month LTV ' + usd(f.ltv) + ' (' + f.ratio.toFixed(1) + '×), ' + (f.pb == null ? 'does not pay back inside two years.' : 'pays back in month ' + Math.max(1, Math.ceil(f.pb)) + '.') + ' ' :
    '<b>' + best.c.name + '</b> returns ' + best.ratio.toFixed(1) + '× its CAC' + (best.pb != null ? ' and pays back in month ' + Math.max(1, Math.ceil(best.pb)) : '') + '. ';
  if (!f && worst !== best) t += '<b>' + worst.c.name + '</b> ' + (worst.pb == null ? 'never pays back inside 24 months' : 'needs ' + Math.ceil(worst.pb) + ' months') + ' at ' + worst.ratio.toFixed(1) + '×.';
