}

/* ------------------------------------------------------------------ table */
const COLS = [['name', 'Channel'], ['n', 'New subscribers'], ['spend', 'Spend'], ['cac', 'CAC'], ['aov', 'Order value'], ['ltv', '24-mo LTV'], ['ratio', 'LTV : CAC'], ['pb', 'Payback'], ['mix', 'Mix']];
const ARW = '<svg viewBox="0 0 10 10" aria-hidden="true"><path d="M2 3.5L5 6.5 8 3.5"/></svg>';
$('[data-thead]').innerHTML = COLS.map((c) => '<th scope="col" data-k="' + c[0] + '"><button type="button">' + c[1] + ARW + '</button></th>').join('');
