const SK = { name: (p) => p.c.name, n: (p) => p.c.n, spend: (p) => p.spend, cac: (p) => p.cac, aov: (p) => p.aov, ltv: (p) => p.ltv, ratio: (p) => p.ratio, pb: (p) => (p.pb == null ? 99 : p.pb), mix: (p) => p.c.n };
function renderTable(animate) {
  $$('[data-thead] th').forEach((th) => { if (th.dataset.k === sortK) th.setAttribute('aria-sort', sortDir > 0 ? 'ascending' : 'descending'); else th.removeAttribute('aria-sort'); });
