  const tb = $('[data-tbody]'), before = new Map($$('tr', tb).map((tr) => [tr.dataset.k, tr.getBoundingClientRect().top]));
  tb.innerHTML = rows.map((p) => '<tr data-k="' + p.c.k + '" tabindex="0" style="--c:' + p.c.c + '" aria-label="' + p.c.name + ': show on the payback chart"><td><i></i>' + p.c.name + '</td><td>' + NF.format(p.c.n) + '</td><td>$' + (p.spend / 1e6).toFixed(2) + 'M</td><td>' + usd(p.cac) + '</td><td>' + usd(p.aov) + '</td><td>' + usd(p.ltv) + '</td>' +
    '<td><span class="ratio"><span style="--r:' + p.ratio.toFixed(2) + '"><i></i><s title="3× target"></s></span><b class="' + (p.ratio < 3 ? 'lo' : '') + '">' + p.ratio.toFixed(1) + '×</b></span></td><td class="' + (p.pb == null || p.pb > 12 ? 'lo' : '') + '">' + pbTxt(p.pb) + '</td><td>' + (p.c.n / M.N * 100).toFixed(1) + '%</td></tr>').join('');
  const b = M.blend;
  $('[data-tfoot]').innerHTML = '<tr><td>Blended</td><td>' + NF.format(M.N) + '</td><td>$' + (M.per.reduce((t, p) => t + p.spend, 0) / 1e6).toFixed(2) + 'M</td><td>' + usd(b.cac) + '</td><td>' + usd(M.per.reduce((t, p) => t + p.aov * p.c.n, 0) / M.N) + '</td><td>' + usd(b.ltv) + '</td><td>' + b.ratio.toFixed(1) + '×</td><td>' + pbTxt(b.pb) + '</td><td>100%</td></tr>';
  if (animate && !RM) $$('tr', tb).forEach((tr) => { const t0 = before.get(tr.dataset.k); if (t0 == null) return; const d = t0 - tr.getBoundingClientRect().top; if (Math.abs(d) > 1) tr.animate([{ transform: 'translateY(' + d + 'px)' }, { transform: 'none' }], { duration: 500, easing: 'cubic-bezier(.2,.9,.25,1)' }); });
}
function focusChannel(k) { focusK = k; shown.add(k); $$('button', legend).forEach((x) => x.setAttribute('aria-pressed', shown.has(x.dataset.k))); go('curves'); renderSay(); }
$('[data-tbody]').addEventListener('click', (e) => { const tr = e.target.closest('tr[data-k]'); if (tr) focusChannel(tr.dataset.k); });
$('[data-tbody]').addEventListener('keydown', (e) => {
  const tr = e.target.closest('tr[data-k]'); if (!tr) return;
  if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); focusChannel(tr.dataset.k); }
  if (e.key === 'ArrowDown' && tr.nextElementSibling) { e.preventDefault(); tr.nextElementSibling.focus(); }
  if (e.key === 'ArrowUp' && tr.previousElementSibling) { e.preventDefault(); tr.previousElementSibling.focus(); }
});

/* ------------------------------------------------------------------ retention heat */
const heat = $('[data-heat]');
heat.innerHTML = '<div class="hd" role="columnheader"></div>' + Array.from({ length: 13 }, (_, m) => '<div class="hd" role="columnheader">M' + (m + 1) + '</div>').join('') +
  CH.map((c, r) => '<div class="rl" role="rowheader" style="--c:' + c.c + '"><i></i>' + c.name + '</div>' + Array.from({ length: 13 }, (_, m) => '<div class="cell" role="cell" data-k="' + c.k + '" data-m="' + m + '" style="--c:' + c.c + ';--i:' + (r * 13 + m) + '"></div>').join('')).join('');
function renderHeat() {
  $$('.cell', heat).forEach((el) => {
    const p = M.per.find((x) => x.c.k === el.dataset.k), v = p.surv[+el.dataset.m];
    el.style.setProperty('--t', v.toFixed(3)); el.style.setProperty('--dex-unit-n', Math.round(v * 100));
