  syncInputs(); renderKpis();
  if (view === 'curves') { renderCurves(false); renderSay(); }
  if (view === 'table') renderTable(false);
  if (view === 'ret') renderHeat();
}
const H2 = { curves: 'When does a customer pay back?', table: 'What each channel returns', ret: 'Who stays, and for how long' };
function go(v) {
