}
$('.dex-unit__nav').addEventListener('click', (e) => { const b = e.target.closest('button'); if (b && b.dataset.view !== view) go(b.dataset.view); });
$('.dex-unit__nav').addEventListener('keydown', (e) => {
  const bs = $$('.dex-unit__nav button'), i = bs.indexOf(document.activeElement); if (i < 0) return;
  if (e.key === 'ArrowDown' || e.key === 'ArrowRight') { e.preventDefault(); bs[(i + 1) % bs.length].focus(); }
  if (e.key === 'ArrowUp' || e.key === 'ArrowLeft') { e.preventDefault(); bs[(i + bs.length - 1) % bs.length].focus(); }
});
root.addEventListener('keydown', (e) => { if (e.key === 'Escape') { tip.classList.remove('on'); if (focusK) { focusK = null; renderCurves(false); renderSay(); } } });

/* ------------------------------------------------------------------ mount */
syncInputs(); renderKpis(); renderCurves(true); renderSay(); renderHeat();

if (window.ResizeObserver) {
  const ro = new ResizeObserver(() => {
    if (!root.isConnected) { ro.disconnect(); return; }
    if (view === 'curves' && svg.clientWidth && svg._size !== svg.clientWidth + 'x' + svg.clientHeight) renderCurves(svg.classList.contains('enter'));
  });
