}

css:
.dex-cashbridge {
  --dex-cashbridge-bg: oklch(0.982 0.006 150);
  --dex-cashbridge-ink: oklch(0.27 0.035 210);
  --dex-cashbridge-in: oklch(0.62 0.12 168);
  --dex-cashbridge-out: oklch(0.67 0.15 38);
