  --dex-cashbridge-line: color-mix(in oklch, var(--dex-cashbridge-ink) 12%, transparent);
  --dex-cashbridge-hair: color-mix(in oklch, var(--dex-cashbridge-ink) 7%, transparent);
  --dex-cashbridge-soft: color-mix(in oklch, var(--dex-cashbridge-ink) 5%, transparent);
  --dex-cashbridge-mute: color-mix(in oklch, var(--dex-cashbridge-ink) 63%, var(--dex-cashbridge-bg));
  --dex-cashbridge-faint: color-mix(in oklch, var(--dex-cashbridge-ink) 42%, var(--dex-cashbridge-bg));
  --dex-cashbridge-sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --dex-cashbridge-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --dex-cashbridge-out-e: cubic-bezier(.16, 1, .3, 1);
  --dex-cashbridge-spring: linear(0, .006, .025 2.8%, .101 6.1%, .539 18.9%, .721 25.3%, .849 31.5%, .937 38.1%, .968 41.8%, .991 45.7%, 1.006 50.1%, 1.015 55%, 1.017 63.9%, 1.001);
  width: 100%;
  height: var(--dex-cashbridge-h, 680px);
  container-type: inline-size;
  position: relative; isolation: isolate; overflow: hidden;
  border-radius: 18px;
  background: var(--dex-cashbridge-bg);
