  }
}
.dex-cashbridge__cov {
  margin-top: auto; display: grid; gap: 6px; padding: 14px 8px 0; border-top: 1px solid var(--dex-cashbridge-line); font-size: 12px; color: var(--dex-cashbridge-mute); text-wrap: pretty;
  & b { color: var(--dex-cashbridge-ink); font-variant-numeric: tabular-nums; }
