}
.dex-cashbridge__all {
  display: inline-flex; align-items: center; gap: 7px; padding: 6px 12px; border-radius: 10px; font-size: 12.5px; font-weight: 650; box-shadow: inset 0 0 0 1px var(--dex-cashbridge-line); transition: background-color .2s;
  &:hover { background: var(--dex-cashbridge-soft); }
