}

.dex-cashbridge__view { min-height: 0; }
.dex-cashbridge__view[data-view="bridge"] { display: grid; grid-template-columns: minmax(0, 1fr) 262px; gap: 14px; }
.dex-cashbridge__panel { position: relative; min-width: 0; min-height: 0; border-radius: 16px; background: var(--dex-cashbridge-card); box-shadow: inset 0 0 0 1px var(--dex-cashbridge-line), 0 18px 36px -32px color-mix(in oklch, var(--dex-cashbridge-ink) 70%, transparent); animation: dex-cashbridge-rise .7s var(--dex-cashbridge-out-e) both; animation-delay: calc(var(--i, 0) * 80ms); }
