  &.item .bar { background: color-mix(in oklch, var(--c) 78%, white); }
  &:hover .bar { filter: brightness(1.05) saturate(1.1); }
  & .val { position: absolute; left: -4px; right: -4px; top: 26px; text-align: center; font-size: 11.5px; font-weight: 720; font-variant-numeric: tabular-nums; white-space: nowrap; transform: translateY(calc(var(--vy) * 1px)); transition: transform .65s var(--dex-cashbridge-spring); }
