}
.dex-cashbridge__cols.dense .dex-cashbridge__col.grp .nm::after { display: none; }
.dex-cashbridge__cols.dense { padding-left: 12px; }
.dex-cashbridge__cols.enter .dex-cashbridge__col .bar { animation: dex-cashbridge-drop .9s var(--dex-cashbridge-out-e) both; animation-delay: calc(150ms + var(--i) * 70ms); }
.dex-cashbridge__cols.enter .dex-cashbridge__col.up .bar, .dex-cashbridge__cols.enter .dex-cashbridge__col.tot .bar { animation-name: dex-cashbridge-raise; }
