}

@keyframes dex-cashbridge-rise { from { opacity: 0; transform: translateY(8px); } }
@keyframes dex-cashbridge-fade { from { opacity: 0; } }
@keyframes dex-cashbridge-grow { from { transform: scaleY(0); } }
@keyframes dex-cashbridge-drop { from { clip-path: inset(var(--t) 0 calc(100% - var(--t)) 0 round 4px); } }
@keyframes dex-cashbridge-raise { from { clip-path: inset(calc(100% - var(--b)) 0 var(--b) 0 round 4px); } }

@container (width < 960px) {
  .dex-cashbridge__shell { grid-template-columns: 64px minmax(0, 1fr); }
  .dex-cashbridge__side { align-items: center; padding: 18px 10px; }
  .dex-cashbridge__lbl { display: none; }
  .dex-cashbridge__brand { padding: 0 0 14px; }
  .dex-cashbridge__nav button { padding: 10px; justify-content: center; }
  .dex-cashbridge__view[data-view="bridge"] { grid-template-columns: minmax(0, 1fr) 230px; }
}
@container (width < 760px) {
  .dex-cashbridge__shell { grid-template-columns: minmax(0, 1fr); grid-template-rows: auto minmax(0, 1fr); }
  .dex-cashbridge__side { flex-direction: row; padding: 10px 12px; border-right: 0; border-bottom: 1px solid var(--dex-cashbridge-line); overflow: visible; }
  .dex-cashbridge__brand { padding: 0 6px 0 0; }
  .dex-cashbridge__nav { display: flex; gap: 4px; }
  .dex-cashbridge__main { overflow: auto; padding: 14px; grid-template-rows: auto auto; }
  .dex-cashbridge__view[data-view="bridge"] { grid-template-columns: minmax(0, 1fr); grid-template-rows: 380px max-content; }
  .dex-cashbridge__detail { overflow: visible; }
  .dex-cashbridge__stmt { height: auto; max-height: 480px; }
  .dex-cashbridge__cols { overflow-x: auto; scrollbar-width: none; }
  .dex-cashbridge__col { min-width: 46px; }
}
@container (width < 480px) {
  .dex-cashbridge__col { min-width: 36px; }
  .dex-cashbridge__cols { gap: 4px; }
  .dex-cashbridge__col .nm { font-size: 10px; }
  .dex-cashbridge__col .val { font-size: 10.5px; }
  .dex-cashbridge__table td, .dex-cashbridge__table th { padding-inline: 8px; }
}

@media (prefers-reduced-motion: reduce) {
  .dex-cashbridge__panel, .dex-cashbridge__grid div, .dex-cashbridge__brk button, .dex-cashbridge__table tr.it { animation: none; }
  .dex-cashbridge__cols.enter .dex-cashbridge__col :is(.bar, .val), .dex-cashbridge__mini.enter rect { animation: none; }
  .dex-cashbridge__col :is(.bar, .val, .cn), .dex-cashbridge__cov .g i, .dex-cashbridge__tip { transition: none; }
}

