const RM = !!(window.matchMedia && matchMedia('(prefers-reduced-motion: reduce)').matches);
const $ = (s, el) => (el || root).querySelector(s);
const $$ = (s, el) => Array.from((el || root).querySelectorAll(s));

/* ------------------------------------------------------------------ data ($M by month, Jan-Sep 2026; inflows +, outflows -) */
const MON = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep'];
const MEND = ['31 Jan', '28 Feb', '31 Mar', '30 Apr', '31 May', '30 Jun', '31 Jul', '31 Aug', '30 Sep'];
const OPEN0 = 24.6, COVENANT = 8.0;
const GROUPS = [
  { k: 'rec', name: 'Customer receipts', items: [
    ['hw', 'Hardware receipts', [3.2, 2.8, 4.1, 3.6, 3.9, 4.8, 3.5, 4.2, 5.6]],
    ['raas', 'Robots-as-a-service', [1.4, 1.45, 1.5, 1.58, 1.62, 1.7, 1.78, 1.85, 1.93]],
    ['svc', 'Service and spares', [0.42, 0.4, 0.45, 0.47, 0.44, 0.5, 0.52, 0.49, 0.55]]] },
  { k: 'ops', name: 'Operating payments', items: [
    ['pay', 'Payroll', [-2.9, -2.9, -3.0, -3.05, -3.1, -3.15, -3.2, -3.25, -3.3]],
    ['bom', 'Components', [-2.1, -1.9, -2.6, -2.3, -2.5, -3.0, -2.4, -2.7, -3.4]],
    ['cm', 'Contract assembly', [-0.8, -0.7, -0.95, -0.85, -0.9, -1.1, -0.9, -1.0, -1.25]],
    ['fac', 'Facilities and IT', [-0.45, -0.45, -0.46, -0.46, -0.47, -0.47, -0.48, -0.48, -0.5]],
    ['tax', 'Taxes and duties', [-0.1, -0.12, -0.35, -0.12, -0.11, -0.38, -0.13, -0.12, -0.41]]] },
  { k: 'inv', name: 'Investment', items: [
    ['capex', 'Test cells and tooling', [-0.3, -0.25, -0.6, -0.2, -0.35, -0.9, -0.3, -0.4, -1.1]],
    ['sw', 'Capitalised software', [-0.22, -0.22, -0.23, -0.23, -0.24, -0.24, -0.25, -0.25, -0.26]]] },
  { k: 'fin', name: 'Financing', items: [
    ['debt', 'Venture debt drawn', [0, 0, 0, 0, 0, 5.0, 0, 0, 0]],
    ['int', 'Interest and fees', [-0.05, -0.05, -0.05, -0.05, -0.05, -0.08, -0.09, -0.09, -0.09]],
    ['lease', 'Lease repayments', [-0.12, -0.12, -0.12, -0.12, -0.12, -0.12, -0.12, -0.12, -0.12]]] },
  { k: 'fx', name: 'FX revaluation', items: [['fx', 'FX revaluation', [0.04, -0.06, 0.02, -0.03, 0.05, -0.02, 0.08, -0.04, -0.07]]] }
];
const NOTES = {
  hw: 'Two fleet acceptances at the Duisburg hub released $1.9M of milestone payments in September.',
  raas: 'Subscription receipts grow with the installed fleet: 1,140 robots on contract at 30 September.',
  bom: 'Lidar modules were bought ahead of the Q4 build, about $0.6M earlier than plan.',
  pay: 'Includes the September payroll for 212 people and the Q3 commission run.',
  capex: 'Third test cell commissioned in Lyon; final invoice paid in September.',
  debt: 'The $5.0M second tranche of the venture loan was drawn in June.',
  tax: 'Quarterly VAT settlement falls in the third month of each quarter.',
  cm: 'Assembly partner invoices track units shipped, one month in arrears.'
};
const ITEM = {};
GROUPS.forEach((g) => { g.series = MON.map((_, i) => g.items.reduce((t, it) => t + it[2][i], 0)); g.items.forEach((it) => { ITEM[it[0]] = { k: it[0], name: it[1], v: it[2], g }; }); });
const NET = MON.map((_, i) => GROUPS.reduce((t, g) => t + g.series[i], 0));
const CLOSE = []; NET.reduce((c, n, i) => (CLOSE[i] = c + n), OPEN0);
const PER = { m: { idx: [8], long: 'September 2026', name: 'September' }, q: { idx: [6, 7, 8], long: 'Q3 2026', name: 'the third quarter' }, y: { idx: [0, 1, 2, 3, 4, 5, 6, 7, 8], long: 'Year to date', name: 'the year to date' } };

/* ------------------------------------------------------------------ state */
let per = 'm', view = 'bridge', sel = 'close';
const expanded = new Set();
const sumIdx = (arr) => PER[per].idx.reduce((t, i) => t + arr[i], 0);
const opening = () => (PER[per].idx[0] === 0 ? OPEN0 : CLOSE[PER[per].idx[0] - 1]);
const closing = () => CLOSE[8];
const m$ = (v, sign) => (v < 0 ? '−$' : sign && v > 0 ? '+$' : '$') + Math.abs(v).toFixed(Math.abs(v) < 0.095 && v !== 0 ? 2 : 1) + 'M';
const SHORT = { open: 'Opening', close: 'Closing', rec: 'Receipts', ops: 'Operating', inv: 'Investing', fin: 'Financing', fx: 'FX', hw: 'Hardware', raas: 'RaaS', svc: 'Service', pay: 'Payroll', bom: 'Parts', cm: 'Assembly', fac: 'Facilities', tax: 'Tax', capex: 'Capex', sw: 'Software', debt: 'Debt', int: 'Interest', lease: 'Leases' };
const color = (v, kind) => (kind === 'tot' ? 'var(--dex-cashbridge-ink)' : v >= 0 ? 'var(--dex-cashbridge-in)' : 'var(--dex-cashbridge-out)');

function steps() {
  const out = [{ id: 'open', kind: 'tot', name: 'Opening cash', v: opening() }];
  GROUPS.forEach((g) => {
    if (g.items.length > 1 && expanded.has(g.k)) g.items.forEach((it) => out.push({ id: it[0], kind: 'item', g: g.k, name: it[1], v: sumIdx(it[2]) }));
    else out.push({ id: g.items.length > 1 ? g.k : g.items[0][0], kind: g.items.length > 1 ? 'grp' : 'item', g: g.k, name: g.name, v: sumIdx(g.series) });
  });
  out.push({ id: 'close', kind: 'tot', name: 'Closing cash', v: closing() });
  let run = 0;
  out.forEach((s) => { if (s.kind === 'tot') { s.a = 0; s.b = s.v; run = s.v; } else { s.a = run; s.b = run + s.v; run = s.b; } });
  return out;
}

/* ------------------------------------------------------------------ helpers */
const tip = $('.dex-cashbridge__tip');
function tipAt(x, y) {
  const r = root.getBoundingClientRect(), w = tip.offsetWidth, h = tip.offsetHeight;
  const l = Math.min(Math.max(8, x - r.left + 14), r.width - w - 8);
  let t = y - r.top - h - 12; if (t < 8) t = y - r.top + 18;
  tip.style.translate = Math.round(l) + 'px ' + Math.round(t) + 'px';
}
function niceStep(span, n) { const raw = span / n, mag = Math.pow(10, Math.floor(Math.log10(raw))), e = raw / mag; return (e <= 1 ? 1 : e <= 2 ? 2 : e <= 2.5 ? 2.5 : e <= 5 ? 5 : 10) * mag; }
const X9 = '<svg viewBox="0 0 10 10" aria-hidden="true"><path d="M2 2l6 6M8 2L2 8"/></svg>';

/* ------------------------------------------------------------------ bridge */
const plot = $('[data-plot]'), cols = $('[data-cols]'), grid = $('[data-grid]'), brk = $('[data-brk]');
let lastScale = '';
function renderBridge(enter) {
  const st = steps(), Hp = plot.clientHeight; if (!Hp) return;
  const dense = cols.clientWidth / st.length < 74, NB = dense ? 70 : 46;
  cols.classList.toggle('dense', dense); cols.style.setProperty('--nb', NB + 'px');
  const Ha = Hp - 26 - NB;
  const vals = st.flatMap((s) => [s.a, s.b]);
  const step = niceStep(Math.max(...vals) - Math.min(0, ...vals), 5);
  const lo = Math.min(0, Math.floor(Math.min(...vals) / step) * step), hi = Math.ceil(Math.max(...vals) * 1.06 / step) * step;
  const py = (v) => Ha * (hi - v) / (hi - lo);
  /* grid */
  const sk = lo + ':' + hi + ':' + Hp + ':' + NB;
  if (sk !== lastScale) {
    let g = '';
    for (let v = lo; v <= hi + 1e-9; v += step) g += '<div class="' + (Math.abs(v) < 1e-9 ? 'z' : '') + '" style="--y:' + (26 + py(v)).toFixed(1) + '"><span>$' + (+v.toFixed(1)) + 'M</span></div>';
    grid.innerHTML = g; lastScale = sk;
  }
  /* columns, keyed by id so existing ones transition and new ones FLIP in */
  const before = new Map($$('.dex-cashbridge__col', cols).map((c) => [c.dataset.id, c.getBoundingClientRect()]));
  const keep = new Set(st.map((s) => s.id));
  $$('.dex-cashbridge__col', cols).forEach((c) => { if (!keep.has(c.dataset.id)) c.remove(); });
  st.forEach((s, i) => {
    let c = cols.querySelector('[data-id="' + s.id + '"]');
    if (!c) {
      c = document.createElement('button'); c.type = 'button'; c.className = 'dex-cashbridge__col'; c.dataset.id = s.id; c.tabIndex = -1;
      c.innerHTML = '<span class="bar"></span><span class="val"></span><span class="cn"></span><span class="nm"></span>';
    }
    cols.appendChild(c);
    c.classList.remove('tot', 'grp', 'item', 'up');
    c.classList.add(s.kind); if (s.v >= 0) c.classList.add('up');
    c.style.setProperty('--c', color(s.v, s.kind));
    c.style.setProperty('--i', i);
    c.style.setProperty('--t', ((hi - Math.max(s.a, s.b)) / (hi - lo) * 100).toFixed(3) + '%');
    c.style.setProperty('--b', ((Math.min(s.a, s.b) - lo) / (hi - lo) * 100).toFixed(3) + '%');
    c.style.setProperty('--vy', (py(Math.max(s.a, s.b)) - 17).toFixed(1));
    c.style.setProperty('--cy', py(s.b).toFixed(1));
    c.querySelector('.val').textContent = dense ? (s.kind === 'tot' ? '' : s.v > 0 ? '+' : s.v < 0 ? '−' : '') + Math.abs(s.v).toFixed(Math.abs(s.v) < 0.095 ? 2 : 1) : s.kind === 'tot' ? m$(s.v) : m$(s.v, true);
    c.querySelector('.nm').textContent = dense ? SHORT[s.id] || s.name : s.name;
    c.title = s.name;
    if (s.kind === 'grp') { c.setAttribute('aria-expanded', 'false'); c.setAttribute('aria-label', s.name + ', ' + m$(s.v, true) + '. Expand into lines'); c.removeAttribute('aria-current'); }
    else {
      c.removeAttribute('aria-expanded');
