css:
.dex-risk {
  --dex-risk-bg: oklch(0.185 0.01 260);
  --dex-risk-ink: oklch(0.94 0.01 250);
  --dex-risk-lo: oklch(0.55 0.08 170);
  --dex-risk-mid: oklch(0.8 0.14 85);
  --dex-risk-hi: oklch(0.63 0.2 28);
  --dex-risk-panel: color-mix(in oklch, var(--dex-risk-bg) 90%, var(--dex-risk-ink));
  --dex-risk-deep: color-mix(in oklch, var(--dex-risk-bg) 75%, black);
  --dex-risk-line: color-mix(in oklch, var(--dex-risk-ink) 12%, transparent);
  --dex-risk-soft: color-mix(in oklch, var(--dex-risk-ink) 6%, transparent);
  --dex-risk-mute: color-mix(in oklch, var(--dex-risk-ink) 62%, var(--dex-risk-bg));
  --dex-risk-faint: color-mix(in oklch, var(--dex-risk-ink) 40%, var(--dex-risk-bg));
  --dex-risk-sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --dex-risk-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --dex-risk-out: cubic-bezier(.16, 1, .3, 1);
  --dex-risk-spring: linear(0, .009, .035 2.1%, .141 4.4%, .723 12.9%, .938 16.7%, 1.017 19.4%, 1.067, 1.077 24.3%, 1.065 26.6%, 1.022 31.3%, .997 35.6%, .988 39.5%, .994 47.1%, 1.001);
  width: 100%;
  height: var(--dex-risk-h, 680px);
  container-type: inline-size;
  container-name: dex-risk;
  position: relative; isolation: isolate; overflow: hidden;
  border-radius: 18px;
  background: var(--dex-risk-bg);
  color: var(--dex-risk-ink);
  font: 13px/1.45 var(--dex-risk-sans);
  color-scheme: dark;
  accent-color: var(--dex-risk-mid);
  scrollbar-width: thin;
  scrollbar-color: color-mix(in oklch, var(--dex-risk-ink) 22%, transparent) transparent;
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, h3, p, dl, dd, dt, ul, li) { margin: 0; padding: 0; }
  & :where(ul) { list-style: none; }
  & :where(button) { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; text-align: inherit; }
  & :focus-visible { outline: 2px solid var(--dex-risk-mid); outline-offset: 2px; border-radius: 6px; }
  & [hidden] { display: none !important; }
}
.dex-risk__ic { width: 18px; height: 18px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }
.dex-risk__cap { font-size: 10.5px; font-weight: 650; letter-spacing: .13em; text-transform: uppercase; color: var(--dex-risk-faint); }
.dex-risk__shell { height: 100%; display: grid; grid-template-columns: 210px minmax(0, 1fr); }

.dex-risk__side { display: flex; flex-direction: column; gap: 6px; padding: 20px 12px 16px; min-height: 0; overflow: auto; background: var(--dex-risk-deep); border-right: 1px solid var(--dex-risk-line); }
.dex-risk__brand {
  display: flex; align-items: center; gap: 10px; padding: 0 6px 18px; font-weight: 750; font-size: 15px; letter-spacing: -.02em;
  & svg { width: 30px; height: 30px; flex: none; padding: 5px; border-radius: 9px; background: var(--dex-risk-ink); fill: none; stroke: var(--dex-risk-bg); stroke-width: 1.9; stroke-linecap: round; stroke-linejoin: round; }
  & small { display: block; font-size: 11px; font-weight: 500; letter-spacing: 0; color: var(--dex-risk-mute); }
}
.dex-risk__nav {
  display: grid; gap: 2px; margin-bottom: 12px;
  & button {
    display: flex; align-items: center; gap: 10px; padding: 9px 10px; border-radius: 10px; color: var(--dex-risk-mute); font-weight: 550; transition: background-color .2s, color .2s;
    &:hover { background: var(--dex-risk-soft); color: var(--dex-risk-ink); }
    &[aria-current="page"] { background: var(--dex-risk-soft); color: var(--dex-risk-ink); font-weight: 650; box-shadow: inset 2px 0 0 var(--dex-risk-mid); }
  }
}
.dex-risk__side > .dex-risk__cap { padding: 0 8px 2px; }
.dex-risk__cats {
  display: grid; gap: 1px;
  & button {
    display: flex; align-items: center; gap: 8px; padding: 6px 10px; border-radius: 8px; font-size: 12.5px; color: var(--dex-risk-mute); transition: background-color .2s, color .2s;
    & b { margin-left: auto; font-size: 11px; font-weight: 650; font-variant-numeric: tabular-nums; color: var(--dex-risk-faint); }
    & i { width: 8px; height: 8px; border-radius: 2px; box-shadow: inset 0 0 0 1.5px var(--dex-risk-faint); transition: background-color .2s, box-shadow .2s; }
